class _CustomerServiceScope extends InheritedWidget {
  const _CustomerServiceScope({required this.repository, required this.catalogue, required this.refresh, required super.child});
  final Future<CustomerManagementRepository> Function() repository;
  final Future<CloudCatalogueRepository?> Function() catalogue;
  final Future<void> Function() refresh;
  static _CustomerServiceScope? maybeOf(BuildContext context) => context.dependOnInheritedWidgetOfExactType<_CustomerServiceScope>();
  @override
  bool updateShouldNotify(_CustomerServiceScope oldWidget) => false;
}

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(CrimsonCatalogueStudioApp(repository: await _startupRepository()));
}

Future<LocalCatalogueRepository> _startupRepository() async {
  if (!Platform.isAndroid) return LocalCatalogueRepository();

  try {
    const channel = MethodChannel('com.mycrimson.cataloguestudio/storage');
    final filesDir = await channel.invokeMethod<String>('filesDir');
    final cleanDir = cleanText(filesDir);
    if (cleanDir.isNotEmpty) {
      return LocalCatalogueRepository(
        storeFile: File('$cleanDir/catalogue_store.json'),
      );
    }
  } on Object {
    // Fall through to a writable Android cache fallback.
  }

  return LocalCatalogueRepository(
    storeFile: File('${Directory.systemTemp.path}/catalogue_store.json'),
  );
}

