}

class _LoginScreen extends StatefulWidget {
  const _LoginScreen({
    required this.busy,
    required this.error,
    required this.cloudConfigured,
    required this.hasBiometricUnlock,
    required this.onLogin,
    required this.onBiometricUnlock,
  });

  final bool busy;
  final String error;
  final bool cloudConfigured;
  final bool hasBiometricUnlock;
  final Future<void> Function(String email, String password) onLogin;
  final Future<void> Function() onBiometricUnlock;

  @override
  State<_LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<_LoginScreen> {
  final _email = TextEditingController();
  final _password = TextEditingController();
  bool _obscure = true;

  @override
  void dispose() {
    _email.dispose();
    _password.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _CrimsonColors.background,
      body: SafeArea(
        child: Center(
          child: SingleChildScrollView(
            padding: const EdgeInsets.all(24),
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 440),
              child: _Surface(
                padding: const EdgeInsets.all(28),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    const Center(child: _CrimsonLogoMark(size: 72)),
                    const SizedBox(height: 18),
                    Text(
                      'Welcome to Crimson Decore',
                      textAlign: TextAlign.center,
                      style:
                          Theme.of(context).textTheme.headlineSmall?.copyWith(
                                fontWeight: FontWeight.w900,
                              ),
                    ),
                    const SizedBox(height: 6),
                    Text(
                      'Login to view your live catalogue.',
                      textAlign: TextAlign.center,
                      style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                            color: _CrimsonColors.textSecondary,
                          ),
                    ),
                    const SizedBox(height: 24),
                    TextField(
                      controller: _email,
                      keyboardType: TextInputType.text,
                      textInputAction: TextInputAction.next,
                      decoration: _inputDecoration('User ID or email').copyWith(
                        prefixIcon: const Icon(Icons.mail_outline_rounded),
                      ),
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      controller: _password,
                      obscureText: _obscure,
                      onSubmitted: (_) => _submit(),
                      decoration: _inputDecoration('Password').copyWith(
                        prefixIcon: const Icon(Icons.lock_outline_rounded),
                        suffixIcon: IconButton(
                          onPressed: () => setState(() => _obscure = !_obscure),
                          icon: Icon(
                            _obscure
                                ? Icons.visibility_outlined
                                : Icons.visibility_off_outlined,
                          ),
                        ),
                      ),
                    ),
                    if (widget.error.trim().isNotEmpty) ...[
                      const SizedBox(height: 12),
                      _WarningPanel(message: widget.error),
                    ],
                    const SizedBox(height: 18),
                    FilledButton.icon(
                      onPressed: widget.busy || !widget.cloudConfigured
                          ? null
                          : _submit,
                      icon: widget.busy
                          ? const SizedBox(
                              width: 18,
                              height: 18,
                              child: CircularProgressIndicator(strokeWidth: 2),
                            )
                          : const Icon(Icons.login_rounded),
                      label: Text(widget.busy ? 'Signing in...' : 'Sign In'),
                    ),
                    if (widget.hasBiometricUnlock) ...[
                      const SizedBox(height: 10),
                      OutlinedButton.icon(
                        onPressed: widget.busy || !widget.cloudConfigured
                            ? null
                            : widget.onBiometricUnlock,
                        icon: const Icon(Icons.fingerprint_rounded),
                        label: const Text('Unlock with fingerprint'),
                      ),
                    ],
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  void _submit() {
    final email = cleanText(_email.text);
    final password = _password.text;
    if (email.isEmpty || password.isEmpty) {
      _showMessage(context, 'Enter user ID or email and password.');
      return;
    }
    widget.onLogin(email, password);
  }
}

