class CatalogueHomeScreen extends StatefulWidget {
  const CatalogueHomeScreen({
    super.key,
    this.repository,
    this.enableCloud = true,
  });

  final LocalCatalogueRepository? repository;
  final bool enableCloud;

  @override
  State<CatalogueHomeScreen> createState() => _CatalogueHomeScreenState();
}

class _CatalogueHomeScreenState extends State<CatalogueHomeScreen>
    with WidgetsBindingObserver {
  late final LocalCatalogueRepository _repository;
  late Future<CatalogueState> _catalogueFuture;
  CloudCatalogueRepository? _cloudRepository;
  CloudCatalogueSettings? _cloudSettings;
  CloudAuthRepository? _authRepository;
  CloudAuthSessionStore? _authSessionStore;
  CloudAuthSession? _authSession;
  CloudAuthSession? _savedSessionForUnlock;
  CrimsonProfile? _profile;
  bool _authChecking = true;
  bool _authBusy = false;
  bool _biometricAvailable = false;
  String _authError = '';
  CloudSyncStatus _cloudStatus = const CloudSyncStatus.localOnly();
  bool _cloudSessionRefreshFailed = false;
  _CatalogueSection _section = _CatalogueSection.dashboard;
  final List<_CatalogueSection> _sectionHistory = [];
  VoidCallback? _sectionBackHandler;
  String? _selectedProductId;
  String _pendingProductCategory = '';
  String _pendingProductSubcategory = '';
  ProductDraft? _editingProduct;
  final List<CustomerOrderItemDraft> _customerCartItems = [];
  CustomerOrderDraft? _editingCustomerOrder;
  Timer? _cloudRefreshTimer;
  bool _backgroundRefreshInProgress = false;
  int _cloudWritesInProgress = 0;
  AppLifecycleState _lifecycleState = AppLifecycleState.resumed;
  final LocalAuthentication _localAuth = LocalAuthentication();
  CatalogueState? _lastStockSource;

  void _publishStockSnapshot(CatalogueState? state) {
    if (identical(_lastStockSource, state)) return;
    _lastStockSource = state;
    final next = state == null ? null : LiveStockSnapshot.fromState(state);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && identical(_lastStockSource, state)) {
        _liveStockSnapshot.value = next;
      }
    });
  }

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _repository = widget.repository ?? LocalCatalogueRepository();
    _catalogueFuture = Future.value(const CatalogueState());
    unawaited(_bootstrapAuth());
    if (widget.enableCloud) {
      _cloudRefreshTimer = Timer.periodic(
        const Duration(seconds: 15),
        (_) => unawaited(_refreshCatalogueSilently()),
      );
    }
  }

  @override
  void dispose() {
    _cloudRefreshTimer?.cancel();
    WidgetsBinding.instance.removeObserver(this);
    _liveStockSnapshot.value = null;
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    _lifecycleState = state;
    if (state == AppLifecycleState.resumed) {
      unawaited(_refreshCatalogueSilently());
    }
  }

  Future<void> _bootstrapAuth() async {
    if (!widget.enableCloud) {
      if (!mounted) return;
      setState(() {
        _profile = const CrimsonProfile.localAdmin();
        _authChecking = false;
        _catalogueFuture = _loadCatalogueForDisplay();
      });
      return;
    }

    try {
      final settings = await CloudCatalogueSettings.load();
      const store = CloudAuthSessionStore();
      if (!mounted) return;
      setState(() {
        _cloudSettings = settings;
        _authSessionStore = store;
        _authRepository = settings == null || !settings.isConfigured
            ? null
            : CloudAuthRepository(settings);
      });
      if (settings == null || !settings.isConfigured) {
        setState(() {
          _authChecking = false;
          _authError =
              'Cloud setup missing. Add Supabase URL and anon key before login.';
        });
        return;
      }
      final savedSession = await store.load();
      final biometricAvailable =
          savedSession != null && await _canUseBiometricUnlock();
      if (mounted) {
        setState(() {
          _savedSessionForUnlock = savedSession;
          _biometricAvailable = biometricAvailable;
          _authChecking = false;
        });
      }
      return;
    } on Object catch (error) {
      if (!mounted) return;
      await _authSessionStore?.clear();
      setState(() {
        _authSession = null;
        _savedSessionForUnlock = null;
        _biometricAvailable = false;
        _profile = null;
        _authChecking = false;
        _authError = error.toString();
        _cloudStatus = const CloudSyncStatus.localOnly();
      });
    }
  }

  Future<bool> _canUseBiometricUnlock() async {
    if (!Platform.isAndroid && !Platform.isIOS) return false;
    try {
      return await _localAuth.isDeviceSupported();
    } on Object {
      return false;
    }
  }

  Future<void> _handleBiometricUnlock() async {
    final auth = _authRepository;
    final session = _savedSessionForUnlock;
    if (auth == null || session == null) {
      setState(() => _authError = 'Login once with email and password first.');
      return;
    }
    setState(() {
      _authBusy = true;
      _authError = '';
    });
    try {
      final allowed = await _localAuth.authenticate(
        localizedReason: 'Unlock Crimson Decore catalogue',
        options: const AuthenticationOptions(
          stickyAuth: true,
          biometricOnly: false,
        ),
      );
      if (!allowed) {
        if (!mounted) return;
        setState(() => _authBusy = false);
        return;
      }
      final usableSession =
          session.expiresSoon ? await auth.refresh(session) : session;
      await _adoptSession(usableSession, save: true);
    } on Object catch (error) {
      if (!mounted) return;
      setState(() {
        _authError = 'Fingerprint unlock failed: $error';
        _authBusy = false;
      });
    }
  }

  Future<void> _handleLogin(String email, String password) async {
    final auth = _authRepository;
    final store = _authSessionStore;
    if (auth == null || store == null) {
      setState(() {
        _authError =
            'Cloud setup missing. Please add Supabase configuration first.';
      });
      return;
    }
    setState(() {
      _authBusy = true;
      _authError = '';
    });
    try {
      final session = await auth.signIn(email: customerLoginEmail(email), password: password);
      await _adoptSession(session, save: true);
    } on Object catch (error) {
      if (!mounted) return;
      setState(() {
        _authError = error.toString();
        _authBusy = false;
      });
    }
  }

  Future<void> _adoptSession(
    CloudAuthSession session, {
    required bool save,
  }) async {
    final auth = _authRepository;
    final store = _authSessionStore;
    if (auth == null || store == null) return;
    final profile = await auth.fetchProfile(session);
    if (save) await store.save(session);
    if (!mounted) return;
    setState(() {
      _authSession = session;
      _savedSessionForUnlock = session;
      _biometricAvailable = false;
      _profile = profile;
      _cloudSessionRefreshFailed = false;
      _cloudRepository = _cloudSettings == null
          ? null
          : CloudCatalogueRepository(
              _cloudSettings!,
              accessToken: session.accessToken,
              customerSafe: profile.role == CrimsonUserRole.customer,
            );
      _authChecking = false;
      _authBusy = false;
      _authError = '';
      _catalogueFuture = _loadCatalogueForDisplay();
    });
  }

  Future<void> _handleLogout() async {
    final session = _authSession;
    if (session != null) {
      await _authRepository?.signOut(session);
    }
    await _authSessionStore?.clear();
    if (!mounted) return;
    setState(() {
      _authSession = null;
      _savedSessionForUnlock = null;
      _biometricAvailable = false;
      _profile = null;
      _cloudSessionRefreshFailed = false;
      _cloudRepository = null;
      _selectedProductId = null;
      _pendingProductCategory = '';
      _pendingProductSubcategory = '';
      _editingProduct = null;
      _section = _CatalogueSection.dashboard;
      _sectionHistory.clear();
      _sectionBackHandler = null;
      _catalogueFuture = Future.value(const CatalogueState());
      _cloudStatus = const CloudSyncStatus.localOnly();
    });
  }

  bool get _canManageCatalogue => _profile?.canManageCatalogue ?? false;

  bool _requireAdminAccess() {
    if (_canManageCatalogue) return true;
    if (mounted) {
      _showMessage(context, 'Admin access required for catalogue changes.');
    }
    return false;
  }

  Future<void> _verifyResetAdminCredentials({
    required String email,
    required String password,
  }) async {
    if (!_requireAdminAccess()) {
      throw StateError('Admin access required for catalogue reset.');
    }
    final auth = _authRepository;
    final currentSession = _authSession;
    if (widget.enableCloud && (auth == null || currentSession == null)) {
      throw StateError('Cloud login is required before catalogue reset.');
    }
    if (!widget.enableCloud) return;
    final session = await auth!.signIn(email: email, password: password);
    final profile = await auth.fetchProfile(session);
    if (!profile.canManageCatalogue) {
      throw StateError('This login is not an admin account.');
    }
    if (session.userId != currentSession!.userId) {
      throw StateError(
          'Use the same admin account that is currently signed in.');
    }
  }

  Future<void> _resetCatalogueData(CatalogueState cleanState) async {
    if (!_requireAdminAccess()) return;
    final state =
        cleanState.copyWith(updatedAt: DateTime.now().toIso8601String());
    final cloud = await _cloud();
    if (widget.enableCloud && cloud == null) {
      throw StateError('Cloud is not available. Reset was not applied.');
    }

    _cloudWritesInProgress++;
    if (cloud != null) _setCloudStatus(const CloudSyncStatus.saving());
    try {
      CatalogueState published = state;
      if (cloud != null) {
        final remote = await cloud.pull();
        published = await cloud.push(state, previousState: remote);
      }
      await _repository.save(published);
      if (!mounted) return;
      setState(() {
        _selectedProductId = null;
        _pendingProductCategory = '';
        _pendingProductSubcategory = '';
        _editingProduct = null;
        _section = _CatalogueSection.studioTools;
        _sectionHistory.clear();
        _sectionBackHandler = null;
        _catalogueFuture = Future.value(published);
      });
      _setCloudStatus(cloud == null
          ? const CloudSyncStatus.localOnly()
          : const CloudSyncStatus.saved());
    } on Object {
      _setCloudStatus(const CloudSyncStatus.offlinePending());
      rethrow;
    } finally {
      _cloudWritesInProgress--;
    }
  }

  Future<CatalogueState> _loadCatalogueForDisplay() async {
    final state = await _loadCatalogue(includeCloud: false);
    if (widget.enableCloud) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          unawaited(_refreshCatalogueSilently(force: true));
        }
      });
    }
    return state;
  }

  Future<CatalogueState> _loadCatalogue({bool includeCloud = true}) async {
    var state = await _repository.load();
    if (_profile?.role == CrimsonUserRole.customer) {
      // A device may have cached another account's data. Only the protected
      // order endpoint may populate a customer order list for this session.
      state = state.copyWith(customerOrders: const [], stockVouchers: const [], stockItems: const []);
    }
    final reconciledLocal = reconcileSimplePluralCategoryAliases(state);
    if (!_sameCatalogue(reconciledLocal, state)) {
      await _repository.save(reconciledLocal);
      state = await _repository.load();
    }
    final cloud = includeCloud ? await _cloud() : null;
    if (cloud != null) {
      try {
        final remote = await cloud.pull();
        if (remote != null) {
          final preferRemote = _profile?.role == CrimsonUserRole.customer || Platform.isAndroid ||
              _isRemoteNewer(remote, state) ||
              _isSampleCatalogue(state) ||
              (_hasCloudImages(remote) && !_hasCloudImages(state));
          final merged = _mergeCatalogueStates(
            local: state,
            remote: remote,
            preferLocal: !preferRemote,
            authoritativeStructure: preferRemote,
          );
          if (!_sameCatalogue(merged, state)) {
            await _repository.save(merged);
            state = merged;
          }
          if (_canManageCatalogue &&
              (!_sameCatalogue(merged, remote) ||
                  cloud.lastPullHadDuplicateProductIds)) {
            final published = await cloud.push(
              merged,
              previousState: remote,
            );
            await _repository.save(published);
            state = published;
          }
        } else if (_canManageCatalogue &&
            _shouldPublishInitialCatalogue(state)) {
          final published = await cloud.push(state);
          await _repository.save(published);
          state = published;
        }
        try {
          final cloudOrders = await cloud.pullCustomerOrders();
          if (cloudOrders.isNotEmpty || _profile?.role == CrimsonUserRole.customer) {
            state = state.copyWith(
              customerOrders: _profile?.role == CrimsonUserRole.customer ? visibleOrdersForCustomer(cloudOrders, _authSession?.userId ?? '') : _mergeCustomerOrderDraftLists(
                state.customerOrders,
                cloudOrders,
              ),
            );
            await _repository.save(state);
          }
        } on CloudCatalogueException {
          // Older Supabase projects may not have the separate order table yet.
        }
        _setCloudStatus(const CloudSyncStatus.updated());
      } on Object {
        _setCloudStatus(const CloudSyncStatus.offlinePending());
      }
    } else {
      _setCloudStatus(_cloudSessionRefreshFailed
          ? const CloudSyncStatus.offlinePending()
          : const CloudSyncStatus.localOnly());
    }
    final activeProducts = _profile == null
        ? state.products.where((product) => !product.isArchived).toList()
        : _activeProductsForRole(state, _profile!);
    if (_selectedProductId == null && activeProducts.isNotEmpty) {
      _selectedProductId = activeProducts.first.id;
    }
    return state;
  }

  Future<void> _refreshCatalogue() async {
    await _ensureFreshAuthSession(force: true);
    await _refreshCatalogueSilently(force: true);
  }

  Future<void> _refreshCatalogueSilently({bool force = false}) async {
    if (!mounted || _backgroundRefreshInProgress || _profile == null) return;
    if (!force && _lifecycleState != AppLifecycleState.resumed) return;
    if (_cloudWritesInProgress > 0) return;

    _backgroundRefreshInProgress = true;
    try {
      CatalogueState? visibleState;
      try {
        visibleState = await _catalogueFuture;
      } on Object {
        // A fresh cloud pull below can recover a failed initial/local load.
      }

      final refreshed = await _loadCatalogue();
      if (!mounted) return;
      if (visibleState == null || !_sameCatalogue(refreshed, visibleState)) {
        setState(() => _catalogueFuture = Future.value(refreshed));
      }
    } finally {
      _backgroundRefreshInProgress = false;
    }
  }

  Future<void> _saveProduct(ProductDraft product) async {
    if (!_requireAdminAccess()) return;
    final nextState = await _repository.upsertProduct(product);
    final savedProduct = nextState.products.firstWhere(
      (item) => _sameName(item.name, product.name),
      orElse: () => product,
    );
    setState(() {
      _selectedProductId = savedProduct.id;
      _section = _CatalogueSection.products;
      _editingProduct = null;
      _catalogueFuture = Future.value(nextState);
    });
    _pushCloud(nextState, authoritativeProductId: savedProduct.id);
  }

  Future<void> _archiveProduct(ProductDraft product) async {
    if (!_requireAdminAccess()) return;
    final nextState = await _repository.archiveProduct(product.id);
    final activeProducts =
        nextState.products.where((item) => !item.isArchived).toList();
    setState(() {
      _selectedProductId =
          activeProducts.isEmpty ? null : activeProducts.first.id;
      _editingProduct = null;
      _section = _CatalogueSection.products;
      _catalogueFuture = Future.value(nextState);
    });
    _pushCloud(nextState);
  }

  Future<void> _restoreProduct(ProductDraft product) async {
    if (!_requireAdminAccess()) return;
    final nextState = await _repository.restoreProduct(product.id);
    setState(() {
      _selectedProductId = product.id;
      _editingProduct = null;
      _section = _CatalogueSection.products;
      _catalogueFuture = Future.value(nextState);
    });
    _pushCloud(nextState);
  }

  Future<void> _setProductPublished(
    ProductDraft product,
    bool isPublished,
  ) async {
    await _setProductsPublished({product.id}, isPublished);
  }

  Future<void> _setProductsPublished(
    Set<String> productIds,
    bool isPublished,
  ) async {
    if (!_requireAdminAccess()) return;
    final ids = productIds.map(cleanText).where((id) => id.isNotEmpty).toSet();
    if (ids.isEmpty) return;
    final current = await _catalogueFuture;
    final selectedProducts =
        current.products.where((product) => ids.contains(product.id)).toList();
    if (selectedProducts.isEmpty) return;
    final blockedIds = isPublished
        ? selectedProducts
            .where((product) =>
                product.isComingSoon && !_comingSoonProductIsReady(product))
            .map((product) => product.id)
            .toSet()
        : <String>{};
    final activeIds = ids.difference(blockedIds);
    if (blockedIds.isNotEmpty && mounted) {
      _showMessage(context,
          '${blockedIds.length} Coming Soon product(s) need a real name, category, subcategory and at least one priced variation before going live.');
    }
    if (activeIds.isEmpty) return;
    final activeProducts = selectedProducts
        .where((product) => activeIds.contains(product.id))
        .toList();

    var categories = List<CategoryDraft>.from(current.categories);
    if (isPublished) {
      for (final product in activeProducts) {
        final categoryName = cleanText(product.category);
        final subcategoryName = cleanText(product.subcategory);
        if (categoryName.isEmpty) continue;
        var categoryExists = false;
        categories = categories.map((category) {
          if (!_sameName(category.name, categoryName)) return category;
          categoryExists = true;
          final subcategories = [...category.subcategories];
          if (subcategoryName.isNotEmpty &&
              !subcategories.any((item) => _sameName(item, subcategoryName))) {
            subcategories.add(subcategoryName);
          }
          final subcategoryPublished =
              Map<String, bool>.from(category.subcategoryPublished);
          if (subcategoryName.isNotEmpty) {
            subcategoryPublished[subcategoryName] = true;
          }
          return category.copyWith(
            isPublished: true,
            subcategories: subcategories,
            subcategoryPublished: subcategoryPublished,
          );
        }).toList();
        if (!categoryExists) {
          categories.add(
            CategoryDraft(
              name: categoryName,
              subcategories:
                  subcategoryName.isEmpty ? const [] : [subcategoryName],
              isPublished: true,
              subcategoryPublished:
                  subcategoryName.isEmpty ? const {} : {subcategoryName: true},
            ),
          );
        }
      }
    }
    final nextState = current.copyWith(
      products: current.products
          .map((item) => activeIds.contains(item.id)
              ? item.copyWith(
                  isPublished: isPublished,
                  isComingSoon: false,
                )
              : item)
          .toList(),
      categories: categories,
    );
    await _repository.save(nextState);
    setState(() {
      if (activeIds.length == 1) _selectedProductId = activeIds.first;
      _catalogueFuture = Future.value(nextState);
    });
    unawaited(_pushCloud(
      nextState,
      authoritativeProductId: activeIds.length == 1 ? activeIds.first : null,
      authoritativeStructure: isPublished,
    ));
  }

  Future<void> _saveCategories(List<CategoryDraft> categories) async {
    if (!_requireAdminAccess()) return;
    final current = await _catalogueFuture;
    final nextState = current.copyWith(categories: categories);
    await _repository.save(nextState);
    setState(() {
      _catalogueFuture = Future.value(nextState);
    });
    _pushCloud(nextState, authoritativeStructure: true);
  }

  Future<void> _saveBrands(List<String> brands) async {
    if (!_requireAdminAccess()) return;
    final current = await _catalogueFuture;
    final nextState = current.copyWith(brands: brands);
    await _repository.save(nextState);
    setState(() {
      _catalogueFuture = Future.value(nextState);
    });
    _pushCloud(nextState, authoritativeStructure: true);
  }

  Future<void> _saveCatalogueStructure(CatalogueState nextState) async {
    if (!_requireAdminAccess()) return;
    final previousState = await _catalogueFuture;
    final previousOrders = {
      for (final order in previousState.customerOrders) order.id: order,
    };
    final changedOrders = [
      for (final order in nextState.customerOrders)
        if (previousOrders[order.id] == null ||
            !_sameCustomerOrderDraft(previousOrders[order.id]!, order))
          order,
    ];
    // A new linked order must reach its protected store before it is treated
    // as saved locally; otherwise a retry could silently skip cloud creation.
    if (widget.enableCloud) {
      await _syncCustomerOrdersToCloud(changedOrders.where((o) => o.customerType == 'regular' || o.customerType == 'retail').toList());
    }
    await _repository.save(nextState);
    final saved = await _repository.load();
    setState(() => _catalogueFuture = Future.value(saved));
    await _syncCustomerOrdersToCloud([
      for (final order in changedOrders)
        if (order.customerType != 'regular' && order.customerType != 'retail')
          order,
    ]);
    final synced = await _pushCloud(saved, authoritativeStructure: true);
    if (widget.enableCloud && !synced) {
      throw StateError(
          'Saved locally, but cloud sync did not complete. Check the sync status and try again.');
    }
  }

  Future<File> _resolvePhotoInboxImage(String path) async {
    if (!path.startsWith('http://') && !path.startsWith('https://')) {
      return File(path);
    }
    final cloud = await _cloud();
    if (cloud == null) throw StateError('Cloud is unavailable for this photo.');
    return cloud.resolvePhotoInboxImage(path);
  }

  Future<bool> _photoInboxCloudReady() async {
    if (!widget.enableCloud) return true;
    final cloud = await _cloud();
    return cloud != null && await cloud.isPhotoInboxReady();
  }

  Future<void> _importBulkPaste(BulkPasteImportResult result) async {
    if (!_requireAdminAccess()) return;
    final nextState = await _repository.importProducts(
      incomingProducts: result.products,
      incomingCategories: result.categories,
    );
    setState(() {
      if (result.products.isNotEmpty) {
        final importedName = result.products.first.name;
        _selectedProductId = nextState.products
            .firstWhere((product) => _sameName(product.name, importedName),
                orElse: () => nextState.products.first)
            .id;
      }
      _section = _CatalogueSection.products;
      _catalogueFuture = Future.value(nextState);
    });
    _pushCloud(nextState);
  }

  Future<void> _restoreCatalogueBackup(CatalogueState restored) async {
    if (!_requireAdminAccess()) return;
    await _repository.save(restored);
    final nextState = await _repository.load();
    final activeProducts =
        nextState.products.where((product) => !product.isArchived).toList();
    setState(() {
      _selectedProductId =
          activeProducts.isEmpty ? null : activeProducts.first.id;
      _editingProduct = null;
      _section = _CatalogueSection.studioTools;
      _catalogueFuture = Future.value(nextState);
    });
    _pushCloud(nextState);
  }

  Future<CloudCatalogueRepository?> _cloud() async {
    if (!widget.enableCloud) return null;
    if (_profile?.canViewProducts != true || _authSession == null) return null;
    final session = await _ensureFreshAuthSession();
    if (session == null) return null;
    final token = session.accessToken;
    if (_cloudRepository != null) {
      _cloudRepository!.setAccessToken(token);
      return _cloudRepository;
    }
    final settings = _cloudSettings ?? await CloudCatalogueSettings.load();
    if (settings == null || !settings.isConfigured) return null;
    _cloudSettings = settings;
    return _cloudRepository = CloudCatalogueRepository(
      settings,
      accessToken: token,
      customerSafe: _profile?.role == CrimsonUserRole.customer,
    );
  }

  Future<CloudAuthSession?> _ensureFreshAuthSession({
    bool force = false,
  }) async {
    if (!widget.enableCloud) return _authSession;
    final auth = _authRepository;
    final store = _authSessionStore;
    final session = _authSession;
    if (auth == null || session == null) return null;
    if (!force && !session.expiresSoon) {
      _cloudSessionRefreshFailed = false;
      return session;
    }

    try {
      final refreshed = await auth.refresh(session);
      if (store != null) await store.save(refreshed);
      _cloudRepository?.setAccessToken(refreshed.accessToken);
      _cloudSessionRefreshFailed = false;
      if (mounted) {
        setState(() {
          _authSession = refreshed;
          _savedSessionForUnlock = refreshed;
        });
      } else {
        _authSession = refreshed;
        _savedSessionForUnlock = refreshed;
      }
      return refreshed;
    } on Object {
      _cloudSessionRefreshFailed = true;
      _setCloudStatus(const CloudSyncStatus.offlinePending());
      return null;
    }
  }

  Future<CustomerManagementRepository> _customerManagement() async {
    final session = await _ensureFreshAuthSession();
    final settings = _cloudSettings;
    if (session == null || settings == null || !_canManageCatalogue) {
      throw StateError('Sign in as an admin to manage customers.');
    }
    return CustomerManagementRepository(settings: settings, session: session);
  }

  Future<void> _syncCustomerOrdersToCloud(
    List<CustomerOrderDraft> orders,
  ) async {
    if (orders.isEmpty) return;
    for (final order in orders) {
      final saved = await _saveCustomerOrderToCloud(order);
      if (widget.enableCloud && saved == null &&
          (order.customerType == 'regular' || order.customerType == 'retail')) {
        throw StateError('Order saved on this device, but the secure order service did not save it. Check the connection before continuing.');
      }
    }
  }

  Future<CustomerOrderDraft?> _saveCustomerOrderToCloud(
    CustomerOrderDraft order, {
    bool assignServerNumber = false,
  }) async {
    final cloud = await _cloud();
    final session = _authSession;
    if (cloud == null || session == null) return null;
    try {
      return await cloud.saveCustomerOrder(
        order,
        userId: _canManageCatalogue && order.customerType == 'regular' && order.customerAccountId.isNotEmpty ? order.customerAccountId : session.userId,
        email: session.email,
        assignServerNumber: assignServerNumber,
      );
    } on CloudCatalogueException {
      return null;
    } on Object {
      _setCloudStatus(const CloudSyncStatus.offlinePending());
      return null;
    }
  }

  Future<CatalogueState> _stateWithCloudCustomerOrders(
    CatalogueState state,
  ) async {
    final cloud = await _cloud();
    if (cloud == null) return state;
    try {
      final cloudOrders = await cloud.pullCustomerOrders();
      if (_profile?.role == CrimsonUserRole.customer) {
        return state.copyWith(customerOrders: visibleOrdersForCustomer(cloudOrders, _authSession?.userId ?? ''));
      }
      if (cloudOrders.isEmpty) return state;
      return state.copyWith(
        customerOrders: _mergeCustomerOrderDraftLists(
          state.customerOrders,
          cloudOrders,
        ),
      );
    } on CloudCatalogueException {
      return state;
    } on Object {
      _setCloudStatus(const CloudSyncStatus.offlinePending());
      return state;
    }
  }

  Future<bool> _pushCloud(
    CatalogueState state, {
    String? authoritativeProductId,
    bool authoritativeStructure = false,
  }) async {
    if (!_canManageCatalogue) return false;
    final cloud = await _cloud();
    if (cloud == null) {
      _setCloudStatus(_cloudSessionRefreshFailed
          ? const CloudSyncStatus.offlinePending()
          : const CloudSyncStatus.localOnly());
      return false;
    }
    _cloudWritesInProgress++;
    _setCloudStatus(const CloudSyncStatus.saving());
    try {
      final remote = await cloud.pull();
      final merged = remote == null
          ? state
          : _mergeCatalogueStates(
              local: state,
              remote: remote,
              preferLocal: true,
              authoritativeProductId: authoritativeProductId,
              authoritativeStructure: authoritativeStructure,
            );
      final published = await cloud.push(
        merged,
        previousState: remote,
      );
      await _repository.save(published);
      if (mounted) {
        setState(() => _catalogueFuture = Future.value(published));
      }
      _setCloudStatus(const CloudSyncStatus.saved());
      return true;
    } on Object {
      _setCloudStatus(const CloudSyncStatus.offlinePending());
      return false;
    } finally {
      _cloudWritesInProgress--;
    }
  }

  void _setCloudStatus(CloudSyncStatus status) {
    if (!mounted) return;
    setState(() => _cloudStatus = status);
  }

  bool _isRemoteNewer(CatalogueState remote, CatalogueState local) {
    final remoteTime = DateTime.tryParse(remote.updatedAt);
    final localTime = DateTime.tryParse(local.updatedAt);
    if (remoteTime == null) return false;
    if (localTime == null) return true;
    return remoteTime.isAfter(localTime);
  }

  bool _isSampleCatalogue(CatalogueState state) {
    if (state.products.isEmpty || state.products.length > 3) return false;
    return state.products.every((product) => product.id.startsWith('sample-'));
  }

  bool _shouldPublishInitialCatalogue(CatalogueState state) {
    if (Platform.isAndroid || _isSampleCatalogue(state)) return false;
    return state.products.isNotEmpty;
  }

  bool _hasCloudImages(CatalogueState state) {
    for (final product in state.products) {
      for (final path in [...product.imagePaths, product.imagePath]) {
        if (_isNetworkImagePath(cleanText(path))) return true;
      }
    }
    for (final category in state.categories) {
      if (_isNetworkImagePath(cleanText(category.imagePath))) return true;
      for (final path in category.subcategoryImages.values) {
        if (_isNetworkImagePath(cleanText(path))) return true;
      }
    }
    for (final path in state.brandImages.values) {
      if (_isNetworkImagePath(cleanText(path))) return true;
    }
    for (final path in state.bannerImagePaths) {
      if (_isNetworkImagePath(cleanText(path))) return true;
    }
    return false;
  }

  CatalogueState _mergeCatalogueStates({
    required CatalogueState local,
    required CatalogueState remote,
    required bool preferLocal,
    String? authoritativeProductId,
    bool authoritativeStructure = false,
  }) {
    final localReset = cleanText(local.resetGeneration);
    final remoteReset = cleanText(remote.resetGeneration);
    if (remoteReset.isNotEmpty && localReset != remoteReset) {
      if (localReset.isEmpty) {
        return remote;
      }
      final remoteTime = DateTime.tryParse(remote.updatedAt);
      final localTime = DateTime.tryParse(local.updatedAt);
      if (remoteTime != null &&
          localTime != null &&
          remoteTime.isAfter(localTime)) {
        return remote;
      }
    }

    final primaryProducts = preferLocal ? local.products : remote.products;
    final secondaryProducts = preferLocal ? remote.products : local.products;
    final products = <ProductDraft>[...primaryProducts];

    for (final secondary in secondaryProducts) {
      final index = _findProductIndex(
        products,
        secondary,
        allowIdOnlyMatch: authoritativeProductId != null &&
            secondary.id == authoritativeProductId,
      );
      if (index < 0) {
        products.add(secondary);
        continue;
      }
      products[index] = _mergeProductDrafts(
        primary: products[index],
        secondary: secondary,
        primaryImagesAreAuthoritative: !preferLocal ||
            (authoritativeProductId != null &&
                products[index].id == authoritativeProductId),
      );
    }

    final primaryCategories =
        preferLocal ? local.categories : remote.categories;
    final secondaryCategories =
        preferLocal ? remote.categories : local.categories;
    final primaryBrandImages =
        preferLocal ? local.brandImages : remote.brandImages;

    final categories = authoritativeStructure
        ? [
            for (final category in primaryCategories)
              category.copyWith(
                name: cleanText(category.name),
                subcategories: _uniqueDropdownValues(category.subcategories),
                keywords: _uniqueDropdownValues(category.keywords),
              ),
          ]
        : _mergeCategoryDraftLists(primaryCategories, secondaryCategories);
    final primaryBrands = preferLocal ? local.brands : remote.brands;

    return reconcileSimplePluralCategoryAliases(CatalogueState(
      products: products,
      photoInbox: _mergePhotoInboxDrafts(
        preferLocal ? local.photoInbox : remote.photoInbox,
        preferLocal ? remote.photoInbox : local.photoInbox,
      ),
      categories: categories,
      brands: authoritativeStructure
          ? _uniqueDropdownValues(primaryBrands)
          : _uniqueDropdownValues([...local.brands, ...remote.brands]),
      brandImages: primaryBrandImages,
      bannerImagePaths: preferLocal
          ? _uniqueImagePaths(local.bannerImagePaths)
          : _uniqueImagePaths(remote.bannerImagePaths),
      stockVouchers: _mergeStockVoucherDraftLists(
        preferLocal ? local.stockVouchers : remote.stockVouchers,
        preferLocal ? remote.stockVouchers : local.stockVouchers,
      ),
      stockItems: _mergeStockItemDraftLists(
        preferLocal ? local.stockItems : remote.stockItems,
        preferLocal ? remote.stockItems : local.stockItems,
      ),
      customerOrders: _mergeCustomerOrderDraftLists(
        preferLocal ? local.customerOrders : remote.customerOrders,
        preferLocal ? remote.customerOrders : local.customerOrders,
      ),
      customerStockStatuses: preferLocal ? local.customerStockStatuses : remote.customerStockStatuses,
      searchTerminology:
          preferLocal ? local.searchTerminology : remote.searchTerminology,
      resetGeneration: localReset.isNotEmpty ? localReset : remoteReset,
      updatedAt: DateTime.now().toIso8601String(),
    ));
  }

  List<PhotoInboxDraft> _mergePhotoInboxDrafts(
      List<PhotoInboxDraft> primary, List<PhotoInboxDraft> secondary) {
    final result = <PhotoInboxDraft>[...primary];
    for (final draft in secondary) {
      final index = result.indexWhere((item) => item.id == draft.id);
      if (index < 0) {
        result.add(draft);
      } else if (draft.isConverted && !result[index].isConverted) {
        result[index] = draft;
      } else if (draft.mergedIntoDraftId.isNotEmpty &&
          result[index].mergedIntoDraftId.isEmpty) {
        result[index] = draft;
      }
    }
    return result;
  }

  List<StockItemDraft> _mergeStockItemDraftLists(
    List<StockItemDraft> first,
    List<StockItemDraft> second,
  ) {
    final result = <StockItemDraft>[];
    for (final item in [...first, ...second]) {
      final id = cleanText(item.id);
      if (id.isEmpty) continue;
      final index = result.indexWhere((row) => row.id == id);
      if (index < 0) {
        result.add(item);
      } else {
        result[index] = item;
      }
    }
    result.sort((left, right) => _compareUiText(
          left.displayProductName,
          right.displayProductName,
        ));
    return result;
  }

  List<StockVoucherDraft> _mergeStockVoucherDraftLists(
    List<StockVoucherDraft> first,
    List<StockVoucherDraft> second,
  ) {
    final result = <StockVoucherDraft>[];
    for (final voucher in [...first, ...second]) {
      final id = cleanText(voucher.id);
      if (id.isEmpty) continue;
      final index = result.indexWhere((item) => item.id == id);
      if (index < 0) {
        result.add(voucher);
      } else {
        result[index] = voucher;
      }
    }
    result.sort((left, right) => right.date.compareTo(left.date));
    return result;
  }

  List<CustomerOrderDraft> _mergeCustomerOrderDraftLists(
    List<CustomerOrderDraft> first,
    List<CustomerOrderDraft> second,
  ) {
    final result = <CustomerOrderDraft>[];
    for (final order in [...first, ...second]) {
      final id = cleanText(order.id);
      if (id.isEmpty) continue;
      final index = result.indexWhere((item) => item.id == id);
      if (index < 0) {
        result.add(order);
      } else {
        final existingTime = DateTime.tryParse(result[index].updatedAt);
        final incomingTime = DateTime.tryParse(order.updatedAt);
        result[index] = incomingTime != null &&
                (existingTime == null || incomingTime.isAfter(existingTime))
            ? order
            : result[index];
      }
    }
    result.sort((left, right) => right.createdAt.compareTo(left.createdAt));
    return result;
  }

  ProductDraft _mergeProductDrafts({
    required ProductDraft primary,
    required ProductDraft secondary,
    bool primaryImagesAreAuthoritative = false,
  }) {
    final primaryHasNewerImages =
        primary.imageRevision > secondary.imageRevision;
    final secondaryHasNewerImages =
        secondary.imageRevision > primary.imageRevision;
    final imageSource = primaryHasNewerImages
        ? primary
        : secondaryHasNewerImages
            ? secondary
            : primaryImagesAreAuthoritative
                ? primary
                : null;
    final images = imageSource != null
        ? _uniqueImagePaths([
            ...imageSource.imagePaths,
            imageSource.imagePath,
          ])
        : _uniqueImagePaths([
            ..._cloudImagePaths(primary),
            ..._cloudImagePaths(secondary),
            ..._localImagePaths(primary),
            ..._localImagePaths(secondary),
          ]);
    final cloudImages = images.where(_isNetworkImagePath).toList();
    final primaryImage = cleanText(primary.imagePath);
    final secondaryImage = cleanText(secondary.imagePath);
    final imagePath = imageSource != null
        ? (images.isEmpty ? '' : images.first)
        : cloudImages.isNotEmpty
            ? cloudImages.first
            : primaryImage.isNotEmpty
                ? primaryImage
                : secondaryImage;
    final imageFinishTags = _imageFinishTagsForPaths(
      images,
      imageSource == null ? [primary, secondary] : [imageSource],
    );

    return primary.copyWith(
      imagePath: imagePath,
      imagePaths: images,
      imageFinishTags: imageFinishTags,
      imageRevision: primary.imageRevision > secondary.imageRevision
          ? primary.imageRevision
          : secondary.imageRevision,
      variations: primary.variations.isNotEmpty
          ? primary.variations
          : secondary.variations,
      keywords: _uniqueDropdownValues([
        ...primary.keywords,
        ...secondary.keywords,
      ]),
    );
  }

  int _findProductIndex(
    List<ProductDraft> products,
    ProductDraft target, {
    bool allowIdOnlyMatch = false,
  }) {
    final normalizedSku = _normalUi(target.sku);
    if (normalizedSku.isNotEmpty) {
      final bySku = products.indexWhere(
        (product) => _normalUi(product.sku) == normalizedSku,
      );
      if (bySku >= 0) return bySku;
    }

    final byName = products.indexWhere(
      (product) => _normalUi(product.name) == _normalUi(target.name),
    );
    if (byName >= 0) return byName;
    if (!allowIdOnlyMatch) return -1;
    return products.indexWhere((product) => product.id == target.id);
  }

  List<CategoryDraft> _mergeCategoryDraftLists(
    List<CategoryDraft> first,
    List<CategoryDraft> second,
  ) {
    final result = <CategoryDraft>[];
    for (final category in [...first, ...second]) {
      final name = cleanText(category.name);
      if (name.isEmpty) continue;
      final index =
          result.indexWhere((item) => _normalUi(item.name) == _normalUi(name));
      if (index < 0) {
        result.add(category.copyWith(
          name: name,
          subcategories: _uniqueDropdownValues(category.subcategories),
          keywords: _uniqueDropdownValues(category.keywords),
        ));
      } else {
        final existing = result[index];
        result[index] = existing.copyWith(
          imagePath: existing.imagePath,
          subcategories: _uniqueDropdownValues([
            ...existing.subcategories,
            ...category.subcategories,
          ]),
          keywords: _uniqueDropdownValues([
            ...existing.keywords,
            ...category.keywords,
          ]),
          subcategoryImages: existing.subcategoryImages,
        );
      }
    }
    return result;
  }

  List<String> _uniqueDropdownValues(List<String> values) {
    final result = <String>[];
    for (final value in values) {
      final clean = cleanText(value);
      if (clean.isEmpty) continue;
      if (!result.any((item) => _normalUi(item) == _normalUi(clean))) {
        result.add(clean);
      }
    }
    return result;
  }

  List<String> _cloudImagePaths(ProductDraft product) {
    return _uniqueImagePaths([
      for (final path in [...product.imagePaths, product.imagePath])
        if (_isNetworkImagePath(cleanText(path))) cleanText(path),
    ]);
  }

  List<String> _localImagePaths(ProductDraft product) {
    return _uniqueImagePaths([
      for (final path in [...product.imagePaths, product.imagePath])
        if (cleanText(path).isNotEmpty && !_isNetworkImagePath(cleanText(path)))
          cleanText(path),
    ]);
  }

  List<String> _uniqueImagePaths(List<String> paths) {
    final result = <String>[];
    for (final path in paths) {
      final clean = cleanText(path);
      if (clean.isEmpty) continue;
      if (!result.contains(clean)) result.add(clean);
    }
    return result;
  }

  bool _sameCatalogue(CatalogueState left, CatalogueState right) {
    if (identical(left, right)) return true;
    if (!_sameStringList(left.brands, right.brands) ||
        !_sameStringList(left.bannerImagePaths, right.bannerImagePaths) ||
        !_sameStringMap(left.brandImages, right.brandImages) ||
        !_sameStringMap(left.customerStockStatuses, right.customerStockStatuses) ||
        left.resetGeneration != right.resetGeneration ||
        left.products.length != right.products.length ||
        left.photoInbox.length != right.photoInbox.length ||
        left.categories.length != right.categories.length ||
        left.stockItems.length != right.stockItems.length ||
        left.stockVouchers.length != right.stockVouchers.length ||
        left.customerOrders.length != right.customerOrders.length ||
        !_sameSearchTerminologyList(
          left.searchTerminology,
          right.searchTerminology,
        )) {
      return false;
    }
    for (var index = 0; index < left.products.length; index++) {
      if (!_sameProductDraft(left.products[index], right.products[index])) {
        return false;
      }
    }
    for (var index = 0; index < left.photoInbox.length; index++) {
      if (jsonEncode(left.photoInbox[index].toJson()) !=
          jsonEncode(right.photoInbox[index].toJson())) {
        return false;
      }
    }
    for (var index = 0; index < left.categories.length; index++) {
      if (!_sameCategoryDraft(
          left.categories[index], right.categories[index])) {
        return false;
      }
    }
    for (var index = 0; index < left.stockItems.length; index++) {
      if (!_sameStockItemDraft(
          left.stockItems[index], right.stockItems[index])) {
        return false;
      }
    }
    for (var index = 0; index < left.stockVouchers.length; index++) {
      if (!_sameStockVoucherDraft(
          left.stockVouchers[index], right.stockVouchers[index])) {
        return false;
      }
    }
    for (var index = 0; index < left.customerOrders.length; index++) {
      if (!_sameCustomerOrderDraft(
          left.customerOrders[index], right.customerOrders[index])) {
        return false;
      }
    }
    return true;
  }

  bool _sameSearchTerminologyList(
    List<SearchTerminologyDraft> left,
    List<SearchTerminologyDraft> right,
  ) {
    if (left.length != right.length) return false;
    for (var index = 0; index < left.length; index++) {
      if (left[index].canonical != right[index].canonical ||
          !_sameStringList(left[index].aliases, right[index].aliases)) {
        return false;
      }
    }
    return true;
  }

  bool _sameCustomerOrderDraft(
      CustomerOrderDraft left, CustomerOrderDraft right) {
    if (!(left.id == right.id &&
        left.orderNumber == right.orderNumber &&
        left.customerAccountId == right.customerAccountId &&
        left.customerType == right.customerType &&
        left.customerName == right.customerName &&
        left.customerPhone == right.customerPhone &&
        left.customerNotes == right.customerNotes &&
        left.salesman == right.salesman &&
        left.status == right.status &&
        left.approvedBy == right.approvedBy &&
        left.dispatchDetails == right.dispatchDetails &&
        left.additionalDiscountPercent == right.additionalDiscountPercent &&
        left.createdAt == right.createdAt &&
        left.updatedAt == right.updatedAt &&
        left.items.length == right.items.length)) {
      return false;
    }
    for (var index = 0; index < left.items.length; index++) {
      if (!_sameCustomerOrderItemDraft(left.items[index], right.items[index])) {
        return false;
      }
    }
    return true;
  }

  bool _sameCustomerOrderItemDraft(
    CustomerOrderItemDraft left,
    CustomerOrderItemDraft right,
  ) {
    return left.productId == right.productId &&
        left.productName == right.productName &&
        left.stockItemId == right.stockItemId &&
        left.stockSku == right.stockSku &&
        left.brand == right.brand &&
        left.size == right.size &&
        left.finish == right.finish &&
        left.imagePath == right.imagePath &&
        left.quantity == right.quantity &&
        left.unitPrice == right.unitPrice &&
        left.defaultDiscount == right.defaultDiscount &&
        left.revisedDiscount == right.revisedDiscount &&
        left.finalDiscount == right.finalDiscount &&
        left.approvedQuantity == right.approvedQuantity &&
        left.dispatchedQuantity == right.dispatchedQuantity &&
        left.notes == right.notes;
  }

  bool _sameStockItemDraft(StockItemDraft left, StockItemDraft right) {
    return left.id == right.id &&
        left.displayProductId == right.displayProductId &&
        left.displayProductName == right.displayProductName &&
        left.stockSku == right.stockSku &&
        left.brand == right.brand &&
        left.size == right.size &&
        left.finish == right.finish &&
        left.category == right.category &&
        left.subcategory == right.subcategory &&
        left.material == right.material &&
        left.isActive == right.isActive &&
        left.createdAt == right.createdAt &&
        left.updatedAt == right.updatedAt;
  }

  bool _sameStockVoucherDraft(StockVoucherDraft left, StockVoucherDraft right) {
    if (left.id != right.id ||
        left.type != right.type ||
        left.voucherNumber != right.voucherNumber ||
        left.date != right.date ||
        left.partyName != right.partyName ||
        left.reference != right.reference ||
        left.notes != right.notes ||
        left.createdAt != right.createdAt ||
        left.items.length != right.items.length) {
      return false;
    }
    for (var index = 0; index < left.items.length; index++) {
      if (!_sameStockVoucherItemDraft(left.items[index], right.items[index])) {
        return false;
      }
    }
    return true;
  }

  bool _sameStockVoucherItemDraft(
    StockVoucherItemDraft left,
    StockVoucherItemDraft right,
  ) {
    return left.stockItemId == right.stockItemId &&
        left.productId == right.productId &&
        left.productName == right.productName &&
        left.stockSku == right.stockSku &&
        left.brand == right.brand &&
        left.size == right.size &&
        left.finish == right.finish &&
        left.godown == right.godown &&
        left.quantity == right.quantity &&
        left.notes == right.notes;
  }

  bool _sameProductDraft(ProductDraft left, ProductDraft right) {
    if (left.id != right.id ||
        left.name != right.name ||
        left.sku != right.sku ||
        left.internalProductCode != right.internalProductCode ||
        left.category != right.category ||
        left.subcategory != right.subcategory ||
        left.brand != right.brand ||
        left.sizeSpec != right.sizeSpec ||
        left.finishColor != right.finishColor ||
        left.sellingPrice != right.sellingPrice ||
        left.imagePath != right.imagePath ||
        left.notes != right.notes ||
        !_sameStringList(left.keywords, right.keywords) ||
        left.imageRevision != right.imageRevision ||
        left.isPublished != right.isPublished ||
        left.isComingSoon != right.isComingSoon ||
        left.isArchived != right.isArchived ||
        left.archivedAt != right.archivedAt ||
        !_sameStringList(left.imagePaths, right.imagePaths) ||
        !_sameStringMap(left.imageFinishTags, right.imageFinishTags) ||
        left.variations.length != right.variations.length) {
      return false;
    }
    for (var index = 0; index < left.variations.length; index++) {
      if (!_sameVariationDraft(
          left.variations[index], right.variations[index])) {
        return false;
      }
    }
    return true;
  }

  bool _sameVariationDraft(VariationDraft left, VariationDraft right) {
    return left.size == right.size &&
        left.finish == right.finish &&
        left.breadth == right.breadth &&
        left.length == right.length &&
        left.height == right.height &&
        left.thickness == right.thickness &&
        left.price == right.price &&
        left.sku == right.sku &&
        left.notes == right.notes;
  }

  bool _sameCategoryDraft(CategoryDraft left, CategoryDraft right) {
    return left.name == right.name &&
        left.imagePath == right.imagePath &&
        left.isPublished == right.isPublished &&
        _sameStringList(left.subcategories, right.subcategories) &&
        _sameStringList(left.keywords, right.keywords) &&
        _sameStringMap(left.subcategoryImages, right.subcategoryImages) &&
        _sameBoolMap(left.subcategoryPublished, right.subcategoryPublished);
  }

  bool _sameStringList(List<String> left, List<String> right) {
    if (left.length != right.length) return false;
    for (var index = 0; index < left.length; index++) {
      if (left[index] != right[index]) return false;
    }
    return true;
  }

  bool _sameStringMap(Map<String, String> left, Map<String, String> right) {
    if (left.length != right.length) return false;
    for (final entry in left.entries) {
      if (right[entry.key] != entry.value) return false;
    }
    return true;
  }

  bool _sameBoolMap(Map<String, bool> left, Map<String, bool> right) {
    if (left.length != right.length) return false;
    for (final entry in left.entries) {
      if (right[entry.key] != entry.value) return false;
    }
    return true;
  }

  @override
  Widget build(BuildContext context) {
    if (_authChecking) {
      return const Scaffold(
        body: Center(child: CircularProgressIndicator()),
      );
    }
    final profile = _profile;
    if (profile == null) {
      _publishStockSnapshot(null);
      return _LoginScreen(
        busy: _authBusy,
        error: _authError,
        cloudConfigured: _cloudSettings?.isConfigured == true,
        hasBiometricUnlock: _biometricAvailable,
        onLogin: _handleLogin,
        onBiometricUnlock: _handleBiometricUnlock,
      );
    }
    return FutureBuilder<CatalogueState>(
      future: _catalogueFuture,
      builder: (context, snapshot) {
        if (snapshot.connectionState != ConnectionState.done &&
            !snapshot.hasData) {
          return const Scaffold(
              body: Center(child: CircularProgressIndicator()));
        }
        if (snapshot.hasError) {
          return Scaffold(
            body: Center(
              child: _LoadErrorCard(
                message: snapshot.error.toString(),
                onRetry: _refreshCatalogue,
              ),
            ),
          );
        }

        final state = snapshot.data ?? const CatalogueState();
        _publishStockSnapshot(state);
        final selectedProduct = _selectedProduct(state.products);
        if (selectedProduct != null) _selectedProductId = selectedProduct.id;

        return PopScope(
          canPop: false,
          onPopInvokedWithResult: (didPop, result) {
            if (!didPop) _goBack();
          },
          child: _CustomerServiceScope(
          repository: _customerManagement,
          catalogue: _cloud,
          refresh: _refreshCatalogue,
          child: _CatalogueShell(
            state: state,
            profile: profile,
            selectedProduct: selectedProduct,
            pendingProductCategory: _pendingProductCategory,
            pendingProductSubcategory: _pendingProductSubcategory,
            section: _section,
            editingProduct: _editingProduct,
            storePath: _repository.storePath,
            cloudStatus: _cloudStatus,
            canGoBack: _canGoBack,
            onBack: _goBack,
            onSectionBackChanged: _setSectionBackHandler,
            onRefreshCatalogue: _refreshCatalogue,
            onLogout: _handleLogout,
            onSectionChanged: _goToSection,
            onOpenProductCategory: _openProductCategory,
            onPendingProductCategoryConsumed: () {
              if (_pendingProductCategory.isNotEmpty ||
                  _pendingProductSubcategory.isNotEmpty) {
                setState(() {
                  _pendingProductCategory = '';
                  _pendingProductSubcategory = '';
                });
              }
            },
            onAddProduct: () => _goToSection(
              _CatalogueSection.addProduct,
              clearEditingProduct: true,
            ),
            onSelectProduct: (product) {
              setState(() => _selectedProductId = product.id);
              _goToSection(_CatalogueSection.products);
            },
            onEditProduct: (product) {
              setState(() {
                _selectedProductId = product.id;
                _editingProduct = product;
                _pendingProductCategory = cleanText(product.category);
                _pendingProductSubcategory = cleanText(product.subcategory);
              });
              _goToSection(_CatalogueSection.addProduct);
            },
            onSaveProduct: _saveProduct,
            onArchiveProduct: _archiveProduct,
            onRestoreProduct: _restoreProduct,
            onToggleProductPublished: _setProductPublished,
            onSetProductsPublished: _setProductsPublished,
            onSaveCategories: _saveCategories,
            onSaveBrands: _saveBrands,
            onSaveCatalogueStructure: _saveCatalogueStructure,
            onResolvePhotoInboxImage: _resolvePhotoInboxImage,
            onCheckPhotoInboxReady: _photoInboxCloudReady,
            onImportBulkPaste: _importBulkPaste,
            onRestoreBackup: _restoreCatalogueBackup,
            onVerifyAdminReset: _verifyResetAdminCredentials,
            customerCartItems: _customerCartItems,
            editingCustomerOrder: _editingCustomerOrder,
            onAddCustomerCartItem: _addCustomerCartItem,
            onUpdateCustomerCartQuantity: _updateCustomerCartQuantity,
            onRemoveCustomerCartItem: _removeCustomerCartItem,
            onClearCustomerCart: _clearCustomerCart,
            onPlaceCustomerOrder: _placeCustomerOrder,
            onEditCustomerOrder: _editCustomerOrder,
            onCancelCustomerOrder: _cancelCustomerOrder,
            onResetCatalogueData: _resetCatalogueData,
          ),
          ),
        );
      },
    );
  }

  bool get _canGoBack =>
      _sectionBackHandler != null ||
      _sectionHistory.isNotEmpty ||
      _section != _CatalogueSection.dashboard;

  void _setSectionBackHandler(VoidCallback? handler) {
    if (_sectionBackHandler == handler) return;
    setState(() => _sectionBackHandler = handler);
  }

  void _goToSection(
    _CatalogueSection section, {
    bool clearEditingProduct = false,
    bool recordHistory = true,
  }) {
    final allowedSection = _sectionForRole(section);
    setState(() {
      section = allowedSection;
      if (recordHistory && section != _section) {
        _sectionHistory.add(_section);
      }
      _section = section;
      if (section != _CatalogueSection.products) {
        _sectionBackHandler = null;
      }
      if (clearEditingProduct) {
        _editingProduct = null;
      }
    });
  }

  void _openProductCategory(String category) {
    setState(() {
      _pendingProductCategory = cleanText(category);
      _pendingProductSubcategory = '';
    });
    _goToSection(_CatalogueSection.products);
  }

  _CatalogueSection _sectionForRole(_CatalogueSection section) {
    if (_canManageCatalogue) return section;
    if (_profile?.role == CrimsonUserRole.customer) {
      return switch (section) {
        _CatalogueSection.dashboard ||
        _CatalogueSection.products ||
        _CatalogueSection.orders ||
        _CatalogueSection.account =>
          section,
        _ => _CatalogueSection.products,
      };
    }
    return switch (section) {
      _CatalogueSection.dashboard || _CatalogueSection.products => section,
      _ => _CatalogueSection.products,
    };
  }

  void _goBack() {
    final sectionBackHandler = _sectionBackHandler;
    if (sectionBackHandler != null) {
      sectionBackHandler();
      return;
    }
    setState(() {
      if (_editingProduct != null && _section == _CatalogueSection.addProduct) {
        _editingProduct = null;
      }
      if (_sectionHistory.isNotEmpty) {
        _section = _sectionHistory.removeLast();
      } else {
        _section = _CatalogueSection.dashboard;
      }
    });
  }

  ProductDraft? _selectedProduct(List<ProductDraft> products) {
    if (products.isEmpty) return null;
    return products.firstWhere(
      (product) => product.id == _selectedProductId,
      orElse: () => products.first,
    );
  }

  Future<void> _addCustomerCartItem(CustomerOrderItemDraft item) async {
    final catalogue = await _catalogueFuture;
    if (catalogue.products.any(
        (product) => product.id == item.productId && product.isComingSoon)) {
      return;
    }
    setState(() {
      final index = _customerCartItems.indexWhere(
        (line) => _sameCartItem(line, item),
      );
      if (index < 0) {
        _customerCartItems.add(item);
      } else {
        final existing = _customerCartItems[index];
        _customerCartItems[index] = existing.copyWith(
          quantity: existing.quantity + item.quantity,
        );
      }
    });
  }

  void _updateCustomerCartQuantity(int index, double quantity) {
    if (index < 0 || index >= _customerCartItems.length) return;
    setState(() {
      if (quantity <= 0) {
        _customerCartItems.removeAt(index);
        return;
      }
      final item = _customerCartItems[index];
      _customerCartItems[index] = item.copyWith(quantity: quantity);
    });
  }

  void _removeCustomerCartItem(int index) {
    if (index < 0 || index >= _customerCartItems.length) return;
    setState(() => _customerCartItems.removeAt(index));
  }

  void _clearCustomerCart() {
    if (_customerCartItems.isEmpty && _editingCustomerOrder == null) return;
    setState(() {
      _customerCartItems.clear();
      _editingCustomerOrder = null;
    });
  }

  Future<void> _editCustomerOrder(CustomerOrderDraft order) async {
    if (!_customerOrderCanEdit(order)) return;
    setState(() {
      _editingCustomerOrder = order;
      _customerCartItems
        ..clear()
        ..addAll(order.items);
      _section = _CatalogueSection.orders;
    });
  }

  Future<void> _cancelCustomerOrder(CustomerOrderDraft order) async {
    if (!_customerOrderCanEdit(order)) return;
    final current = await _stateWithCloudCustomerOrders(await _catalogueFuture);
    final now = DateTime.now();
    var cancelledOrder = order.copyWith(
      status: CustomerOrderStatus.cancelled,
      updatedAt: now.toUtc().toIso8601String(),
    );
    cancelledOrder =
        await _saveCustomerOrderToCloud(cancelledOrder) ?? cancelledOrder;
    final nextOrders = _mergeCustomerOrderDraftLists(
      current.customerOrders.where((item) => item.id != order.id).toList(),
      [cancelledOrder],
    );
    final nextState = current.copyWith(
      customerOrders: nextOrders,
      updatedAt: now.toIso8601String(),
    );
    await _repository.save(nextState);
    setState(() {
      if (_editingCustomerOrder?.id == order.id) {
        _editingCustomerOrder = null;
        _customerCartItems.clear();
      }
      _catalogueFuture = Future.value(nextState);
    });
  }

  Future<void> _placeCustomerOrder({
    required String customerName,
    required String customerPhone,
    required String notes,
  }) async {
    if (_customerCartItems.isEmpty) return;
    final current = await _stateWithCloudCustomerOrders(await _catalogueFuture);
    final now = DateTime.now();
    final editingOrder = _editingCustomerOrder;
    final pricedItems = editingOrder == null
        ? _cartItemsWithCurrentDiscounts(
            _customerCartItems,
            current.products,
            current.categories,
          )
        : List<CustomerOrderItemDraft>.from(_customerCartItems);
    var order = editingOrder == null
        ? CustomerOrderDraft(
            orderNumber: _nextCustomerOrderNumber(current.customerOrders),
            customerAccountId: _authSession?.userId ?? '',
            customerType: 'regular',
            customerName: cleanText(customerName).isEmpty
                ? (_profile?.displayName ?? 'Customer')
                : cleanText(customerName),
            customerPhone: cleanText(customerPhone),
            customerNotes: cleanText(notes),
            status: CustomerOrderStatus.placed,
            createdAt: now.toUtc().toIso8601String(),
            updatedAt: now.toUtc().toIso8601String(),
            items: pricedItems,
          )
        : editingOrder.copyWith(
            customerName: cleanText(customerName).isEmpty
                ? editingOrder.customerName
                : cleanText(customerName),
            customerPhone: cleanText(customerPhone).isEmpty
                ? editingOrder.customerPhone
                : cleanText(customerPhone),
            customerNotes: cleanText(notes).isEmpty
                ? editingOrder.customerNotes
                : cleanText(notes),
            status: CustomerOrderStatus.placed,
            updatedAt: now.toUtc().toIso8601String(),
            items: pricedItems,
          );
    final cloudOrder = await _saveCustomerOrderToCloud(
      order,
      assignServerNumber: editingOrder == null,
    );
    if (widget.enableCloud && cloudOrder == null) {
      throw StateError('The order could not be sent. Check your connection and try again.');
    }
    order = cloudOrder ?? order;
    final nextOrders = _mergeCustomerOrderDraftLists(
      current.customerOrders
          .where((item) =>
              item.id != order.id && item.id != (editingOrder?.id ?? ''))
          .toList(),
      [order],
    );
    final nextState = current.copyWith(
      customerOrders: nextOrders,
      updatedAt: now.toIso8601String(),
    );
    await _repository.save(nextState);
    setState(() {
      _customerCartItems.clear();
      _editingCustomerOrder = null;
      _catalogueFuture = Future.value(nextState);
      _section = _CatalogueSection.account;
    });
  }

  String _nextCustomerOrderNumber(List<CustomerOrderDraft> orders) {
    return _nextOrderNumberFrom(orders);
  }
}

bool _sameCartItem(CustomerOrderItemDraft left, CustomerOrderItemDraft right) {
  return left.productId == right.productId &&
      _sameName(left.stockSku, right.stockSku) &&
      _sameName(left.size, right.size) &&
      _sameName(left.finish, right.finish);
}

List<CustomerOrderItemDraft> _cartItemsWithCurrentDiscounts(
  List<CustomerOrderItemDraft> items,
  List<ProductDraft> products,
  List<CategoryDraft> categories,
) {
  final productById = {for (final product in products) product.id: product};
  return items.map((item) {
    final product = productById[item.productId];
    if (product == null ||
        item.finalDiscount.trim().isNotEmpty ||
        item.revisedDiscount.trim().isNotEmpty) {
      return item;
    }
    final percent = item.unitPrice > 0
        ? categoryDiscountFor(categories, product.category)
        : 0.0;
    return item.copyWith(
      defaultDiscount: percent > 0 ? '${formatCompactPrice(percent)}%' : '',
    );
  }).toList();
}

const Duration _customerOrderEditWindow = Duration(minutes: 10);

DateTime? _orderCreatedAt(CustomerOrderDraft order) {
  final parsed = DateTime.tryParse(order.createdAt);
  if (parsed == null) return null;
  return parsed.isUtc ? parsed : parsed.toUtc();
}

bool _customerOrderCanEdit(CustomerOrderDraft order) {
  if (order.status != CustomerOrderStatus.placed &&
      order.status != CustomerOrderStatus.draft) {
    return false;
  }
  final createdAt = _orderCreatedAt(order);
  if (createdAt == null) return true;
  return DateTime.now().toUtc().difference(createdAt) <=
      _customerOrderEditWindow;
}

String _nextOrderNumberFrom(List<CustomerOrderDraft> orders) {
  final year = DateTime.now().year;
  final pattern = RegExp(r'^ORD-(\d{4})-(\d+)$');
  var highest = 0;
  for (final order in orders) {
    final match = pattern.firstMatch(cleanText(order.orderNumber));
    if (match == null || match.group(1) != year.toString()) continue;
    final number = int.tryParse(match.group(2) ?? '');
    if (number != null) highest = math.max(highest, number);
  }
  return 'ORD-$year-${(highest + 1).toString().padLeft(5, '0')}';
}

String _customerOrderEditLabel(CustomerOrderDraft order) {
  if (!_customerOrderCanEdit(order)) return 'Locked after approval';
  final createdAt = _orderCreatedAt(order);
  if (createdAt == null) return 'Editable before approval';
  final left =
      _customerOrderEditWindow - DateTime.now().toUtc().difference(createdAt);
  final minutes = math.max(0, left.inMinutes);
  final seconds = math.max(0, left.inSeconds % 60);
  return 'Editable for ${minutes}m ${seconds}s';
}

List<CustomerOrderStatus> _nextOrderWorkflowStatuses(
  CustomerOrderStatus status,
) {
  return switch (status) {
    CustomerOrderStatus.draft => const [
        CustomerOrderStatus.placed,
        CustomerOrderStatus.cancelled,
      ],
    CustomerOrderStatus.placed => const [
        CustomerOrderStatus.confirmed,
        CustomerOrderStatus.rejected,
        CustomerOrderStatus.cancelled,
      ],
    CustomerOrderStatus.confirmed => const [CustomerOrderStatus.packed],
    CustomerOrderStatus.packed => const [CustomerOrderStatus.dispatched],
    CustomerOrderStatus.dispatched => const [CustomerOrderStatus.delivered],
    CustomerOrderStatus.delivered ||
    CustomerOrderStatus.cancelled ||
    CustomerOrderStatus.rejected =>
      const [],
  };
}

String _orderWorkflowActionLabel(CustomerOrderStatus status) {
  return switch (status) {
    CustomerOrderStatus.draft => 'Submit',
    CustomerOrderStatus.placed => 'Approve',
    CustomerOrderStatus.confirmed => 'Mark packed',
    CustomerOrderStatus.packed => 'Dispatch',
    CustomerOrderStatus.dispatched => 'Deliver',
    CustomerOrderStatus.delivered => 'Delivered',
    CustomerOrderStatus.cancelled => 'Cancel',
    CustomerOrderStatus.rejected => 'Reject',
  };
}

String _orderWorkflowHelp(CustomerOrderStatus status) {
  return switch (status) {
    CustomerOrderStatus.draft => 'Draft orders are not yet submitted.',
    CustomerOrderStatus.placed =>
      'Customer can edit briefly. Admin approval locks the order.',
    CustomerOrderStatus.confirmed =>
      'Approved by admin. Stock is deducted when the bill is generated.',
    CustomerOrderStatus.packed =>
      'Packed and ready for transport details or dispatch.',
    CustomerOrderStatus.dispatched =>
      'Dispatched. Generate a bill to record the stock deduction.',
    CustomerOrderStatus.delivered => 'Completed order.',
    CustomerOrderStatus.cancelled => 'Cancelled order.',
    CustomerOrderStatus.rejected => 'Rejected during approval.',
  };
}

enum _CatalogueSection {
  dashboard('Dashboard', Icons.dashboard_outlined),
  products('Products', Icons.inventory_2_outlined),
  stock('Stock', Icons.warehouse_outlined),
  orders('Orders', Icons.receipt_long_outlined),
  orderNew('New Order', Icons.add_shopping_cart_outlined),
  orderView('View Orders', Icons.list_alt_outlined),
  orderPendingApproval('Pending Approval', Icons.pending_actions_outlined),
  orderDispatch('Dispatch', Icons.local_shipping_outlined),
  categories('Categories', Icons.category_outlined),
  addProduct('Add Product', Icons.add_circle_outline),
  photoInbox('Photo Inbox', Icons.photo_library_outlined),
  bulkPaste('Bulk Paste', Icons.content_paste_go_outlined),
  priceMatrix('Price Matrix', Icons.grid_on_outlined),
  exportPreview('Export Preview', Icons.picture_as_pdf_outlined),
  studioTools('Tools', Icons.construction_rounded),
  account('Account', Icons.person_outline),
  settings('Settings', Icons.settings_outlined);

  const _CatalogueSection(this.label, this.icon);

  final String label;
  final IconData icon;
}

