class _CatalogueShellState extends State<_CatalogueShell> {
  bool _navigationOpen = false;

  @override
  Widget build(BuildContext context) {
    final width = MediaQuery.sizeOf(context).width;
    if (width < 720) {
      return _MobileCatalogueShell(
        state: widget.state,
        profile: widget.profile,
        selectedProduct: widget.selectedProduct,
        pendingProductCategory: widget.pendingProductCategory,
        pendingProductSubcategory: widget.pendingProductSubcategory,
        section: widget.section,
        editingProduct: widget.editingProduct,
        storePath: widget.storePath,
        cloudStatus: widget.cloudStatus,
        onVerifyAdminReset: widget.onVerifyAdminReset,
        customerCartItems: widget.customerCartItems,
        editingCustomerOrder: widget.editingCustomerOrder,
        onAddCustomerCartItem: widget.onAddCustomerCartItem,
        onUpdateCustomerCartQuantity: widget.onUpdateCustomerCartQuantity,
        onRemoveCustomerCartItem: widget.onRemoveCustomerCartItem,
        onClearCustomerCart: widget.onClearCustomerCart,
        onPlaceCustomerOrder: widget.onPlaceCustomerOrder,
        onEditCustomerOrder: widget.onEditCustomerOrder,
        onCancelCustomerOrder: widget.onCancelCustomerOrder,
        onResetCatalogueData: widget.onResetCatalogueData,
        canGoBack: widget.canGoBack,
        onBack: widget.onBack,
        onSectionBackChanged: widget.onSectionBackChanged,
        onRefreshCatalogue: widget.onRefreshCatalogue,
        onLogout: widget.onLogout,
        onSectionChanged: widget.onSectionChanged,
        onOpenProductCategory: widget.onOpenProductCategory,
        onPendingProductCategoryConsumed:
            widget.onPendingProductCategoryConsumed,
        onAddProduct: widget.onAddProduct,
        onSelectProduct: widget.onSelectProduct,
        onEditProduct: widget.onEditProduct,
        onToggleProductPublished: widget.onToggleProductPublished,
        onSetProductsPublished: widget.onSetProductsPublished,
        onSaveProduct: widget.onSaveProduct,
        onSaveCategories: widget.onSaveCategories,
        onSaveBrands: widget.onSaveBrands,
        onSaveCatalogueStructure: widget.onSaveCatalogueStructure,
        onResolvePhotoInboxImage: widget.onResolvePhotoInboxImage,
        onCheckPhotoInboxReady: widget.onCheckPhotoInboxReady,
        onImportBulkPaste: widget.onImportBulkPaste,
        onRestoreBackup: widget.onRestoreBackup,
      );
    }

    return Scaffold(
      body: SafeArea(
        child: Stack(
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(22, 18, 22, 18),
              child: widget.section == _CatalogueSection.products
                  ? _sectionBody(context)
                  : Column(
                      children: [
                        _TopSearchBar(
                          section: widget.section,
                          canAddProduct: widget.profile.canManageCatalogue,
                          storePath: widget.storePath,
                          cloudStatus: widget.cloudStatus,
                          canGoBack: widget.canGoBack,
                          onBack: widget.onBack,
                          onRefreshCatalogue: widget.onRefreshCatalogue,
                          onAddProduct: widget.onAddProduct,
                          onMenuPressed: _openNavigation,
                        ),
                        const SizedBox(height: 18),
                        Expanded(child: _sectionBody(context)),
                      ],
                    ),
            ),
            if (_navigationOpen)
              Positioned.fill(
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: _closeNavigation,
                  child: Container(color: const Color(0x52000000)),
                ),
              ),
            AnimatedPositioned(
              duration: const Duration(milliseconds: 220),
              curve: Curves.easeOutCubic,
              left: _navigationOpen ? 0 : -272,
              top: 0,
              bottom: 0,
              width: 272,
              child: Material(
                color: Colors.white,
                elevation: 18,
                child: _SideNavigation(
                  selected: widget.section,
                  profile: widget.profile,
                  onLogout: widget.onLogout,
                  onClose: _closeNavigation,
                  onChanged: (section) {
                    widget.onSectionChanged(section);
                    _closeNavigation();
                  },
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _sectionBody(BuildContext context) {
    switch (widget.section) {
      case _CatalogueSection.dashboard:
        return _DashboardScreen(
          state: widget.state,
          profile: widget.profile,
          onLogout: widget.onLogout,
          onSelectProduct: widget.onSelectProduct,
          onOpenProducts: () =>
              widget.onSectionChanged(_CatalogueSection.products),
          onOpenProductCategory: widget.onOpenProductCategory,
        );
      case _CatalogueSection.products:
        return _ProductsBrowserScreen(
          state: widget.state,
          profile: widget.profile,
          selectedProduct: widget.selectedProduct,
          initialCategory: widget.pendingProductCategory,
          initialSubcategory: widget.pendingProductSubcategory,
          onInitialCategoryConsumed: widget.onPendingProductCategoryConsumed,
          onOpenNavigation: _openNavigation,
          canGoBack: widget.canGoBack,
          onBack: widget.onBack,
          onSectionBackChanged: widget.onSectionBackChanged,
          onAddProduct: widget.onAddProduct,
          cloudStatus: widget.cloudStatus,
          onRefreshCatalogue: widget.onRefreshCatalogue,
          onSelectProduct: widget.onSelectProduct,
          onEditProduct: widget.onEditProduct,
          onArchiveProduct: widget.onArchiveProduct,
          onRestoreProduct: widget.onRestoreProduct,
          onToggleProductPublished: widget.onToggleProductPublished,
          onSetProductsPublished: widget.onSetProductsPublished,
          onAddCustomerCartItem: widget.onAddCustomerCartItem,
          onOpenCart: () => widget.onSectionChanged(_CatalogueSection.orders),
        );
      case _CatalogueSection.stock:
        return _StockScreen(
          state: widget.state,
          onSaveState: widget.onSaveCatalogueStructure,
        );
      case _CatalogueSection.orders:
        if (widget.profile.role == CrimsonUserRole.customer) {
          return _CustomerCartScreen(
            items: widget.customerCartItems,
            products: widget.state.products,
            categories: widget.state.categories,
            profile: widget.profile,
            onOpenProducts: () =>
                widget.onSectionChanged(_CatalogueSection.products),
            onSelectProduct: widget.onSelectProduct,
            onEditProduct: widget.onEditProduct,
            onAddCustomerCartItem: widget.onAddCustomerCartItem,
            onUpdateQuantity: widget.onUpdateCustomerCartQuantity,
            onRemoveItem: widget.onRemoveCustomerCartItem,
            onClear: widget.onClearCustomerCart,
            editingOrder: widget.editingCustomerOrder,
            onPlaceOrder: widget.onPlaceCustomerOrder,
          );
        }
        return _OrdersScreen(
          state: widget.state,
          profile: widget.profile,
          mode: _OrderWorkspaceMode.newOrder,
          onSaveState: widget.onSaveCatalogueStructure,
        );
      case _CatalogueSection.orderNew:
        return _OrdersScreen(
          state: widget.state,
          profile: widget.profile,
          mode: _OrderWorkspaceMode.newOrder,
          onSaveState: widget.onSaveCatalogueStructure,
        );
      case _CatalogueSection.orderView:
        return _OrdersScreen(
          state: widget.state,
          profile: widget.profile,
          mode: _OrderWorkspaceMode.viewOrders,
          onSaveState: widget.onSaveCatalogueStructure,
        );
      case _CatalogueSection.orderPendingApproval:
        return _OrdersScreen(
          state: widget.state,
          profile: widget.profile,
          mode: _OrderWorkspaceMode.pendingApproval,
          onSaveState: widget.onSaveCatalogueStructure,
        );
      case _CatalogueSection.orderDispatch:
        return _OrdersScreen(
          state: widget.state,
          profile: widget.profile,
          mode: _OrderWorkspaceMode.dispatch,
          onSaveState: widget.onSaveCatalogueStructure,
        );
      case _CatalogueSection.categories:
        return _CategoriesScreen(
          state: widget.state,
          onSaveCategories: widget.onSaveCategories,
          onSaveBrands: widget.onSaveBrands,
          onSaveState: widget.onSaveCatalogueStructure,
          onOpenProducts: () =>
              widget.onSectionChanged(_CatalogueSection.products),
        );
      case _CatalogueSection.addProduct:
        return _AddProductScreen(
          key: ValueKey(widget.editingProduct?.id ?? 'new-product'),
          editingProduct: widget.editingProduct,
          categories: widget.state.categories,
          brands: widget.state.brands,
          onSaveProduct: widget.onSaveProduct,
          onSaveCategories: widget.onSaveCategories,
          onCancel: () => widget.onSectionChanged(_CatalogueSection.products),
        );
      case _CatalogueSection.photoInbox:
        return PhotoInboxScreen(
          state: widget.state,
          onSaveState: widget.onSaveCatalogueStructure,
          onResolveImage: widget.onResolvePhotoInboxImage,
          onCheckCloudReady: widget.onCheckPhotoInboxReady,
        );
      case _CatalogueSection.bulkPaste:
        return _BulkPasteImportScreen(
          products: widget.state.products,
          onImport: widget.onImportBulkPaste,
        );
      case _CatalogueSection.priceMatrix:
        return _PriceMatrixScreen(product: widget.selectedProduct);
      case _CatalogueSection.exportPreview:
        return _ExportPreviewScreen(product: widget.selectedProduct);
      case _CatalogueSection.studioTools:
        return _BackupHealthScreen(
          state: widget.state,
          storePath: widget.storePath,
          onRestoreBackup: widget.onRestoreBackup,
          onSaveState: widget.onSaveCatalogueStructure,
          onVerifyAdminReset: widget.onVerifyAdminReset,
          onResetCatalogueData: widget.onResetCatalogueData,
          onEditProduct: widget.onEditProduct,
        );
      case _CatalogueSection.account:
        return _CustomerAccountScreen(
          profile: widget.profile,
          orders: widget.state.customerOrders,
          cloudStatus: widget.cloudStatus,
          onRefreshCatalogue: widget.onRefreshCatalogue,
          onOpenProducts: () =>
              widget.onSectionChanged(_CatalogueSection.products),
          onEditOrder: widget.onEditCustomerOrder,
          onCancelOrder: widget.onCancelCustomerOrder,
          onLogout: widget.onLogout,
        );
      case _CatalogueSection.settings:
        return _SettingsScreen(
          state: widget.state,
          storePath: widget.storePath,
          cloudStatus: widget.cloudStatus,
          profile: widget.profile,
          onLogout: widget.onLogout,
          onSaveState: widget.onSaveCatalogueStructure,
        );
    }
  }

  void _openNavigation() => setState(() => _navigationOpen = true);

  void _closeNavigation() {
    if (_navigationOpen) setState(() => _navigationOpen = false);
  }
}

class _MobileCatalogueShell extends StatelessWidget {
  const _MobileCatalogueShell({
    required this.state,
    required this.profile,
    required this.selectedProduct,
    required this.pendingProductCategory,
    required this.pendingProductSubcategory,
    required this.section,
    required this.editingProduct,
    required this.storePath,
    required this.cloudStatus,
    required this.canGoBack,
    required this.onBack,
    required this.onSectionBackChanged,
    required this.onRefreshCatalogue,
    required this.onLogout,
    required this.onSectionChanged,
    required this.onOpenProductCategory,
    required this.onPendingProductCategoryConsumed,
    required this.onAddProduct,
    required this.onSelectProduct,
    required this.onEditProduct,
    required this.onAddCustomerCartItem,
    required this.onToggleProductPublished,
    required this.onSetProductsPublished,
    required this.onSaveProduct,
    required this.onSaveCategories,
    required this.onSaveBrands,
    required this.onSaveCatalogueStructure,
    required this.onResolvePhotoInboxImage,
    required this.onCheckPhotoInboxReady,
    required this.onImportBulkPaste,
    required this.onRestoreBackup,
    required this.onVerifyAdminReset,
    required this.customerCartItems,
    required this.editingCustomerOrder,
    required this.onUpdateCustomerCartQuantity,
    required this.onRemoveCustomerCartItem,
    required this.onClearCustomerCart,
    required this.onPlaceCustomerOrder,
    required this.onEditCustomerOrder,
    required this.onCancelCustomerOrder,
    required this.onResetCatalogueData,
  });

  final CatalogueState state;
  final CrimsonProfile profile;
  final ProductDraft? selectedProduct;
  final String pendingProductCategory;
  final String pendingProductSubcategory;
  final _CatalogueSection section;
  final ProductDraft? editingProduct;
  final String storePath;
  final CloudSyncStatus cloudStatus;
  final bool canGoBack;
  final VoidCallback onBack;
  final void Function(VoidCallback? handler) onSectionBackChanged;
  final Future<void> Function() onRefreshCatalogue;
  final Future<void> Function() onLogout;
  final ValueChanged<_CatalogueSection> onSectionChanged;
  final ValueChanged<String> onOpenProductCategory;
  final VoidCallback onPendingProductCategoryConsumed;
  final VoidCallback onAddProduct;
  final ValueChanged<ProductDraft> onSelectProduct;
  final ValueChanged<ProductDraft> onEditProduct;
  final void Function(ProductDraft product, bool isPublished)
      onToggleProductPublished;
  final Future<void> Function(Set<String> productIds, bool isPublished)
      onSetProductsPublished;
  final ValueChanged<ProductDraft> onSaveProduct;
  final ValueChanged<List<CategoryDraft>> onSaveCategories;
  final ValueChanged<List<String>> onSaveBrands;
  final Future<void> Function(CatalogueState state) onSaveCatalogueStructure;
  final Future<File> Function(String path) onResolvePhotoInboxImage;
  final Future<bool> Function() onCheckPhotoInboxReady;
  final ValueChanged<BulkPasteImportResult> onImportBulkPaste;
  final Future<void> Function(CatalogueState state) onRestoreBackup;
  final Future<void> Function({required String email, required String password})
      onVerifyAdminReset;
  final List<CustomerOrderItemDraft> customerCartItems;
  final CustomerOrderDraft? editingCustomerOrder;
  final ValueChanged<CustomerOrderItemDraft> onAddCustomerCartItem;
  final void Function(int index, double quantity) onUpdateCustomerCartQuantity;
  final ValueChanged<int> onRemoveCustomerCartItem;
  final VoidCallback onClearCustomerCart;
  final Future<void> Function({
    required String customerName,
    required String customerPhone,
    required String notes,
  }) onPlaceCustomerOrder;
  final Future<void> Function(CustomerOrderDraft order) onEditCustomerOrder;
  final Future<void> Function(CustomerOrderDraft order) onCancelCustomerOrder;
  final Future<void> Function(CatalogueState state) onResetCatalogueData;

  @override
  Widget build(BuildContext context) {
    final sections = profile.canManageCatalogue
        ? const [
            _CatalogueSection.dashboard,
            _CatalogueSection.products,
            _CatalogueSection.stock,
            _CatalogueSection.orders,
            _CatalogueSection.studioTools,
          ]
        : profile.role == CrimsonUserRole.customer
            ? const [
                _CatalogueSection.dashboard,
                _CatalogueSection.products,
                _CatalogueSection.orders,
                _CatalogueSection.account,
              ]
            : const [
                _CatalogueSection.dashboard,
                _CatalogueSection.products,
              ];
    final activeSection = _mobileSection(section, sections);
    return Scaffold(
      backgroundColor: _CrimsonColors.background,
      body: SafeArea(
        child: RefreshIndicator(
          onRefresh: onRefreshCatalogue,
          color: _CrimsonColors.crimson,
          child: AnimatedSwitcher(
            duration: const Duration(milliseconds: 300),
            child: Padding(
              key: ValueKey(section),
              padding: const EdgeInsets.fromLTRB(14, 10, 14, 0),
              child: _bodyForSection(context),
            ),
          ),
        ),
      ),
      bottomNavigationBar: NavigationBar(
        selectedIndex: activeSection,
        backgroundColor: Colors.white,
        indicatorColor: _CrimsonColors.crimsonLight,
        onDestinationSelected: (index) => onSectionChanged(sections[index]),
        destinations: [for (final item in sections) _mobileDestination(item)],
      ),
    );
  }

  int _mobileSection(
    _CatalogueSection section,
    List<_CatalogueSection> sections,
  ) {
    final mapped = section == _CatalogueSection.categories
        ? _CatalogueSection.products
        : section;
    final index = sections.indexOf(mapped);
    return index < 0 ? 0 : index;
  }

  NavigationDestination _mobileDestination(_CatalogueSection section) {
    return switch (section) {
      _CatalogueSection.dashboard => const NavigationDestination(
          icon: Icon(Icons.home_outlined),
          selectedIcon: Icon(Icons.home_rounded),
          label: 'Home',
        ),
      _CatalogueSection.products => const NavigationDestination(
          icon: Icon(Icons.inventory_2_outlined),
          selectedIcon: Icon(Icons.inventory_2_rounded),
          label: 'Products',
        ),
      _CatalogueSection.stock => const NavigationDestination(
          icon: Icon(Icons.warehouse_outlined),
          selectedIcon: Icon(Icons.warehouse_rounded),
          label: 'Stock',
        ),
      _CatalogueSection.orders => NavigationDestination(
          icon: const Icon(Icons.shopping_bag_outlined),
          selectedIcon: const Icon(Icons.shopping_bag_rounded),
          label: profile.role == CrimsonUserRole.customer ? 'Cart' : 'Orders',
        ),
      _CatalogueSection.account => const NavigationDestination(
          icon: Icon(Icons.person_outline),
          selectedIcon: Icon(Icons.person_rounded),
          label: 'Account',
        ),
      _CatalogueSection.addProduct => const NavigationDestination(
          icon: Icon(Icons.add_circle_outline),
          selectedIcon: Icon(Icons.add_circle),
          label: 'Add',
        ),
      _CatalogueSection.settings => const NavigationDestination(
          icon: Icon(Icons.settings_outlined),
          selectedIcon: Icon(Icons.settings_rounded),
          label: 'Settings',
        ),
      _ => const NavigationDestination(
          icon: Icon(Icons.build_outlined),
          selectedIcon: Icon(Icons.build_rounded),
          label: 'Tools',
        ),
    };
  }

  Widget _bodyForSection(BuildContext context) {
    return switch (section) {
      _CatalogueSection.dashboard => _MobileHomeScreen(
          state: state,
          profile: profile,
          onLogout: onLogout,
          onOpenProducts: () => onSectionChanged(_CatalogueSection.products),
          onOpenCart: () => onSectionChanged(_CatalogueSection.orders),
          onOpenProductCategory: onOpenProductCategory,
          onAddProduct: onAddProduct,
          onBulkPaste: () => onSectionChanged(_CatalogueSection.bulkPaste),
          cloudStatus: cloudStatus,
          onSelectProduct: onSelectProduct,
          onEditProduct: onEditProduct,
          onAddCustomerCartItem: onAddCustomerCartItem,
        ),
      _CatalogueSection.products => _MobileProductsScreen(
          state: state,
          profile: profile,
          onSelectProduct: onSelectProduct,
          onEditProduct: onEditProduct,
          onAddCustomerCartItem: onAddCustomerCartItem,
          onOpenCart: () => onSectionChanged(_CatalogueSection.orders),
          onToggleProductPublished: onToggleProductPublished,
          onSetProductsPublished: onSetProductsPublished,
          onAddProduct: onAddProduct,
          initialCategory: pendingProductCategory,
          initialSubcategory: pendingProductSubcategory,
          onInitialCategoryConsumed: onPendingProductCategoryConsumed,
          onSectionBackChanged: onSectionBackChanged,
          cloudStatus: cloudStatus,
        ),
      _CatalogueSection.stock => _StockScreen(
          state: state,
          onSaveState: onSaveCatalogueStructure,
        ),
      _CatalogueSection.orders => profile.role == CrimsonUserRole.customer
          ? _CustomerCartScreen(
              items: customerCartItems,
              products: state.products,
              categories: state.categories,
              profile: profile,
              onOpenProducts: () =>
                  onSectionChanged(_CatalogueSection.products),
              onSelectProduct: onSelectProduct,
              onEditProduct: onEditProduct,
              onAddCustomerCartItem: onAddCustomerCartItem,
              onUpdateQuantity: onUpdateCustomerCartQuantity,
              onRemoveItem: onRemoveCustomerCartItem,
              onClear: onClearCustomerCart,
              editingOrder: editingCustomerOrder,
              onPlaceOrder: onPlaceCustomerOrder,
            )
          : _OrdersScreen(
              state: state,
              profile: profile,
              mode: _OrderWorkspaceMode.newOrder,
              onSaveState: onSaveCatalogueStructure,
            ),
      _CatalogueSection.account => _CustomerAccountScreen(
          profile: profile,
          orders: state.customerOrders,
          cloudStatus: cloudStatus,
          onRefreshCatalogue: onRefreshCatalogue,
          onOpenProducts: () => onSectionChanged(_CatalogueSection.products),
          onEditOrder: onEditCustomerOrder,
          onCancelOrder: onCancelCustomerOrder,
          onLogout: onLogout,
        ),
      _CatalogueSection.categories => _CategoriesScreen(
          state: state,
          onSaveCategories: onSaveCategories,
          onSaveBrands: onSaveBrands,
          onSaveState: onSaveCatalogueStructure,
          onOpenProducts: () => onSectionChanged(_CatalogueSection.products),
        ),
      _CatalogueSection.addProduct => _MobileAddProductScreen(
          editingProduct: editingProduct,
          categories: state.categories,
          brands: state.brands,
          onSaveProduct: onSaveProduct,
          onSaveCategories: onSaveCategories,
          onCancel: () => onSectionChanged(_CatalogueSection.products),
          cloudStatus: cloudStatus,
        ),
      _CatalogueSection.photoInbox => PhotoInboxScreen(
          state: state,
          onSaveState: onSaveCatalogueStructure,
          onResolveImage: onResolvePhotoInboxImage,
          onCheckCloudReady: onCheckPhotoInboxReady,
        ),
      _CatalogueSection.bulkPaste => _MobileBulkPasteScreen(
          products: state.products,
          onImport: onImportBulkPaste,
          cloudStatus: cloudStatus,
        ),
      _CatalogueSection.settings => _MobileSettingsScreen(
          state: state,
          storePath: storePath,
          cloudStatus: cloudStatus,
          profile: profile,
          onLogout: onLogout,
          onSaveState: onSaveCatalogueStructure,
        ),
      _ => profile.canManageCatalogue
          ? _MobileToolsScreen(
              state: state,
              storePath: storePath,
              cloudStatus: cloudStatus,
              onOpenBulkPaste: () =>
                  onSectionChanged(_CatalogueSection.bulkPaste),
              onOpenBackup: () =>
                  onSectionChanged(_CatalogueSection.studioTools),
              onOpenCategories: () =>
                  onSectionChanged(_CatalogueSection.categories),
              onOpenPhotoInbox: () =>
                  onSectionChanged(_CatalogueSection.photoInbox),
              onRestoreBackup: onRestoreBackup,
              onVerifyAdminReset: onVerifyAdminReset,
              onResetCatalogueData: onResetCatalogueData,
              onSaveState: onSaveCatalogueStructure,
              onAddProduct: onAddProduct,
              onOpenSettings: () =>
                  onSectionChanged(_CatalogueSection.settings),
            )
          : _MobileProductsScreen(
              state: state,
              profile: profile,
              onSelectProduct: onSelectProduct,
              onEditProduct: onEditProduct,
              onAddCustomerCartItem: onAddCustomerCartItem,
              onOpenCart: () => onSectionChanged(_CatalogueSection.orders),
              onToggleProductPublished: onToggleProductPublished,
              onSetProductsPublished: onSetProductsPublished,
              onAddProduct: onAddProduct,
              initialCategory: pendingProductCategory,
              initialSubcategory: pendingProductSubcategory,
              onInitialCategoryConsumed: onPendingProductCategoryConsumed,
              onSectionBackChanged: onSectionBackChanged,
              cloudStatus: cloudStatus,
            ),
    };
  }
}

class _MobileHomeScreen extends StatelessWidget {
  const _MobileHomeScreen({
    required this.state,
    required this.profile,
    required this.onLogout,
    required this.onOpenProducts,
    required this.onOpenCart,
    required this.onOpenProductCategory,
    required this.onAddProduct,
    required this.onBulkPaste,
    required this.cloudStatus,
    required this.onSelectProduct,
    required this.onEditProduct,
    required this.onAddCustomerCartItem,
  });

  final CatalogueState state;
  final CrimsonProfile profile;
  final Future<void> Function() onLogout;
  final VoidCallback onOpenProducts;
  final VoidCallback onOpenCart;
  final ValueChanged<String> onOpenProductCategory;
  final VoidCallback onAddProduct;
  final VoidCallback onBulkPaste;
  final CloudSyncStatus cloudStatus;
  final ValueChanged<ProductDraft> onSelectProduct;
  final ValueChanged<ProductDraft> onEditProduct;
  final ValueChanged<CustomerOrderItemDraft> onAddCustomerCartItem;

  @override
  Widget build(BuildContext context) {
    final products = _activeProductsForRole(state, profile);
    final categories = _CategorySummary.fromProducts(
      products,
      categories: state.categories,
    ).where((summary) => summary.name.isNotEmpty).take(6).toList();
    final recent = products.take(8).toList();

    void openCustomerProductDetail(BuildContext context, ProductDraft product) {
      _openMobileProductDetail(
        context,
        product,
        onSelectProduct,
        onEditProduct,
        profile,
        onAddCustomerCartItem,
        onOpenCart,
        categoryDiscountPercent:
            categoryDiscountFor(state.categories, product.category),
      );
    }

    void showCustomerSearch(BuildContext context) {
      final products = _activeProductsForRole(state, profile);
      showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        backgroundColor: Colors.white,
        showDragHandle: true,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
        ),
        builder: (sheetContext) => _CustomerSearchSheet(
          products: products,
          categories: state.categories,
          terminology: state.searchTerminology,
          onOpenProduct: (product) {
            Navigator.pop(sheetContext);
            openCustomerProductDetail(context, product);
          },
        ),
      );
    }

    if (!profile.canManageCatalogue) {
      return Column(
        children: [
          _MobileTopBar(
            title: 'Crimson Decore',
            subtitle: 'Premium hardware catalogue',
            trailing: IconButton(
              tooltip: 'Search products',
              onPressed: () => showCustomerSearch(context),
              icon: const Icon(Icons.search_rounded),
            ),
          ),
          const SizedBox(height: 12),
          Expanded(
            child: _CustomerStorefrontHome(
              state: state,
              profile: profile,
              compact: true,
              onOpenProducts: onOpenProducts,
              onOpenProductCategory: onOpenProductCategory,
              onSelectProduct: (product) => openCustomerProductDetail(
                context,
                product,
              ),
            ),
          ),
        ],
      );
    }

    return CustomScrollView(
      slivers: [
        SliverToBoxAdapter(
          child: _MobileTopBar(
            title: 'Catalogue',
            subtitle: 'Crimson Decore catalogue',
            trailing: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                _CloudStatusChip(status: cloudStatus, compact: true),
                _RoleChip(profile: profile),
                IconButton(
                  tooltip: 'Logout',
                  onPressed: onLogout,
                  icon: const Icon(Icons.logout_rounded),
                ),
                IconButton(
                  tooltip: 'Search products',
                  onPressed: onOpenProducts,
                  icon: const Icon(Icons.search_rounded),
                ),
              ],
            ),
          ),
        ),
        SliverToBoxAdapter(
          child: Padding(
            padding: const EdgeInsets.only(top: 14, bottom: 14),
            child: InkWell(
              borderRadius: BorderRadius.circular(16),
              onTap: onOpenProducts,
              child: IgnorePointer(
                child: TextField(
                  decoration: _inputDecoration(
                    'Search products, SKU, finish, size...',
                  ).copyWith(prefixIcon: const Icon(Icons.search_rounded)),
                ),
              ),
            ),
          ),
        ),
        SliverToBoxAdapter(
          child: Row(
            children: [
              if (profile.canManageCatalogue) ...[
                Expanded(
                  child: _MobileQuickAction(
                    icon: Icons.add_rounded,
                    label: 'Add Product',
                    onTap: onAddProduct,
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: _MobileQuickAction(
                    icon: Icons.content_paste_go_outlined,
                    label: 'Bulk Paste',
                    onTap: onBulkPaste,
                  ),
                ),
                const SizedBox(width: 10),
              ],
              Expanded(
                child: _MobileQuickAction(
                  icon: Icons.inventory_2_outlined,
                  label: 'Products',
                  onTap: onOpenProducts,
                ),
              ),
            ],
          ),
        ),
        const SliverToBoxAdapter(child: SizedBox(height: 20)),
        const SliverToBoxAdapter(
          child: _MobileSectionTitle(
            title: 'Categories',
            subtitle: 'Browse by product family',
          ),
        ),
        const SliverToBoxAdapter(child: SizedBox(height: 10)),
        categories.isEmpty
            ? const SliverToBoxAdapter(child: _EmptyListMessage())
            : SliverGrid.builder(
                gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount: 2,
                  crossAxisSpacing: 12,
                  mainAxisSpacing: 12,
                  childAspectRatio: 0.92,
                ),
                itemCount: categories.length,
                itemBuilder: (context, index) => _MobileCategoryTile(
                  summary: categories[index],
                  onTap: () => onOpenProductCategory(categories[index].name),
                ),
              ),
        const SliverToBoxAdapter(child: SizedBox(height: 20)),
        const SliverToBoxAdapter(
          child: _MobileSectionTitle(
            title: 'Recent Products',
            subtitle: 'Tap to view details',
          ),
        ),
        const SliverToBoxAdapter(child: SizedBox(height: 10)),
        SliverList.separated(
          itemCount: recent.length,
          separatorBuilder: (_, __) => const SizedBox(height: 10),
          itemBuilder: (context, index) => _MobileProductListTile(
            product: recent[index],
            onTap: () => _openMobileProductDetail(
              context,
              recent[index],
              onSelectProduct,
              onEditProduct,
              profile,
              onAddCustomerCartItem,
              onOpenCart,
              categoryDiscountPercent:
                  categoryDiscountFor(state.categories, recent[index].category),
            ),
          ),
        ),
        const SliverToBoxAdapter(child: SizedBox(height: 18)),
      ],
    );
  }
}

class _CustomerSearchSheet extends StatefulWidget {
  const _CustomerSearchSheet({
    required this.products,
    required this.categories,
    required this.terminology,
    required this.onOpenProduct,
  });

  final List<ProductDraft> products;
  final List<CategoryDraft> categories;
  final List<SearchTerminologyDraft> terminology;
  final ValueChanged<ProductDraft> onOpenProduct;

  @override
  State<_CustomerSearchSheet> createState() => _CustomerSearchSheetState();
}

class _CustomerSearchSheetState extends State<_CustomerSearchSheet> {
  final _controller = TextEditingController();
  final _focusNode = FocusNode();

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance
        .addPostFrameCallback((_) => _focusNode.requestFocus());
  }

  @override
  void dispose() {
    _controller.dispose();
    _focusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final query = cleanText(_controller.text);
    final results = query.isEmpty
        ? widget.products.take(12).toList()
        : filterCatalogueProducts(
            widget.products,
            CatalogueProductFilter(query: query),
            categories: widget.categories,
            terminology: widget.terminology,
          ).take(30).toList();
    return SafeArea(
      child: Padding(
        padding: EdgeInsets.fromLTRB(
          16,
          4,
          16,
          16 + MediaQuery.viewInsetsOf(context).bottom,
        ),
        child: SizedBox(
          height: MediaQuery.sizeOf(context).height * 0.76,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'Search catalogue',
                style: Theme.of(context).textTheme.titleLarge?.copyWith(
                      fontWeight: FontWeight.w900,
                    ),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: _controller,
                focusNode: _focusNode,
                textInputAction: TextInputAction.search,
                onChanged: (_) => setState(() {}),
                decoration: _inputDecoration(
                  'Search name, size, finish, category...',
                ).copyWith(
                  prefixIcon: const Icon(Icons.search_rounded),
                  suffixIcon: query.isEmpty
                      ? null
                      : IconButton(
                          tooltip: 'Clear search',
                          onPressed: () {
                            _controller.clear();
                            setState(() {});
                          },
                          icon: const Icon(Icons.close_rounded),
                        ),
                ),
              ),
              const SizedBox(height: 12),
              Expanded(
                child: results.isEmpty
                    ? const _EmptyListMessage()
                    : ListView.separated(
                        itemCount: results.length,
                        separatorBuilder: (_, __) => const SizedBox(height: 8),
                        itemBuilder: (context, index) => _MobileProductListTile(
                          product: results[index],
                          onTap: () => widget.onOpenProduct(results[index]),
                        ),
                      ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _MobileProductsScreen extends StatefulWidget {
  const _MobileProductsScreen({
    required this.state,
    required this.profile,
    required this.onSelectProduct,
    required this.onEditProduct,
    required this.onAddCustomerCartItem,
    required this.onOpenCart,
    required this.onToggleProductPublished,
    required this.onSetProductsPublished,
    required this.onAddProduct,
    required this.initialCategory,
    required this.initialSubcategory,
    required this.onInitialCategoryConsumed,
    required this.onSectionBackChanged,
    required this.cloudStatus,
  });

  final CatalogueState state;
  final CrimsonProfile profile;
  final ValueChanged<ProductDraft> onSelectProduct;
  final ValueChanged<ProductDraft> onEditProduct;
  final ValueChanged<CustomerOrderItemDraft> onAddCustomerCartItem;
  final VoidCallback onOpenCart;
  final void Function(ProductDraft product, bool isPublished)
      onToggleProductPublished;
  final Future<void> Function(Set<String> productIds, bool isPublished)
      onSetProductsPublished;
  final VoidCallback onAddProduct;
  final String initialCategory;
  final String initialSubcategory;
  final VoidCallback onInitialCategoryConsumed;
  final void Function(VoidCallback? handler) onSectionBackChanged;
  final CloudSyncStatus cloudStatus;

  @override
  State<_MobileProductsScreen> createState() => _MobileProductsScreenState();
}

class _MobileProductsScreenState extends State<_MobileProductsScreen> {
  final _searchController = TextEditingController();
  Timer? _mobileSearchDebounce;
  String _category = '';
  String _subcategory = '';
  String _categorySearchReturnQuery = '';
  final Set<String> _selectedProductIds = {};
  final _multiExportService = const MultiProductExportService();
  bool _exportingSelection = false;
  bool _updatingSelectionVisibility = false;
  bool? _registeredBackAvailable;
  CatalogueState? _cachedProductsState;
  CrimsonUserRole? _cachedProductsRole;
  List<ProductDraft>? _cachedProducts;

  List<ProductDraft> get _visibleProducts {
    if (identical(_cachedProductsState, widget.state) &&
        _cachedProductsRole == widget.profile.role &&
        _cachedProducts != null) {
      return _cachedProducts!;
    }
    final products = _activeProductsForRole(widget.state, widget.profile);
    _cachedProductsState = widget.state;
    _cachedProductsRole = widget.profile.role;
    _cachedProducts = products;
    return products;
  }

  @override
  void initState() {
    super.initState();
    _applyInitialCategory();
  }

  @override
  void didUpdateWidget(covariant _MobileProductsScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.initialCategory != oldWidget.initialCategory ||
        widget.initialSubcategory != oldWidget.initialSubcategory) {
      _applyInitialCategory();
    }
  }

  void _applyInitialCategory() {
    final category = cleanText(widget.initialCategory);
    if (category.isEmpty) return;
    _searchController.clear();
    _selectedProductIds.clear();
    _category = category;
    _subcategory = cleanText(widget.initialSubcategory);
    _categorySearchReturnQuery = '';
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) widget.onInitialCategoryConsumed();
    });
  }

  @override
  void dispose() {
    widget.onSectionBackChanged(null);
    _mobileSearchDebounce?.cancel();
    _searchController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    _syncMobileProductsBackHandler();
    final products = _visibleProducts;
    final searchActiveNow = cleanText(_searchController.text).isNotEmpty;
    final filtered = filterCatalogueProducts(
      products,
      CatalogueProductFilter(
        query: _searchController.text,
        category: _category,
        subcategory: _subcategory == '__all__' ? '' : _subcategory,
      ),
      categories: widget.state.categories,
      terminology: widget.state.searchTerminology,
    );
    if (!searchActiveNow) filtered.sort(_compareProductsForCatalogue);
    final stockTotals = _displayProductStockTotals(widget.state);
    final categories = _CategorySummary.fromProducts(
      products,
      categories: widget.state.categories,
    );
    final matchingCategories = widget.profile.canManageCatalogue &&
            searchActiveNow &&
            cleanText(_category).isEmpty
        ? categories
            .where((summary) =>
                categoryNameMatchesSearch(
                    summary.name, _searchController.text))
            .toList(growable: false)
        : const <_CategorySummary>[];
    final categoryProducts = _category.isEmpty
        ? products
        : products
            .where((product) =>
                _normalUi(product.category) == _normalUi(_category))
            .toList();
    final selectedCategoryDraft =
        widget.state.categories.cast<CategoryDraft?>().firstWhere(
              (category) =>
                  category != null && _sameName(category.name, _category),
              orElse: () => null,
            );
    final subcategories = _SubcategorySummary.fromProducts(
      categoryProducts,
      category: selectedCategoryDraft,
    );
    final searchMode = searchActiveNow;
    final customerCatalogueView =
        widget.profile.role == CrimsonUserRole.customer;
    final showCategoryBrowser = !searchMode && cleanText(_category).isEmpty;
    final showSubcategoryBrowser = !customerCatalogueView &&
        !searchMode &&
        cleanText(_category).isNotEmpty &&
        cleanText(_subcategory).isEmpty &&
        subcategories.isNotEmpty;
    final canSelectForExport =
        widget.profile.canExportPdf || widget.profile.canShare;
    final canManageCatalogue = widget.profile.canManageCatalogue;
    final canSelectProducts = canSelectForExport || canManageCatalogue;

    return CustomScrollView(
      slivers: [
        SliverToBoxAdapter(
          child: _MobileTopBar(
            title: 'Products',
            subtitle: '${filtered.length} visible products',
            trailing: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                IconButton(
                  tooltip: 'Filter products',
                  onPressed: () => _showCategoryFilter(categories),
                  icon: const Icon(Icons.tune_rounded),
                ),
                _CloudStatusChip(status: widget.cloudStatus, compact: true),
                const SizedBox(width: 6),
                if (widget.profile.canManageCatalogue)
                  IconButton.filled(
                    tooltip: 'Add product',
                    onPressed: widget.onAddProduct,
                    icon: const Icon(Icons.add_rounded),
                  ),
              ],
            ),
          ),
        ),
        SliverToBoxAdapter(
          child: Padding(
            padding: const EdgeInsets.only(top: 12, bottom: 12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                TextField(
                  controller: _searchController,
                  onChanged: (_) {
                    _categorySearchReturnQuery = '';
                    _mobileSearchDebounce?.cancel();
                    _mobileSearchDebounce =
                        Timer(const Duration(milliseconds: 75), () {
                      if (mounted) setState(() {});
                    });
                  },
                  decoration: _inputDecoration(
                    'Try: black 4 inch handle, rose gold knob...',
                  ).copyWith(
                    prefixIcon: const Icon(Icons.search_rounded),
                    suffixIcon: _searchController.text.isEmpty
                        ? null
                        : IconButton(
                            onPressed: () {
                              _searchController.clear();
                              setState(() {});
                            },
                            icon: const Icon(Icons.close_rounded),
                          ),
                  ),
                ),
                _SmartSearchChipRow(query: _searchController.text),
              ],
            ),
          ),
        ),
        SliverToBoxAdapter(
          child: _MobileBrowsePath(
            category: _category,
            subcategory: _subcategory,
            rootLabel: _categorySearchReturnQuery.isEmpty
                ? 'Categories'
                : 'Search results',
            onCategories: () => setState(() {
              _returnToMobileCategories();
            }),
            onSubcategories: () => setState(() => _subcategory = ''),
          ),
        ),
        if (canSelectProducts &&
            (_selectedProductIds.isNotEmpty ||
                (!showCategoryBrowser && !showSubcategoryBrowser)))
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.only(top: 10),
              child: CatalogueSelectionBar(
                selectedCount: _selectedProductIds.length,
                visibleCount: filtered.length,
                busy: _exportingSelection || _updatingSelectionVisibility,
                compact: true,
                onSelectAll: () => _toggleMobileSelectionGroup(
                  filtered.map((product) => product.id),
                ),
                onClear: () => setState(_selectedProductIds.clear),
                onExportImage: _exportMobileCatalogueImages,
                onExportPdf: _exportMobileCataloguePdf,
                onExportStickers: _exportMobileStickerSheets,
                onMakeLive: canManageCatalogue
                    ? () => _updateMobileSelectionVisibility(true)
                    : null,
                onMakeHidden: canManageCatalogue
                    ? () => _updateMobileSelectionVisibility(false)
                    : null,
              ),
            ),
          ),
        const SliverToBoxAdapter(child: SizedBox(height: 12)),
        if (showCategoryBrowser)
          SliverGrid.builder(
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 2,
              crossAxisSpacing: 10,
              mainAxisSpacing: 10,
              childAspectRatio: 0.96,
            ),
            itemCount:
                categories.where((summary) => summary.name.isNotEmpty).length,
            itemBuilder: (context, index) {
              final summary = categories
                  .where((item) => item.name.isNotEmpty)
                  .toList()[index];
              final ids = productIdsForCategory(products, summary.name);
              return _MobileBrowseCard(
                icon: Icons.category_outlined,
                imagePath: summary.imagePath,
                title: summary.name,
                subtitle: '${summary.productCount} products',
                selected: isSelectionGroupComplete(_selectedProductIds, ids),
                onSelectionToggle: canSelectProducts
                    ? () => _toggleMobileSelectionGroup(ids)
                    : null,
                onTap: () => setState(() {
                  _category = summary.name;
                  _subcategory = '';
                }),
              );
            },
          )
        else if (showSubcategoryBrowser)
          SliverGrid.builder(
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 2,
              crossAxisSpacing: 10,
              mainAxisSpacing: 10,
              childAspectRatio: 0.96,
            ),
            itemCount: subcategories.length + 1,
            itemBuilder: (context, index) {
              if (index == 0) {
                final ids = categoryProducts.map((product) => product.id);
                return _MobileBrowseCard(
                  icon: Icons.inventory_2_outlined,
                  imagePath: selectedCategoryDraft?.imagePath ?? '',
                  title: 'All $_category',
                  subtitle: '${categoryProducts.length} products',
                  selected: isSelectionGroupComplete(_selectedProductIds, ids),
                  onSelectionToggle: canSelectProducts
                      ? () => _toggleMobileSelectionGroup(ids)
                      : null,
                  onTap: () => setState(() => _subcategory = '__all__'),
                );
              }
              final summary = subcategories[index - 1];
              final ids = productIdsForSubcategory(
                products,
                category: _category,
                subcategory: summary.name,
              );
              return _MobileBrowseCard(
                icon: Icons.folder_outlined,
                imagePath: summary.imagePath,
                title: summary.name,
                subtitle: '${summary.productCount} products',
                selected: isSelectionGroupComplete(_selectedProductIds, ids),
                onSelectionToggle: canSelectProducts
                    ? () => _toggleMobileSelectionGroup(ids)
                    : null,
                onTap: () => setState(() => _subcategory = summary.name),
              );
            },
          )
        else if (filtered.isEmpty && matchingCategories.isEmpty)
          const SliverToBoxAdapter(child: _EmptyListMessage())
        else ...[
          if (matchingCategories.isNotEmpty)
            SliverToBoxAdapter(
              child: _CategorySearchResults(
                categories: matchingCategories,
                compact: true,
                onOpenCategory: _openMobileSearchedCategory,
              ),
            ),
          if (searchActiveNow && filtered.isNotEmpty)
            SliverToBoxAdapter(
              child: _SearchResultsHeading(
                title: 'Products',
                count: filtered.length,
              ),
            ),
          if (filtered.isNotEmpty)
          SliverGrid.builder(
            gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 2,
              crossAxisSpacing: 12,
              mainAxisSpacing: 12,
              childAspectRatio: 0.68,
            ),
            itemCount: filtered.length,
            itemBuilder: (context, index) {
              final product = filtered[index];
              return _MobileProductCard(
                product: product,
                stockQuantity: stockTotals[product.id],
                selected: _selectedProductIds.contains(product.id),
                onSelectionToggle: canSelectProducts
                    ? () => _toggleMobileProduct(product.id)
                    : null,
                onTogglePublished: widget.profile.canManageCatalogue
                    ? () => widget.onToggleProductPublished(
                          product,
                          !product.isPublished,
                        )
                    : null,
                onTap: () => _openMobileProductDetail(
                  context,
                  product,
                  widget.onSelectProduct,
                  widget.onEditProduct,
                  widget.profile,
                  widget.onAddCustomerCartItem,
                  widget.onOpenCart,
                  onReturnToDraft: widget.profile.canManageCatalogue
                      ? () {
                          Navigator.of(context).pop();
                          widget.onToggleProductPublished(product, false);
                        }
                      : null,
                  onMakeLive: widget.profile.canManageCatalogue
                      ? () {
                          Navigator.of(context).pop();
                          widget.onToggleProductPublished(product, true);
                        }
                      : null,
                  categoryDiscountPercent: categoryDiscountFor(
                    widget.state.categories,
                    product.category,
                  ),
                ),
              );
            },
          ),
        ],
        const SliverToBoxAdapter(child: SizedBox(height: 18)),
      ],
    );
  }

  bool get _canBackWithinMobileProducts =>
      _selectedProductIds.isNotEmpty ||
      cleanText(_subcategory).isNotEmpty ||
      cleanText(_category).isNotEmpty ||
      cleanText(_searchController.text).isNotEmpty;

  void _openMobileSearchedCategory(String category) {
    setState(() {
      _categorySearchReturnQuery = _searchController.text;
      _searchController.clear();
      _category = category;
      _subcategory = '';
    });
  }

  void _returnToMobileCategories() {
    _category = '';
    _subcategory = '';
    if (_categorySearchReturnQuery.isNotEmpty) {
      _searchController.text = _categorySearchReturnQuery;
      _categorySearchReturnQuery = '';
    }
  }

  void _syncMobileProductsBackHandler() {
    final available = _canBackWithinMobileProducts;
    if (_registeredBackAvailable == available) return;
    _registeredBackAvailable = available;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      widget.onSectionBackChanged(available ? _backWithinMobileProducts : null);
    });
  }

  void _backWithinMobileProducts() {
    if (!mounted) return;
    setState(() {
      if (_selectedProductIds.isNotEmpty) {
        _selectedProductIds.clear();
      } else if (cleanText(_subcategory).isNotEmpty) {
        _subcategory = '';
      } else if (cleanText(_category).isNotEmpty) {
        _returnToMobileCategories();
      } else if (cleanText(_searchController.text).isNotEmpty) {
        _searchController.clear();
      }
    });
  }

  void _toggleMobileProduct(String productId) {
    setState(() {
      final next = toggleProductSelection(_selectedProductIds, productId);
      _selectedProductIds
        ..clear()
        ..addAll(next);
    });
  }

  void _toggleMobileSelectionGroup(Iterable<String> productIds) {
    setState(() {
      final next = toggleSelectionGroup(_selectedProductIds, productIds);
      _selectedProductIds
        ..clear()
        ..addAll(next);
    });
  }

  Future<void> _updateMobileSelectionVisibility(bool isPublished) async {
    if (_selectedProductIds.isEmpty || _updatingSelectionVisibility) return;
    final ids = Set<String>.from(_selectedProductIds);
    setState(() => _updatingSelectionVisibility = true);
    try {
      await widget.onSetProductsPublished(ids, isPublished);
      if (mounted) {
        _showMessage(
          context,
          isPublished
              ? '${ids.length} selected products are now live.'
              : '${ids.length} selected products are now hidden.',
        );
      }
    } finally {
      if (mounted) setState(() => _updatingSelectionVisibility = false);
    }
  }

  List<ProductDraft> get _mobileSelectedProducts => (widget.state.products
      .where((product) =>
          _selectedProductIds.contains(product.id) && !product.isComingSoon)
      .toList(growable: false)
    ..sort(_compareProductsForCatalogue));

  Future<void> _exportMobileCatalogueImages() async {
    final imageLayout = await _chooseCatalogueImageLayout(context);
    if (!mounted || imageLayout == null) return;
    await _runMobileSelectionExport(() async {
      final base = await _mobileExportPath('crimson_selected_catalogue.png');
      final paths = await _multiExportService.exportImages(
        products: _mobileSelectedProducts,
        path: base,
        imageLayout: imageLayout,
      );
      await const MethodChannel('com.mycrimson.cataloguestudio/storage')
          .invokeMethod<void>('shareFiles', {
        'paths': paths,
        'mimeType': 'image/png',
        'title': 'Share Crimson catalogue images',
      });
    });
  }

  Future<void> _exportMobileStickerSheets() async {
    await _runMobileSelectionExport(() async {
      final base = await _mobileExportPath('crimson_selected_stickers.png');
      final paths = await _multiExportService.exportStickerSheetImages(
        products: _mobileSelectedProducts,
        path: base,
      );
      await const MethodChannel('com.mycrimson.cataloguestudio/storage')
          .invokeMethod<void>('shareFiles', {
        'paths': paths,
        'mimeType': 'image/png',
        'title': 'Share Crimson 60x40 sticker sheet',
      });
    });
  }

  Future<void> _exportMobileCataloguePdf() async {
    final imageLayout = await _chooseCatalogueImageLayout(context);
    if (!mounted || imageLayout == null) return;
    await _runMobileSelectionExport(() async {
      final base = await _mobileExportPath('crimson_selected_page.png');
      final pages = await _multiExportService.exportImages(
        products: _mobileSelectedProducts,
        path: base,
        imageLayout: imageLayout,
      );
      final pdfPath = await _mobileExportPath('Crimson_Selected_Catalogue.pdf');
      await const MethodChannel('com.mycrimson.cataloguestudio/storage')
          .invokeMethod<void>('createPdfFromImages', {
        'imagePaths': pages,
        'outputPath': pdfPath,
      });
      await const MethodChannel('com.mycrimson.cataloguestudio/storage')
          .invokeMethod<void>('shareFiles', {
        'paths': [pdfPath],
        'mimeType': 'application/pdf',
        'title': 'Share Crimson catalogue PDF',
      });
    });
  }

  Future<String> _mobileExportPath(String fileName) async {
    final safeFile = fileName.replaceAll(RegExp(r'[^A-Za-z0-9._-]+'), '_');
    try {
      final filesDir = await const MethodChannel(
        'com.mycrimson.cataloguestudio/storage',
      ).invokeMethod<String>('filesDir');
      final cleanDir = cleanText(filesDir);
      if (cleanDir.isNotEmpty) {
        final directory = Directory(
          '$cleanDir${Platform.pathSeparator}exports',
        );
        await directory.create(recursive: true);
        return '${directory.path}${Platform.pathSeparator}$safeFile';
      }
    } on Object {
      // Fall back below if Android storage is not ready yet.
    }
    final directory = await Directory.systemTemp.createTemp('crimson_export_');
    return '${directory.path}${Platform.pathSeparator}$safeFile';
  }

  Future<void> _runMobileSelectionExport(Future<void> Function() action) async {
    if (_exportingSelection) return;
    if (_mobileSelectedProducts.isEmpty) {
      _showMessage(
          context, 'Select a live product to create a priced catalogue.');
      return;
    }
    setState(() => _exportingSelection = true);
    try {
      await action();
    } on Object catch (error) {
      if (mounted) _showMessage(context, 'Catalogue export failed: $error');
    } finally {
      if (mounted) setState(() => _exportingSelection = false);
    }
  }

  Future<void> _showCategoryFilter(List<_CategorySummary> categories) async {
    await showModalBottomSheet<void>(
      context: context,
      showDragHandle: true,
      builder: (context) => SafeArea(
        child: ListView(
          padding: const EdgeInsets.fromLTRB(18, 0, 18, 18),
          children: [
            Text(
              'Filter Products',
              style: Theme.of(context)
                  .textTheme
                  .titleLarge
                  ?.copyWith(fontWeight: FontWeight.w900),
            ),
            const SizedBox(height: 12),
            for (final summary in categories)
              ListTile(
                contentPadding: EdgeInsets.zero,
                title: Text(summary.name.isEmpty ? 'All' : summary.name),
                subtitle: Text('${summary.productCount} products'),
                trailing: (_category.isEmpty && summary.name.isEmpty) ||
                        _normalUi(_category) == _normalUi(summary.name)
                    ? const Icon(Icons.check_rounded,
                        color: _CrimsonColors.crimson)
                    : null,
                onTap: () {
                  setState(() {
                    _category = summary.name;
                    _subcategory = '';
                    _categorySearchReturnQuery = '';
                  });
                  Navigator.pop(context);
                },
              ),
          ],
        ),
      ),
    );
  }
}

