class _MobileBulkPasteScreenState extends State<_MobileBulkPasteScreen> {
  final _paste = TextEditingController();
  BulkPasteImportResult _result = const BulkPasteImportResult(
    products: [],
    categories: [],
    errors: ['Paste Excel rows to preview import.'],
  );

  @override
  void dispose() {
    _paste.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final variations = _result.products.fold<int>(
      0,
      (sum, product) => sum + product.variations.length,
    );
    return CustomScrollView(
      slivers: [
        SliverToBoxAdapter(
          child: _MobileTopBar(
            title: 'Bulk Paste',
            subtitle: 'Paste Excel rows into the catalogue',
            trailing: _CloudStatusChip(
              status: widget.cloudStatus,
              compact: true,
            ),
          ),
        ),
        SliverToBoxAdapter(
          child: Padding(
            padding: const EdgeInsets.only(top: 14),
            child: SizedBox(
              height: 230,
              child: TextField(
                controller: _paste,
                expands: true,
                maxLines: null,
                minLines: null,
                textAlignVertical: TextAlignVertical.top,
                onChanged: (_) => _preview(),
                decoration: _inputDecoration(
                  'Paste long rows (FINISH, SIZE, PRICE) or a wide matrix (FINISH, KNOB, 96MM, 4 INCH...)',
                ),
              ),
            ),
          ),
        ),
        SliverToBoxAdapter(
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 12),
            child: Wrap(
              spacing: 10,
              runSpacing: 10,
              children: [
                OutlinedButton.icon(
                  onPressed: _loadSample,
                  icon: const Icon(Icons.auto_fix_high_outlined),
                  label: const Text('Sample'),
                ),
                OutlinedButton.icon(
                  onPressed: _preview,
                  icon: const Icon(Icons.visibility_outlined),
                  label: const Text('Preview'),
                ),
                FilledButton.icon(
                  onPressed: _result.products.isEmpty
                      ? null
                      : () => widget.onImport(_result),
                  icon: const Icon(Icons.download_done_outlined),
                  label: const Text('Import'),
                ),
              ],
            ),
          ),
        ),
        SliverToBoxAdapter(
          child: _Surface(
            padding: const EdgeInsets.all(14),
            child: Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                _MiniChip(
                  label: '${_result.products.length} Products',
                  selected: true,
                ),
                _MiniChip(label: '$variations Variations'),
                if (_result.format != BulkPasteImportFormat.unknown)
                  _MiniChip(
                    label: _bulkPasteFormatLabel(_result.format),
                    selected: true,
                  ),
              ],
            ),
          ),
        ),
        if (_result.errors.isNotEmpty)
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.only(top: 12),
              child: _ImportMessages(errors: _result.errors),
            ),
          ),
        const SliverToBoxAdapter(child: SizedBox(height: 12)),
        _result.products.isEmpty
            ? const SliverToBoxAdapter(child: _EmptyBulkPreview())
            : SliverList.separated(
                itemCount: _result.products.length,
                separatorBuilder: (_, __) => const SizedBox(height: 10),
                itemBuilder: (context, index) =>
                    _BulkProductPreview(product: _result.products[index]),
              ),
        const SliverToBoxAdapter(child: SizedBox(height: 18)),
      ],
    );
  }

  void _preview() {
    final parsed = parseBulkPasteProducts(_paste.text);
    final warnings =
        _repositoryDuplicateWarnings(widget.products, parsed.products);
    setState(() => _result = _withAdditionalImportMessages(parsed, warnings));
  }

  void _loadSample() {
    _paste.text = _sampleBulkPasteRows;
    _preview();
  }
}

