class _SearchTerminologyManagerState extends State<_SearchTerminologyManager> {
  late List<SearchTerminologyDraft> _entries;
  bool _saving = false;

  @override
  void initState() {
    super.initState();
    _entries = List<SearchTerminologyDraft>.from(
      widget.state.searchTerminology,
    );
  }

  @override
  void didUpdateWidget(covariant _SearchTerminologyManager oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!_saving &&
        !identical(
          oldWidget.state.searchTerminology,
          widget.state.searchTerminology,
        )) {
      _entries = List<SearchTerminologyDraft>.from(
        widget.state.searchTerminology,
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Search terminology',
                    style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                          fontWeight: FontWeight.w900,
                        ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    'Add one standard term and all abbreviations or spellings that should mean the same thing.',
                    style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                          color: _CrimsonColors.textSecondary,
                        ),
                  ),
                ],
              ),
            ),
            const SizedBox(width: 12),
            FilledButton.icon(
              onPressed: _saving ? null : () => _editEntry(),
              icon: const Icon(Icons.add_rounded),
              label: const Text('Add term'),
            ),
          ],
        ),
        const SizedBox(height: 14),
        _Surface(
          padding: EdgeInsets.zero,
          child: ExpansionTile(
            leading: const Icon(
              Icons.auto_awesome_rounded,
              color: _CrimsonColors.crimson,
            ),
            title: const Text(
              'Built-in hardware terminology',
              style: TextStyle(fontWeight: FontWeight.w900),
            ),
            subtitle: Text(
              '${builtInSearchTerminology.length} protected defaults included',
            ),
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
                child: Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: [
                    for (final entry in builtInSearchTerminology)
                      Chip(
                        label: Text(
                          '${entry.canonical}: ${entry.aliases.join(', ')}',
                        ),
                        backgroundColor: _CrimsonColors.crimsonLight,
                        side: BorderSide.none,
                      ),
                  ],
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 12),
        Expanded(
          child: _entries.isEmpty
              ? _Surface(
                  child: Center(
                    child: Padding(
                      padding: const EdgeInsets.all(28),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          const Icon(
                            Icons.manage_search_rounded,
                            size: 48,
                            color: _CrimsonColors.textSecondary,
                          ),
                          const SizedBox(height: 12),
                          Text(
                            'No custom terminology yet',
                            style: Theme.of(context)
                                .textTheme
                                .titleMedium
                                ?.copyWith(fontWeight: FontWeight.w900),
                          ),
                          const SizedBox(height: 6),
                          const Text(
                            'Example: standard term “Rose Gold”; aliases “RG, R/G, RoseGold”.',
                            textAlign: TextAlign.center,
                          ),
                        ],
                      ),
                    ),
                  ),
                )
              : ListView.separated(
                  padding: const EdgeInsets.only(bottom: 16),
                  itemCount: _entries.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 8),
                  itemBuilder: (context, index) {
                    final entry = _entries[index];
                    return _Surface(
                      padding: const EdgeInsets.fromLTRB(16, 12, 8, 12),
                      child: Row(
                        children: [
                          Container(
                            width: 40,
                            height: 40,
                            decoration: BoxDecoration(
                              color: _CrimsonColors.crimsonLight,
                              borderRadius: BorderRadius.circular(12),
                            ),
                            child: const Icon(
                              Icons.translate_rounded,
                              color: _CrimsonColors.crimson,
                            ),
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  entry.canonical,
                                  style: const TextStyle(
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                                const SizedBox(height: 3),
                                Text(
                                  entry.aliases.join(' • '),
                                  maxLines: 2,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                    color: _CrimsonColors.textSecondary,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          IconButton(
                            tooltip: 'Edit terminology',
                            onPressed:
                                _saving ? null : () => _editEntry(index: index),
                            icon: const Icon(Icons.edit_outlined),
                          ),
                          IconButton(
                            tooltip: 'Delete terminology',
                            onPressed:
                                _saving ? null : () => _deleteEntry(index),
                            icon: const Icon(Icons.delete_outline_rounded),
                          ),
                        ],
                      ),
                    );
                  },
                ),
        ),
        if (_saving) const LinearProgressIndicator(minHeight: 2),
      ],
    );
  }

  Future<void> _editEntry({int? index}) async {
    final existing = index == null ? null : _entries[index];
    final canonicalController = TextEditingController(
      text: existing?.canonical ?? '',
    );
    final aliasesController = TextEditingController(
      text: existing?.aliases.join(', ') ?? '',
    );
    final result = await showDialog<SearchTerminologyDraft>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(existing == null ? 'Add search term' : 'Edit search term'),
        content: SizedBox(
          width: 520,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              TextField(
                controller: canonicalController,
                autofocus: true,
                decoration: _inputDecoration('Standard term, e.g. Rose Gold'),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: aliasesController,
                minLines: 2,
                maxLines: 4,
                decoration: _inputDecoration(
                  'Aliases separated by commas, e.g. RG, R/G, RoseGold',
                ),
              ),
              const SizedBox(height: 10),
              const Text(
                'Customers can type the standard term, any alias, or only the first few letters.',
                style: TextStyle(color: _CrimsonColors.textSecondary),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () {
              final canonical = cleanText(canonicalController.text);
              final aliases = aliasesController.text
                  .split(RegExp(r'[,;\n]'))
                  .map(cleanText)
                  .where((value) => value.isNotEmpty)
                  .toSet()
                  .toList(growable: false);
              if (canonical.isEmpty || aliases.isEmpty) {
                _showMessage(
                  dialogContext,
                  'Enter a standard term and at least one alias.',
                );
                return;
              }
              Navigator.pop(
                dialogContext,
                SearchTerminologyDraft(
                  canonical: canonical,
                  aliases: aliases,
                ),
              );
            },
            child: const Text('Save'),
          ),
        ],
      ),
    );
    canonicalController.dispose();
    aliasesController.dispose();
    if (result == null || !mounted) return;
    final next = List<SearchTerminologyDraft>.from(_entries);
    if (index == null) {
      next.add(result);
    } else {
      next[index] = result;
    }
    next.sort((left, right) =>
        left.canonical.toLowerCase().compareTo(right.canonical.toLowerCase()));
    await _save(next);
  }

  Future<void> _deleteEntry(int index) async {
    final entry = _entries[index];
    final confirmed = await showDialog<bool>(
          context: context,
          builder: (dialogContext) => AlertDialog(
            title: const Text('Delete search terminology?'),
            content: Text(
              '“${entry.canonical}” and its aliases will stop being treated as equivalent.',
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext, false),
                child: const Text('Cancel'),
              ),
              FilledButton(
                onPressed: () => Navigator.pop(dialogContext, true),
                child: const Text('Delete'),
              ),
            ],
          ),
        ) ??
        false;
    if (!confirmed || !mounted) return;
    final next = List<SearchTerminologyDraft>.from(_entries)..removeAt(index);
    await _save(next);
  }

  Future<void> _save(List<SearchTerminologyDraft> next) async {
    final previous = _entries;
    setState(() {
      _entries = next;
      _saving = true;
    });
    try {
      await widget.onSaveState(
        widget.state.copyWith(searchTerminology: next),
      );
      if (mounted) _showMessage(context, 'Search terminology saved.');
    } on Object catch (error) {
      if (!mounted) return;
      setState(() => _entries = previous);
      _showMessage(context, 'Could not save terminology: $error');
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }
}

