  @override
  State<_CategoryDiscountSettingsCard> createState() =>
      _CategoryDiscountSettingsCardState();
}

class _CategoryDiscountSettingsCardState
    extends State<_CategoryDiscountSettingsCard> {
  final _discountController = TextEditingController();
  String _category = '';
  bool _saving = false;

  List<String> get _categoryNames {
    final names = <String>[];
    for (final value in [
      ...widget.state.categories.map((category) => category.name),
      ...widget.state.products.map((product) => product.category),
    ]) {
      final name = cleanText(value);
      if (name.isEmpty ||
          names.any(
              (existing) => existing.toLowerCase() == name.toLowerCase())) {
        continue;
      }
      names.add(name);
    }
    names.sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));
    return names;
  }

  @override
  void initState() {
    super.initState();
    final names = _categoryNames;
    if (names.isNotEmpty) _selectCategory(names.first);
  }

  @override
  void didUpdateWidget(covariant _CategoryDiscountSettingsCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    final names = _categoryNames;
    if (names.isEmpty) return;
    if (!names.contains(_category)) {
      _selectCategory(names.first);
    } else if (oldWidget.state != widget.state) {
      _selectCategory(_category);
    }
  }

  void _selectCategory(String name) {
    _category = name;
    _discountController.text = formatCompactPrice(
      categoryDiscountFor(widget.state.categories, name),
    );
  }

  @override
  void dispose() {
    _discountController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final names = _categoryNames;
    return _Surface(
      padding: const EdgeInsets.all(18),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const _SectionHeader(
            title: 'Category discounts',
            subtitle:
                'Set the customer offer for every available price in a category.',
          ),
          const SizedBox(height: 14),
          if (names.isEmpty)
            const Text('Add a product category to set its discount.')
          else ...[
            Wrap(
              spacing: 12,
              runSpacing: 12,
              crossAxisAlignment: WrapCrossAlignment.center,
              children: [
                SizedBox(
                  width: 280,
                  child: DropdownButtonFormField<String>(
                    key: ValueKey(_category),
                    initialValue: _category,
                    isExpanded: true,
                    decoration: _inputDecoration('Category'),
                    items: [
                      for (final name in names)
                        DropdownMenuItem(value: name, child: Text(name)),
                    ],
                    onChanged: _saving
                        ? null
                        : (value) {
                            if (value == null) return;
                            setState(() => _selectCategory(value));
                          },
                  ),
                ),
                SizedBox(
                  width: 170,
                  child: TextField(
                    controller: _discountController,
                    keyboardType:
                        const TextInputType.numberWithOptions(decimal: true),
                    decoration: _inputDecoration('Discount %'),
                  ),
                ),
                FilledButton.icon(
                  onPressed: _saving ? null : _save,
                  icon: const Icon(Icons.save_outlined),
                  label: Text(_saving ? 'Saving...' : 'Save discount'),
                ),
              ],
            ),
            const SizedBox(height: 10),
            Text(
              '0% removes the offer. Base product prices stay unchanged.',
              style: Theme.of(context).textTheme.bodySmall?.copyWith(
                    color: _CrimsonColors.textSecondary,
                  ),
            ),
          ],
        ],
      ),
    );
  }

  Future<void> _save() async {
    final value = double.tryParse(_discountController.text.trim());
    if (value == null || !value.isFinite || value < 0 || value > 100) {
      _showMessage(context, 'Enter a discount from 0 to 100%.');
      return;
    }
    setState(() => _saving = true);
    try {
      final categories = [...widget.state.categories];
      final index = categories.indexWhere(
        (item) => item.name.trim().toLowerCase() == _category.toLowerCase(),
      );
      if (index < 0) {
        categories.add(CategoryDraft(name: _category, discountPercent: value));
      } else {
        categories[index] = categories[index].copyWith(discountPercent: value);
      }
      await widget.onSaveState(widget.state.copyWith(
        categories: categories,
        updatedAt: DateTime.now().toUtc().toIso8601String(),
      ));
      if (mounted) _showMessage(context, 'Category discount saved and synced.');
    } on Object catch (error) {
      if (mounted) _showMessage(context, 'Discount save failed: $error');
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }
}

class _BannerSettingsCard extends StatefulWidget {
  const _BannerSettingsCard({
    required this.state,
