class _BannerSettingsCardState extends State<_BannerSettingsCard> {
  final _fileDialogs = const WindowsFileDialogs();
  late final List<TextEditingController> _controllers;
  bool _saving = false;

  @override
  void initState() {
    super.initState();
    final paths = [...widget.state.bannerImagePaths];
    _controllers = List.generate(3, (index) {
      return TextEditingController(
          text: index < paths.length ? paths[index] : '');
    });
  }

  @override
  void didUpdateWidget(covariant _BannerSettingsCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.state.bannerImagePaths.join('|') !=
        widget.state.bannerImagePaths.join('|')) {
      for (var index = 0; index < _controllers.length; index++) {
        _controllers[index].text = index < widget.state.bannerImagePaths.length
            ? widget.state.bannerImagePaths[index]
            : '';
      }
    }
  }

  @override
  void dispose() {
    for (final controller in _controllers) {
      controller.dispose();
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return _Surface(
      padding: const EdgeInsets.all(18),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 44,
                height: 44,
                decoration: BoxDecoration(
                  color: _CrimsonColors.crimsonLight,
                  borderRadius: BorderRadius.circular(14),
                ),
                child: const Icon(
                  Icons.view_carousel_outlined,
                  color: _CrimsonColors.crimson,
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Customer banner images',
                      style: Theme.of(context).textTheme.titleMedium?.copyWith(
                            fontWeight: FontWeight.w900,
                          ),
                    ),
                    Text(
                      'Add up to 3 rotating home banners for customer view.',
                      style: Theme.of(context).textTheme.bodySmall?.copyWith(
                            color: _CrimsonColors.textSecondary,
                          ),
                    ),
                  ],
                ),
              ),
              FilledButton.icon(
                onPressed: _saving ? null : _save,
                icon: _saving
                    ? const SizedBox(
                        width: 16,
                        height: 16,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : const Icon(Icons.save_outlined),
                label: Text(_saving ? 'Saving...' : 'Save banners'),
              ),
            ],
          ),
          const SizedBox(height: 16),
          for (var index = 0; index < _controllers.length; index++) ...[
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(
                  child: TextField(
                    controller: _controllers[index],
                    decoration:
                        _inputDecoration('Banner ${index + 1} image path'),
                  ),
                ),
                const SizedBox(width: 10),
                OutlinedButton.icon(
                  onPressed: () => _browse(index),
                  icon: const Icon(Icons.folder_open_outlined),
                  label: const Text('Browse'),
                ),
                const SizedBox(width: 8),
                IconButton.outlined(
                  tooltip: 'Clear banner ${index + 1}',
                  onPressed: () => setState(() => _controllers[index].clear()),
                  icon: const Icon(Icons.close_rounded),
                ),
              ],
            ),
            if (index != _controllers.length - 1) const SizedBox(height: 10),
          ],
          const SizedBox(height: 12),
          Text(
            'These banners are only customer-facing. Admin tools and health checks remain separate.',
            style: Theme.of(context).textTheme.bodySmall?.copyWith(
                  color: _CrimsonColors.textSecondary,
                ),
          ),
        ],
      ),
    );
  }

  Future<void> _browse(int index) async {
    try {
      final paths = Platform.isAndroid
          ? await const MethodChannel('com.mycrimson.cataloguestudio/storage')
                  .invokeListMethod<String>('pickImageFiles') ??
              const <String>[]
          : await _fileDialogs.pickImageFiles();
      if (paths.isEmpty) return;
      setState(() => _controllers[index].text = paths.first);
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'Could not browse banner image: $error');
    }
  }

  Future<void> _save() async {
    setState(() => _saving = true);
    final paths = _controllers
        .map((controller) => cleanText(controller.text))
        .where((path) => path.isNotEmpty)
        .take(3)
        .toList();
    try {
      await widget.onSaveState(widget.state.copyWith(bannerImagePaths: paths));
      if (!mounted) return;
      _showMessage(context, 'Customer banners saved and synced.');
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'Banner sync failed: $error');
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }
}

