Future<void> _openMobileProductDetail(
  BuildContext context,
  ProductDraft product,
  ValueChanged<ProductDraft> onSelectProduct,
  ValueChanged<ProductDraft> onEditProduct,
  CrimsonProfile profile,
  ValueChanged<CustomerOrderItemDraft> onAddCustomerCartItem,
  VoidCallback onOpenCart, {
  CustomerOrderItemDraft? initialCartItem,
  double categoryDiscountPercent = 0,
  VoidCallback? onReturnToDraft,
  VoidCallback? onMakeLive,
}) async {
  onSelectProduct(product);
  if (product.isComingSoon) {
    await Navigator.of(context).push(MaterialPageRoute<void>(
      builder: (_) => Scaffold(
        appBar: AppBar(title: const Text('Coming Soon')),
        body: _ComingSoonProductPanel(
          product: product,
          onEdit: profile.canEditProducts ? () => onEditProduct(product) : null,
          onReturnToDraft: onReturnToDraft,
          onMakeLive: onMakeLive,
        ),
      ),
    ));
    return;
  }
  await Navigator.of(context).push(
    MaterialPageRoute<void>(
      builder: (_) => _MobileProductDetailPage(
        product: product,
        profile: profile,
        initialCartItem: initialCartItem,
        categoryDiscountPercent: categoryDiscountPercent,
        onEditProduct: () => onEditProduct(product),
        onAddCustomerCartItem: onAddCustomerCartItem,
        onOpenCart: onOpenCart,
      ),
    ),
  );
}

