  final CustomerOrderItemDraft? initialCartItem;
  final double categoryDiscountPercent;
  final VoidCallback onEditProduct;
  final ValueChanged<CustomerOrderItemDraft> onAddCustomerCartItem;
  final VoidCallback onOpenCart;

  @override
  State<_MobileProductDetailPage> createState() =>
      _MobileProductDetailPageState();
}

class _MobileProductDetailPageState extends State<_MobileProductDetailPage> {
  final _exportService = const PremiumExportService();
  late final VariationMatrix _matrix;
  late final List<_VariationAxis> _variationAxes;
  final Map<String, String> _selectedVariationValues = {};
  int _cartQuantity = 1;
  bool _matrixOpen = false;
  bool _sharing = false;
  late final PageController _imagePageController;
  int _imageIndex = 0;

  @override
  void initState() {
    super.initState();
    _liveStockSnapshot.addListener(_onStockChanged);
    _matrix = variationPriceMatrix(widget.product.variations);
    _variationAxes = _variationSelectorAxes(widget.product);
    for (final axis in _variationAxes) {
      if (axis.values.isNotEmpty) {
        _selectedVariationValues[axis.id] = axis.values.first;
      }
    }
    _applyInitialCartSelection();
    _imageIndex = _imageIndexForFinish(
      widget.product,
      _selectedVariationValues['finish'] ?? '',
    );
    _imagePageController = PageController(initialPage: _imageIndex);
  }

  @override
  void dispose() {
    _liveStockSnapshot.removeListener(_onStockChanged);
    _imagePageController.dispose();
    super.dispose();
  }

  void _onStockChanged() {
    if (mounted) setState(() {});
  }

  StockAvailability get _selectedStockStatus =>
      _liveStockSnapshot.value?.statusFor(
        widget.product,
        _selectedVariationDraft(
          widget.product,
          _variationAxes,
          _selectedVariationValues,
        ),
      ) ?? StockAvailability.notRecorded;

  void _applyInitialCartSelection() {
    final item = widget.initialCartItem;
    if (item == null) return;
    _cartQuantity = math.max(1, item.quantity.round());
    final matched = _variationForCartItem(widget.product, item);
    if (matched == null) return;
    for (final axis in _variationAxes) {
      final value = cleanText(axis.valueOf(matched));
      if (value.isNotEmpty && value != '-') {
        _selectedVariationValues[axis.id] = value;
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final showVariantControls =
        _shouldShowVariantControls(widget.product, _matrix);
    final showPriceMatrix = _shouldShowPriceMatrix(widget.product, _matrix);
    final imagePaths = _allImagePaths(widget.product);
    return Scaffold(
      backgroundColor: _CrimsonColors.background,
      bottomNavigationBar: (widget.profile.canEditProducts ||
              widget.profile.canShare ||
              widget.profile.role == CrimsonUserRole.customer)
          ? SafeArea(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(14, 8, 14, 12),
                child: Row(
                  children: [
                    if (widget.profile.canEditProducts) ...[
                      Expanded(
                        child: OutlinedButton.icon(
                          onPressed: _openEditor,
                          icon: const Icon(Icons.edit_outlined),
                          label: const Text('Edit'),
                        ),
                      ),
                      const SizedBox(width: 10),
                    ],
                    if (widget.profile.role == CrimsonUserRole.customer) ...[
                      _CartQuantityStepper(
                        value: _cartQuantity,
                        onDecrease: _decreaseCartQuantity,
                        onIncrease: _increaseCartQuantity,
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: FilledButton.icon(
                          onPressed: _selectedStockStatus == StockAvailability.outOfStock
                              ? null
                              : _addSelectedVariantToCart,
                          icon: const Icon(Icons.add_shopping_cart_rounded),
                          label: const Text('Add to Cart'),
                        ),
                      ),
                    ] else if (widget.profile.canShare)
                      Expanded(
                        child: FilledButton.icon(
                          onPressed: _sharing ? null : _openShareOptions,
                          icon: _sharing
                              ? const SizedBox(
                                  width: 18,
                                  height: 18,
                                  child: CircularProgressIndicator(
                                    strokeWidth: 2,
                                  ),
                                )
                              : const Icon(Icons.share_outlined),
                          label: Text(_sharing ? 'Preparing' : 'Share'),
                        ),
                      ),
                  ],
                ),
              ),
            )
          : null,
      body: SafeArea(
        child: CustomScrollView(
          slivers: [
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(14, 8, 14, 0),
                child: Row(
                  children: [
                    IconButton(
                      onPressed: () => Navigator.pop(context),
                      icon: const Icon(Icons.arrow_back_rounded),
                    ),
                    Expanded(
                      child: Text(
                        widget.product.name,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        textAlign: TextAlign.center,
                        style: Theme.of(context).textTheme.titleLarge?.copyWith(
                              fontWeight: FontWeight.w900,
                            ),
                      ),
                    ),
                    const SizedBox(width: 48),
                  ],
                ),
              ),
            ),
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.all(14),
                child: AspectRatio(
                  aspectRatio: 1.12,
                  child: _Surface(
                    padding: EdgeInsets.zero,
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(22),
                      child: Stack(
                        fit: StackFit.expand,
                        children: [
                          if (imagePaths.isEmpty)
                            const _DialogProductImage(path: null)
                          else
                            PageView.builder(
                              controller: _imagePageController,
                              itemCount: imagePaths.length,
                              onPageChanged: _handleMobileImageChanged,
                              itemBuilder: (context, index) => Padding(
                                padding: const EdgeInsets.all(18),
                                child: _DialogProductImage(
                                  path: imagePaths[index],
                                ),
                              ),
                            ),
                          if (imagePaths.isNotEmpty &&
                              _imageFinishForPath(
                                widget.product,
                                imagePaths[_imageIndex],
                              ).isNotEmpty)
                            Positioned(
                              left: 14,
                              top: 14,
                              child: _ImageFinishBadge(
                                label: _imageFinishForPath(
                                  widget.product,
                                  imagePaths[_imageIndex],
                                ),
                              ),
                            ),
                          if (imagePaths.length > 1)
                            Positioned(
                              left: 0,
                              right: 0,
                              bottom: 12,
                              child: _ImagePageDots(
                                count: imagePaths.length,
                                selectedIndex: _imageIndex,
                              ),
                            ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ),
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 14),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      widget.product.name,
                      style:
                          Theme.of(context).textTheme.headlineSmall?.copyWith(
                                fontWeight: FontWeight.w900,
                              ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      [
                        widget.product.category,
                        if (widget.profile.role != CrimsonUserRole.customer)
                          widget.product.subcategory,
                        widget.product.brand,
                      ]
                          .where((value) => cleanText(value).isNotEmpty)
                          .join(' / '),
                      style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                            color: _CrimsonColors.textSecondary,
                          ),
                    ),
                    const SizedBox(height: 8),
                    Text(
                      _selectedMobilePrice,
                      style:
                          Theme.of(context).textTheme.headlineSmall?.copyWith(
                                color: _CrimsonColors.crimson,
                                fontWeight: FontWeight.w900,
                              ),
                    ),
                    const SizedBox(height: 18),
                    if (showVariantControls) ...[
                      ..._variationSelectorWidgets(
                        product: widget.product,
                        axes: _variationAxes,
                        selectedValues: _selectedVariationValues,
                        onSelected: _selectMobileVariation,
                        stockStatusForVariation: (variation) =>
                            _liveStockSnapshot.value?.statusFor(
                              widget.product, variation) ??
                            StockAvailability.notRecorded,
                      ),
                    ],
                    _SelectedPriceCard(
                      label: _selectedMobileVariationLabel,
                      price: _selectedMobilePrice,
                      originalPrice: _selectedMobileOriginalPrice,
                      discountPercent: widget.categoryDiscountPercent,
                    ),
                    const SizedBox(height: 10),
                    _StockStatusBadge(_selectedStockStatus),
                    const SizedBox(height: 18),
                    if (showPriceMatrix &&
                        widget.profile.role != CrimsonUserRole.customer) ...[
                      ExpansionPanelList(
                        elevation: 0,
                        expandedHeaderPadding: EdgeInsets.zero,
                        expansionCallback: (_, isExpanded) {
                          setState(() => _matrixOpen = !isExpanded);
                        },
                        children: [
                          ExpansionPanel(
                            canTapOnHeader: true,
                            isExpanded: _matrixOpen,
                            headerBuilder: (context, isExpanded) =>
                                const ListTile(
                              title: Text(
                                'View Complete Price Matrix',
                                style: TextStyle(fontWeight: FontWeight.w900),
                              ),
                            ),
                            body: Padding(
                              padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
                              child: _PriceMatrixTable(matrix: _matrix),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 18),
                    ],
                    if (widget.profile.role != CrimsonUserRole.customer) ...[
                      _SpecGrid(
                        product: widget.product,
                        showSubcategory: true,
                      ),
                      const SizedBox(height: 24),
                    ] else
                      const SizedBox(height: 24),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  String get _selectedMobileOriginalPrice {
    if (!_shouldShowVariantControls(widget.product, _matrix)) {
      return _simpleProductPrice(widget.product);
    }
    final variation = _selectedVariationDraft(
      widget.product,
      _variationAxes,
      _selectedVariationValues,
    );
    if (variation == null) return _priceRange(widget.product);
    return _displayPrice(formatCompactPrice(variation.price));
  }

  String get _selectedMobilePrice => _discountedPriceDisplay(
        _selectedMobileOriginalPrice,
        _selectedMobileBasePrice,
        widget.categoryDiscountPercent,
      );

  double get _selectedMobileBasePrice {
    if (!_shouldShowVariantControls(widget.product, _matrix)) {
      return widget.product.variations.isEmpty
          ? _priceNumber(widget.product.sellingPrice)
          : _priceNumber(widget.product.variations.first.price);
    }
    final variation = _selectedVariationDraft(
      widget.product,
      _variationAxes,
      _selectedVariationValues,
    );
    return variation == null ? 0 : _priceNumber(variation.price);
  }

  String get _selectedMobileVariationLabel {
    if (_shouldShowVariantControls(widget.product, _matrix)) {
      return _variationLabelForDraft(_selectedVariationDraft(
        widget.product,
        _variationAxes,
        _selectedVariationValues,
      ));
    }
    return _simpleProductVariationLabel(widget.product);
  }

  void _handleMobileImageChanged(int index) {
    final paths = _allImagePaths(widget.product);
    if (index < 0 || index >= paths.length) return;
    final finish = _matchingFinishSelection(
      _variationAxes,
      _imageFinishForPath(widget.product, paths[index]),
    );
    setState(() {
      _imageIndex = index;
      if (finish.isNotEmpty) {
        _selectedVariationValues['finish'] = finish;
        _cartQuantity = 1;
      }
    });
  }

  void _selectMobileVariation(_VariationAxis axis, String value) {
    setState(() {
      _selectedVariationValues[axis.id] = value;
      _cartQuantity = 1;
    });
    if (axis.id != 'finish') return;
    final index = _imageIndexForFinish(widget.product, value);
    if (index == _imageIndex || !_imagePageController.hasClients) return;
    _imagePageController.animateToPage(
      index,
      duration: const Duration(milliseconds: 260),
      curve: Curves.easeOutCubic,
    );
  }

  void _openEditor() {
    widget.onEditProduct();
    Navigator.of(context).pop();
  }

  void _decreaseCartQuantity() {
    if (_cartQuantity <= 1) return;
    setState(() => _cartQuantity -= 1);
  }

  void _increaseCartQuantity() {
    setState(() => _cartQuantity += 1);
  }

  void _addSelectedVariantToCart() {
    if (_selectedStockStatus == StockAvailability.outOfStock) return;
    final item = _currentOrderItem();
    widget.onAddCustomerCartItem(item);
    _showCartAddedSnackBar(context, item, () {
      Navigator.of(context).pop();
      widget.onOpenCart();
    });
    setState(() => _cartQuantity = 1);
  }

  CustomerOrderItemDraft _currentOrderItem() {
    final variation = _selectedVariationDraft(
      widget.product,
      _variationAxes,
      _selectedVariationValues,
    );
    final imagePath = _imagePathForFinish(
      widget.product,
      variation == null ? widget.product.finishColor : variation.finish,
    );
    return CustomerOrderItemDraft(
      productId: widget.product.id,
      productName: widget.product.name,
      stockSku: _stockSkuFor(widget.product, variation),
      brand: widget.product.brand,
      size: variation == null
          ? widget.product.sizeSpec
          : (_structuredVariationSizeLabel(variation).isEmpty
              ? variation.size
              : _structuredVariationSizeLabel(variation)),
      finish: variation == null ? widget.product.finishColor : variation.finish,
      imagePath: imagePath,
      quantity: _cartQuantity.toDouble(),
      unitPrice: variation == null
          ? _priceNumber(widget.product.sellingPrice)
          : _priceNumber(variation.price),
      defaultDiscount:
          widget.categoryDiscountPercent > 0 && _selectedMobileBasePrice > 0
              ? '${formatCompactPrice(widget.categoryDiscountPercent)}%'
              : '',
    );
  }

  Future<void> _openShareOptions() async {
    if (!widget.profile.canShare) return;
    final action = await showModalBottomSheet<_MobileShareAction>(
      context: context,
      backgroundColor: Colors.white,
      showDragHandle: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (context) => SafeArea(
        child: Padding(
          padding: const EdgeInsets.fromLTRB(18, 4, 18, 18),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'Share product',
                style: Theme.of(context).textTheme.titleLarge?.copyWith(
                      fontWeight: FontWeight.w900,
                    ),
              ),
              const SizedBox(height: 12),
              ListTile(
                contentPadding: EdgeInsets.zero,
                leading: const Icon(Icons.image_outlined,
                    color: _CrimsonColors.crimson),
                title: const Text('Share product image'),
                subtitle: const Text('Premium spotlight image'),
                onTap: () => Navigator.pop(context, _MobileShareAction.image),
              ),
              ListTile(
                contentPadding: EdgeInsets.zero,
                leading: const Icon(Icons.picture_as_pdf_outlined,
                    color: _CrimsonColors.crimson),
                title: const Text('Share product PDF'),
                subtitle: const Text('PDF page ready for WhatsApp'),
                onTap: () => Navigator.pop(context, _MobileShareAction.pdf),
              ),
              ListTile(
                contentPadding: EdgeInsets.zero,
                leading: const Icon(Icons.sell_outlined,
                    color: _CrimsonColors.crimson),
                title: const Text('Share 60 x 40 sticker'),
                subtitle: const Text('Small price label for printing'),
                onTap: () => Navigator.pop(context, _MobileShareAction.sticker),
              ),
            ],
          ),
        ),
      ),
    );
    if (!mounted || action == null) return;
    switch (action) {
      case _MobileShareAction.image:
        await _shareProductImage();
      case _MobileShareAction.pdf:
        await _shareProductPdf();
      case _MobileShareAction.sticker:
        await _shareProductSticker();
    }
  }

  String get _selectedStickerFinish {
    final finish = cleanText(_selectedVariationValues['finish']);
    if (finish.isNotEmpty) return finish;
    return cleanText(widget.product.finishColor);
  }

  Future<void> _shareProductSticker() async {
    final imagePath = await _mobileExportPath(
      '${_safeName(widget.product.name)}_60x40_sticker.png',
    );
    await _runMobileShare(() async {
      await _exportService.exportPriceStickerImage(
        product: widget.product,
        path: imagePath,
        finish: _selectedStickerFinish,
      );
      await const MethodChannel('com.mycrimson.cataloguestudio/storage')
          .invokeMethod<void>('shareFiles', {
        'paths': [imagePath],
        'mimeType': 'image/png',
        'title': 'Share Crimson 60x40 price sticker',
      });
    });
  }

  Future<void> _shareProductImage() async {
    final imagePath = await _mobileExportPath(
      '${_safeName(widget.product.name)}_share.png',
    );
    await _runMobileShare(() async {
      final imagePaths = await _exportService.exportProductSpotlightImages(
        product: widget.product,
        path: imagePath,
      );
      await const MethodChannel('com.mycrimson.cataloguestudio/storage')
          .invokeMethod<void>('shareFiles', {
        'paths': imagePaths,
        'mimeType': 'image/png',
        'title': 'Share Crimson product image',
      });
    });
  }

  Future<void> _shareProductPdf() async {
    final imagePath = await _mobileExportPath(
      '${_safeName(widget.product.name)}_pdf_page.png',
    );
    final pdfPath = await _mobileExportPath(
      '${_safeName(widget.product.name)}_share.pdf',
    );
    await _runMobileShare(() async {
      final imagePaths = await _exportService.exportProductSpotlightImages(
        product: widget.product,
        path: imagePath,
      );
      await const MethodChannel('com.mycrimson.cataloguestudio/storage')
          .invokeMethod<void>('createPdfFromImages', {
        'imagePaths': imagePaths,
        'outputPath': pdfPath,
      });
      await const MethodChannel('com.mycrimson.cataloguestudio/storage')
          .invokeMethod<void>('shareFiles', {
        'paths': [pdfPath],
        'mimeType': 'application/pdf',
        'title': 'Share Crimson product PDF',
      });
    });
  }

  Future<void> _runMobileShare(Future<void> Function() action) async {
    if (_sharing) return;
    setState(() => _sharing = true);
    try {
      await action();
    } on Object catch (error) {
      if (mounted) _showMessage(context, 'Share failed: $error');
    } finally {
      if (mounted) setState(() => _sharing = false);
    }
  }

  Future<String> _mobileExportPath(String fileName) async {
    final safeFile = _safeName(fileName);
    try {
      final filesDir = await const MethodChannel(
        'com.mycrimson.cataloguestudio/storage',
      ).invokeMethod<String>('filesDir');
      final cleanDir = cleanText(filesDir);
      if (cleanDir.isNotEmpty) {
        final directory = Directory(
          '$cleanDir${Platform.pathSeparator}exports',
        );
        await directory.create(recursive: true);
        return '${directory.path}${Platform.pathSeparator}$safeFile';
      }
    } on Object {
      // Fall back below if Android storage is not ready yet.
    }
    final directory = await Directory.systemTemp.createTemp('crimson_export_');
    return '${directory.path}${Platform.pathSeparator}$safeFile';
  }

  String _safeName(String value) {
    final clean = cleanText(value)
        .replaceAll(RegExp(r'[^A-Za-z0-9._-]+'), '_')
        .replaceAll(RegExp(r'_+'), '_');
    return clean.isEmpty ? 'crimson_product' : clean;
  }
}

