class _MobileProductCard extends StatelessWidget {
  const _MobileProductCard({
    required this.product,
    required this.onTap,
    required this.selected,
    this.onSelectionToggle,
    this.onTogglePublished,
    this.stockQuantity,
  });

  final ProductDraft product;
  final VoidCallback onTap;
  final bool selected;
  final VoidCallback? onSelectionToggle;
  final VoidCallback? onTogglePublished;
  final double? stockQuantity;

  @override
  Widget build(BuildContext context) {
    return Material(
      color: Colors.white,
      borderRadius: BorderRadius.circular(18),
      child: InkWell(
        borderRadius: BorderRadius.circular(18),
        onTap: onTap,
        onLongPress: onSelectionToggle,
        child: Container(
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(18),
            border: Border.all(
              color: selected ? _CrimsonColors.crimson : _CrimsonColors.border,
              width: selected ? 2 : 1,
            ),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: ClipRRect(
                  borderRadius:
                      const BorderRadius.vertical(top: Radius.circular(18)),
                  child: Container(
                    color: Colors.white,
                    width: double.infinity,
                    child: _ProductImageFrame(
                      product: product,
                      fit: BoxFit.contain,
                      fallbackIconSize: 42,
                      cacheWidth: 1200,
