class _StockScreen extends StatefulWidget {
  const _StockScreen({
    required this.state,
    required this.onSaveState,
  });

  final CatalogueState state;
  final Future<void> Function(CatalogueState state) onSaveState;

  @override
  State<_StockScreen> createState() => _StockScreenState();
}

enum _StockWorkspaceSection {
  voucher,
  vouchers,
  analytics,
  currentStock
}

extension _StockWorkspaceSectionLabel on _StockWorkspaceSection {
  String get label => switch (this) {
        _StockWorkspaceSection.voucher => 'Stock voucher',
        _StockWorkspaceSection.vouchers => 'Voucher history',
        _StockWorkspaceSection.analytics => 'Stock analytics',
        _StockWorkspaceSection.currentStock => 'Current stock',
      };
}

class _StockScreenState extends State<_StockScreen> {
  StockVoucherType _type = StockVoucherType.inward;
  _StockWorkspaceSection _section = _StockWorkspaceSection.voucher;
  final _partyController = TextEditingController();
  final _referenceController = TextEditingController();
  final _searchController = TextEditingController();
  final _quantityController = TextEditingController();
  final _godownController = TextEditingController(text: 'Main');
  final _notesController = TextEditingController();
  final _bulkStockController = TextEditingController();
  final _searchFocusNode = FocusNode();
  final _quantityFocusNode = FocusNode();
  final List<_StockLineDraft> _lines = [];
  _StockItemOption? _selectedOption;
  String _query = '';
  int _highlightedOptionIndex = 0;
  bool _saving = false;

  @override
  void dispose() {
    _partyController.dispose();
    _referenceController.dispose();
    _searchController.dispose();
    _quantityController.dispose();
    _godownController.dispose();
    _notesController.dispose();
    _bulkStockController.dispose();
    _searchFocusNode.dispose();
    _quantityFocusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final options = _stockOptions(widget.state);
    final balances = _stockBalances(widget.state.stockVouchers);
    final filteredOptions = _filterOptions(options, _query).take(32).toList();
    final totalQty = _lines.fold<double>(0, (sum, line) => sum + line.quantity);

    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxWidth < 840;
        final selectedPanel = switch (_section) {
          _StockWorkspaceSection.voucher => _stockVoucherPanel(
              compact: compact,
              filteredOptions: filteredOptions,
              totalQty: totalQty,
            ),
          _StockWorkspaceSection.vouchers => _StockVoucherHistoryPanel(
              vouchers: widget.state.stockVouchers,
            ),
          _StockWorkspaceSection.analytics => _StockSummaryPanel(
              vouchers: widget.state.stockVouchers,
              balances: balances,
            ),
          _StockWorkspaceSection.currentStock => _CurrentStockPanel(
              options: _currentStockOptions(widget.state, options),
              balances: balances,
            ),
        };

        return SingleChildScrollView(
          padding: const EdgeInsets.only(bottom: 18),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Align(
                alignment: Alignment.centerRight,
                child: SizedBox(
                  width: compact ? double.infinity : 300,
                  child: _stockSectionDropdown(),
                ),
              ),
              const SizedBox(height: 8),
              selectedPanel,
            ],
          ),
        );
      },
    );
  }

  Widget _stockSectionDropdown() {
    return DropdownButtonFormField<_StockWorkspaceSection>(
      initialValue: _section,
      decoration: _inputDecoration('Stock workspace'),
      items: [
        for (final section in _StockWorkspaceSection.values)
          DropdownMenuItem(
            value: section,
            child: Text(section.label),
          ),
      ],
      onChanged: (section) {
        if (section == null) return;
        setState(() => _section = section);
      },
    );
  }

  Widget _stockVoucherPanel({
    required bool compact,
    required List<_StockItemOption> filteredOptions,
    required double totalQty,
  }) {
    return _Surface(
      padding: const EdgeInsets.all(18),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Expanded(
                child: _SectionHeader(
                  title: 'Stock Voucher',
                  subtitle:
                      'Keyboard-first inward, outward and adjustment entries.',
                ),
              ),
              _StatusPill(
                label: _nextVoucherNumber(),
                color: _CrimsonColors.crimson,
                background: _CrimsonColors.crimsonLight,
              ),
            ],
          ),
          const SizedBox(height: 14),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              for (final type in StockVoucherType.values)
                ChoiceChip(
                  label: Text(type.label),
                  selected: _type == type,
                  onSelected: (_) => setState(() => _type = type),
                ),
            ],
          ),
          const SizedBox(height: 14),
          Wrap(
            spacing: 10,
            runSpacing: 10,
            children: [
              SizedBox(
                width: compact ? double.infinity : 260,
                child: TextField(
                  controller: _partyController,
                  decoration: _inputDecoration('Party name'),
                ),
              ),
              SizedBox(
                width: compact ? double.infinity : 260,
                child: TextField(
                  controller: _referenceController,
                  decoration: _inputDecoration('Reference / bill no.'),
                ),
              ),
              SizedBox(
                width: compact ? double.infinity : 180,
                child: TextField(
                  controller: _godownController,
                  decoration: _inputDecoration('Default godown'),
                ),
              ),
            ],
          ),
          const SizedBox(height: 20),
          const _SectionHeader(
            title: 'Add item',
            subtitle:
                'Type, use Up/Down to choose, Enter to select, enter quantity, Enter to add.',
          ),
          const SizedBox(height: 10),
          Wrap(
            spacing: 10,
            runSpacing: 10,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              SizedBox(
                width: compact ? double.infinity : 520,
                child: Focus(
                  onKeyEvent: (node, event) =>
                      _handleSuggestionKey(event, filteredOptions),
                  child: TextField(
                    controller: _searchController,
                    focusNode: _searchFocusNode,
                    textInputAction: TextInputAction.next,
                    onChanged: (value) => setState(() {
                      _query = value;
                      _selectedOption = null;
                      _highlightedOptionIndex = 0;
                    }),
                    onSubmitted: (_) =>
                        _selectHighlightedOption(filteredOptions),
                    decoration: _inputDecoration('Search item / SKU').copyWith(
                      prefixIcon: const Icon(Icons.search_rounded),
                    ),
                  ),
                ),
              ),
              SizedBox(
                width: compact ? double.infinity : 160,
                child: TextField(
                  controller: _quantityController,
                  focusNode: _quantityFocusNode,
                  keyboardType:
                      const TextInputType.numberWithOptions(decimal: true),
                  textInputAction: TextInputAction.done,
                  onSubmitted: (_) => _addLine(),
                  decoration: _inputDecoration('Qty'),
                ),
              ),
              FilledButton.icon(
                onPressed: _addLine,
                icon: const Icon(Icons.add_rounded),
                label: const Text('Add item'),
              ),
            ],
          ),
          if (_query.trim().isNotEmpty && _selectedOption == null) ...[
            const SizedBox(height: 10),
            _SuggestionPanel(
              options: filteredOptions,
              highlightedIndex: _highlightedOptionIndex,
              onSelect: _selectOption,
            ),
          ],
          const SizedBox(height: 14),
          _BulkStockPastePanel(
            controller: _bulkStockController,
            onImport: () => _importBulkStockRows(),
          ),
          const SizedBox(height: 18),
          _VoucherLinesTable(
            lines: _lines,
            onRemove: (index) => setState(() => _lines.removeAt(index)),
          ),
          const SizedBox(height: 14),
          TextField(
            controller: _notesController,
            minLines: 2,
            maxLines: 4,
            decoration: _inputDecoration('Voucher notes'),
          ),
          const SizedBox(height: 14),
          _SoftPanel(
            child: Wrap(
              spacing: 12,
              runSpacing: 10,
              crossAxisAlignment: WrapCrossAlignment.center,
              children: [
                _StatusPill(
                  label: '${_formatQty(totalQty)} total pcs',
                  color: _CrimsonColors.crimson,
                  background: _CrimsonColors.crimsonLight,
                ),
                Text(
                  'Stock updates only after Save Voucher.',
                  style: Theme.of(context).textTheme.bodySmall?.copyWith(
                        color: _CrimsonColors.textSecondary,
                      ),
                ),
                const SpacerFix(),
                OutlinedButton.icon(
                  onPressed: _lines.isEmpty ? null : _clearDraft,
                  icon: const Icon(Icons.clear_rounded),
                  label: const Text('Clear'),
                ),
                FilledButton.icon(
                  onPressed: _saving || _lines.isEmpty ? null : _saveVoucher,
                  icon: _saving
                      ? const SizedBox(
                          width: 18,
                          height: 18,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : const Icon(Icons.save_outlined),
                  label: Text(_saving ? 'Saving...' : 'Save voucher'),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  KeyEventResult _handleSuggestionKey(
    KeyEvent event,
    List<_StockItemOption> options,
  ) {
    if (event is! KeyDownEvent || options.isEmpty) {
      return KeyEventResult.ignored;
    }
    if (event.logicalKey == LogicalKeyboardKey.arrowDown) {
      setState(() => _highlightedOptionIndex =
          (_highlightedOptionIndex + 1).clamp(0, options.length - 1));
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.arrowUp) {
      setState(() => _highlightedOptionIndex =
          (_highlightedOptionIndex - 1).clamp(0, options.length - 1));
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.enter) {
      _selectHighlightedOption(options);
      return KeyEventResult.handled;
    }
    return KeyEventResult.ignored;
  }

  void _selectHighlightedOption(List<_StockItemOption> options) {
    if (options.isEmpty) return;
    final index = _highlightedOptionIndex.clamp(0, options.length - 1);
    _selectOption(options[index]);
  }

  void _selectOption(_StockItemOption option) {
    setState(() {
      _selectedOption = option;
      _searchController.text = option.displayName;
      _query = option.displayName;
      _highlightedOptionIndex = 0;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _quantityFocusNode.requestFocus();
      _quantityController.selection = TextSelection(
        baseOffset: 0,
        extentOffset: _quantityController.text.length,
      );
    });
  }

  void _addLine() {
    final matchingOptions = _filterOptions(_stockOptions(widget.state), _query);
    final option = _selectedOption ??
        (matchingOptions.isEmpty ? null : matchingOptions.first);
    if (option == null) {
      _showMessage(context, 'Search and select an item first.');
      return;
    }
    final qty = double.tryParse(_quantityController.text.trim());
    if (qty == null || qty == 0) {
      _showMessage(context, 'Enter quantity.');
      return;
    }
    setState(() {
      _lines.add(_StockLineDraft(
        option: option,
        quantity: qty,
        godown: cleanText(_godownController.text).isEmpty
            ? 'Main'
            : cleanText(_godownController.text),
      ));
      _selectedOption = null;
      _query = '';
      _highlightedOptionIndex = 0;
      _searchController.clear();
      _quantityController.clear();
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _searchFocusNode.requestFocus();
    });
  }

  void _importBulkStockRows() {
    final imported = _parseBulkStockRows(
      _bulkStockController.text,
      _stockOptions(widget.state),
      cleanText(_godownController.text).isEmpty
          ? 'Main'
          : cleanText(_godownController.text),
    );
    if (imported.lines.isEmpty) {
      _showMessage(context, 'No matching stock rows found.');
      return;
    }
    setState(() {
      _lines.addAll(imported.lines);
      _bulkStockController.clear();
    });
    _showMessage(
      context,
      'Added ${imported.lines.length} stock rows${imported.skipped == 0 ? '' : ', skipped ${imported.skipped}'}.',
    );
  }

  Future<void> _saveVoucher() async {
    if (_lines.isEmpty) return;
    setState(() => _saving = true);
    try {
      final now = DateTime.now();
      final voucher = StockVoucherDraft(
        type: _type,
        voucherNumber: _nextVoucherNumber(),
        date: now.toIso8601String(),
        partyName: cleanText(_partyController.text),
        reference: cleanText(_referenceController.text),
        notes: cleanText(_notesController.text),
        createdAt: now.toUtc().toIso8601String(),
        items: _lines
            .map((line) => StockVoucherItemDraft(
                  stockItemId: line.option.stockItemId,
                  productId: line.option.productId,
                  productName: line.option.productName,
                  stockSku: line.option.stockSku,
                  brand: line.option.brand,
                  size: line.option.size,
                  finish: line.option.finish,
                  godown: line.godown,
                  quantity: line.quantity,
                ))
            .toList(),
      );
      await widget.onSaveState(widget.state.copyWith(
        stockVouchers: [...widget.state.stockVouchers, voucher],
        updatedAt: now.toIso8601String(),
      ));
      if (!mounted) return;
      _showMessage(context, 'Stock voucher saved.');
      setState(() {
        _lines.clear();
        _partyController.clear();
        _referenceController.clear();
        _notesController.clear();
      });
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _searchFocusNode.requestFocus();
      });
    } on Object catch (error) {
      if (mounted) _showMessage(context, 'Stock voucher failed: $error');
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  void _clearDraft() => setState(() {
        _lines.clear();
        _selectedOption = null;
        _query = '';
        _highlightedOptionIndex = 0;
        _searchController.clear();
        _quantityController.clear();
      });

  String _nextVoucherNumber() {
    final number = widget.state.stockVouchers.length + 1;
    return 'STK-${DateTime.now().year}-${number.toString().padLeft(5, '0')}';
  }
}

class SpacerFix extends StatelessWidget {
  const SpacerFix({super.key});

  @override
  Widget build(BuildContext context) => const SizedBox.shrink();
}

class _StockItemOption {
  const _StockItemOption({
    this.stockItemId = '',
    required this.productId,
    required this.productName,
    required this.stockSku,
    required this.brand,
    required this.size,
    required this.finish,
    required this.category,
    this.subcategory = '',
    this.material = '',
    this.unitPrice = 0,
  });

  final String stockItemId;
  final String productId;
  final String productName;
  final String stockSku;
  final String brand;
  final String size;
  final String finish;
  final String category;
  final String subcategory;
  final String material;
  final double unitPrice;

  String get identity => cleanText(stockItemId).isNotEmpty
      ? stockItemId
      : [productId, stockSku, size, finish].join('|');

  String get displayName => [productName, size, finish, brand]
      .where((value) => cleanText(value).isNotEmpty)
      .join(' ');

  String get searchLabel => [
        displayName,
        stockSku,
        brand,
        category,
        subcategory,
        material,
      ].where((value) => cleanText(value).isNotEmpty).join(' ');
}

class _StockLineDraft {
  const _StockLineDraft({
    required this.option,
    required this.quantity,
    required this.godown,
  });

  final _StockItemOption option;
  final double quantity;
  final String godown;
}

class _SuggestionPanel extends StatefulWidget {
  const _SuggestionPanel({
    required this.options,
    required this.highlightedIndex,
    required this.onSelect,
  });

  final List<_StockItemOption> options;
  final int highlightedIndex;
  final ValueChanged<_StockItemOption> onSelect;

  @override
  State<_SuggestionPanel> createState() => _SuggestionPanelState();
}

class _SuggestionPanelState extends State<_SuggestionPanel> {
  static const double _rowExtent = 74;
  final _scrollController = ScrollController();

  @override
  void didUpdateWidget(covariant _SuggestionPanel oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.highlightedIndex != widget.highlightedIndex ||
        oldWidget.options.length != widget.options.length) {
      WidgetsBinding.instance
          .addPostFrameCallback((_) => _keepHighlightVisible());
    }
  }

  @override
  void dispose() {
    _scrollController.dispose();
    super.dispose();
  }

  void _keepHighlightVisible() {
    if (!_scrollController.hasClients || widget.options.isEmpty) return;
    final index = widget.highlightedIndex.clamp(0, widget.options.length - 1);
    final target = index * _rowExtent;
    _scrollController.animateTo(
      target.clamp(
        _scrollController.position.minScrollExtent,
        _scrollController.position.maxScrollExtent,
      ),
      duration: const Duration(milliseconds: 120),
      curve: Curves.easeOut,
    );
  }

  @override
  Widget build(BuildContext context) {
    return _SoftPanel(
      child: widget.options.isEmpty
          ? const Text('No matching stock item found.')
          : ConstrainedBox(
              constraints: const BoxConstraints(maxHeight: 292),
              child: ListView.builder(
                controller: _scrollController,
                shrinkWrap: true,
                padding: const EdgeInsets.only(bottom: _rowExtent * 3),
                itemExtent: _rowExtent,
                itemCount: widget.options.length,
                itemBuilder: (context, index) {
                  final option = widget.options[index];
                  final selected = index == widget.highlightedIndex;
                  return AnimatedContainer(
                    duration: const Duration(milliseconds: 120),
                    decoration: BoxDecoration(
                      color: selected
                          ? _CrimsonColors.crimsonLight
                          : Colors.transparent,
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: ListTile(
                      dense: true,
                      contentPadding: const EdgeInsets.symmetric(
                        horizontal: 8,
                        vertical: 2,
                      ),
                      leading: const Icon(Icons.inventory_2_outlined),
                      title: Text(
                        option.displayName,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(fontWeight: FontWeight.w800),
                      ),
                      subtitle: Text(
                        _stockOptionMeta(option),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                      trailing: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        crossAxisAlignment: CrossAxisAlignment.end,
                        children: [
                          Text(
                            option.stockSku,
                            style: const TextStyle(fontWeight: FontWeight.w800),
                          ),
                          Text(
                            'Rate ${formatCompactPrice(option.unitPrice.toString())}',
                            style: const TextStyle(
                              color: _CrimsonColors.crimson,
                              fontWeight: FontWeight.w800,
                              fontSize: 12,
                            ),
                          ),
                        ],
                      ),
                      onTap: () => widget.onSelect(option),
                    ),
                  );
                },
              ),
            ),
    );
  }
}

class _VoucherLinesTable extends StatelessWidget {
  const _VoucherLinesTable({required this.lines, required this.onRemove});

  final List<_StockLineDraft> lines;
  final ValueChanged<int> onRemove;

  @override
  Widget build(BuildContext context) {
    if (lines.isEmpty) {
      return _SoftPanel(
        child: Center(
          child: Padding(
            padding: const EdgeInsets.all(20),
            child: Text(
              'No items added yet. Search an item, enter quantity and press Add item.',
              textAlign: TextAlign.center,
              style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                    color: _CrimsonColors.textSecondary,
                  ),
            ),
          ),
        ),
      );
    }
    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: DataTable(
        headingRowColor: WidgetStateProperty.all(_CrimsonColors.crimsonLight),
        columns: const [
          DataColumn(label: Text('Product')),
          DataColumn(label: Text('Brand SKU')),
          DataColumn(label: Text('Brand')),
          DataColumn(label: Text('Size')),
          DataColumn(label: Text('Finish')),
          DataColumn(label: Text('Qty')),
          DataColumn(label: Text('Godown')),
          DataColumn(label: Text('')),
        ],
        rows: [
          for (var index = 0; index < lines.length; index++)
            DataRow(cells: [
              DataCell(Text(lines[index].option.productName)),
              DataCell(Text(lines[index].option.stockSku)),
              DataCell(Text(lines[index].option.brand)),
              DataCell(Text(lines[index].option.size)),
              DataCell(Text(lines[index].option.finish)),
              DataCell(Text(_formatQty(lines[index].quantity))),
              DataCell(Text(lines[index].godown)),
              DataCell(IconButton(
                tooltip: 'Remove item',
                icon: const Icon(Icons.delete_outline_rounded),
                onPressed: () => onRemove(index),
              )),
            ]),
        ],
      ),
    );
  }
}

class _StockSummaryPanel extends StatelessWidget {
  const _StockSummaryPanel({required this.vouchers, required this.balances});

  final List<StockVoucherDraft> vouchers;
  final Map<String, double> balances;

  @override
  Widget build(BuildContext context) {
    final inward = _voucherTypeTotal(vouchers, StockVoucherType.inward);
    final outward = _voucherTypeTotal(vouchers, StockVoucherType.outward);
    final lowStock = balances.values.where((qty) => qty > 0 && qty <= 5).length;
    return _Surface(
      padding: const EdgeInsets.all(18),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const _SectionHeader(
            title: 'Stock Analytics',
            subtitle: 'Movement totals and low stock signals.',
          ),
          const SizedBox(height: 14),
          Wrap(
            spacing: 10,
            runSpacing: 10,
            children: [
              _MetricTile(label: 'Inward', value: _formatQty(inward)),
              _MetricTile(label: 'Outward', value: _formatQty(outward)),
              _MetricTile(
                  label: 'Stock balances', value: balances.length.toString()),
              _MetricTile(label: 'Low stock', value: lowStock.toString()),
            ],
          ),
          const SizedBox(height: 14),
          Text(
            'Recent vouchers',
            style: Theme.of(context).textTheme.titleSmall?.copyWith(
                  fontWeight: FontWeight.w900,
                ),
          ),
          const SizedBox(height: 8),
          if (vouchers.isEmpty)
            Text(
              'No stock vouchers saved yet.',
              style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                    color: _CrimsonColors.textSecondary,
                  ),
            )
          else
            for (final voucher in vouchers.reversed.take(5))
              ListTile(
                dense: true,
                contentPadding: EdgeInsets.zero,
                title: Text(voucher.voucherNumber),
                subtitle: Text(
                    '${voucher.type.label} - ${voucher.partyName.isEmpty ? 'No party' : voucher.partyName}'),
                trailing: Text(_formatQty(voucher.items
                    .fold<double>(0, (sum, item) => sum + item.quantity))),
              ),
        ],
      ),
    );
  }
}

class _CurrentStockPanel extends StatefulWidget {
  const _CurrentStockPanel({required this.options, required this.balances});

  final List<_StockItemOption> options;
  final Map<String, double> balances;

  @override
  State<_CurrentStockPanel> createState() => _CurrentStockPanelState();
}

class _CurrentStockPanelState extends State<_CurrentStockPanel> {
  final _searchController = TextEditingController();

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final query = cleanText(_searchController.text).toLowerCase();
    final terms = query.split(RegExp(r'\s+')).where((term) => term.isNotEmpty);
    final rows = [
      for (final option in widget.options)
        if (terms.every((term) => [
              option.productName,
              option.stockSku,
              option.brand,
              option.size,
              option.finish,
              option.category,
              option.subcategory,
            ].join(' ').toLowerCase().contains(term)))
          (option: option, qty: widget.balances[option.identity] ?? 0),
    ]..sort((a, b) => a.option.productName.compareTo(b.option.productName));
    final visibleRows = rows.take(query.isEmpty ? 12 : 100).toList();
    return _Surface(
      padding: const EdgeInsets.all(18),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const _SectionHeader(
            title: 'Current Stock',
            subtitle: 'Calculated from saved stock vouchers.',
          ),
          const SizedBox(height: 12),
          Align(
            alignment: Alignment.centerLeft,
            child: OutlinedButton.icon(
              onPressed: () => Navigator.of(context).push(MaterialPageRoute<void>(
                builder: (_) => TallyStockReviewScreen(variations: [
                  for (final option in widget.options)
                    TallyMatchCandidate(targetKey: option.identity, label: option.searchLabel,
                      productId: option.productId, productName: option.productName,
                      stockItemId: option.stockItemId, stockSku: option.stockSku,
                      brand: option.brand, size: option.size, finish: option.finish),
                ], repository: _CustomerServiceScope.maybeOf(context)?.catalogue,
                  refresh: _CustomerServiceScope.maybeOf(context)?.refresh),
              )),
              icon: const Icon(Icons.upload_file),
              label: const Text('Import Tally Excel'),
            ),
          ),
          const SizedBox(height: 12),
          TextField(
            controller: _searchController,
            onChanged: (_) => setState(() {}),
            textInputAction: TextInputAction.search,
            decoration: _inputDecoration('Search product, SKU, size or finish')
                .copyWith(
              prefixIcon: const Icon(Icons.search_rounded),
              suffixIcon: query.isEmpty
                  ? null
                  : IconButton(
                      tooltip: 'Clear stock search',
                      onPressed: () {
                        _searchController.clear();
                        setState(() {});
                      },
                      icon: const Icon(Icons.close_rounded),
                    ),
            ),
          ),
          const SizedBox(height: 8),
          Text(
            rows.length > visibleRows.length
                ? 'Showing ${visibleRows.length} of ${rows.length}; search to narrow the list.'
                : '${rows.length} ${rows.length == 1 ? 'item' : 'items'}',
            style: Theme.of(context).textTheme.bodySmall?.copyWith(
                  color: _CrimsonColors.textSecondary,
                ),
          ),
          const SizedBox(height: 8),
          if (rows.isEmpty)
            Text(
              query.isEmpty
                  ? 'No catalogue items available for stock yet.'
                  : 'No stock items match this search.',
              style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                    color: _CrimsonColors.textSecondary,
                  ),
            )
          else
            ...visibleRows.map((row) => ListTile(
                  dense: true,
                  contentPadding: EdgeInsets.zero,
                  title: Text(row.option.productName),
                  subtitle: Text([
                    row.option.stockSku,
                    _stockOptionMeta(row.option),
                  ].where((part) => cleanText(part).isNotEmpty).join(' | ')),
                  trailing: Text(
                    _formatQty(row.qty),
                    style: const TextStyle(
                      color: _CrimsonColors.crimson,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                )),
        ],
      ),
    );
  }
}

