  }
}

List<_StockItemOption> _stockOptions(CatalogueState state) {
  final productsById = {
    for (final product in state.products) product.id: product
  };
  final linkedProductIds = <String>{};
  final options = <_StockItemOption>[];

  for (final item in state.stockItems.where((item) => item.isActive)) {
    final product = productsById[item.displayProductId];
    if (product?.isArchived == true) continue;
    linkedProductIds.add(item.displayProductId);
    options.add(_StockItemOption(
      stockItemId: item.id,
      productId: item.displayProductId,
      productName: cleanText(item.displayProductName).isEmpty
          ? (product?.name ?? 'Stock item')
          : item.displayProductName,
      stockSku: cleanText(item.stockSku).isEmpty ? item.id : item.stockSku,
      brand: item.brand,
      size: item.size,
      finish: item.finish,
      category: cleanText(item.category).isEmpty
          ? (product?.category ?? '')
          : item.category,
      subcategory: cleanText(item.subcategory).isEmpty
          ? (product?.subcategory ?? '')
          : item.subcategory,
      material: item.material,
      unitPrice: _priceForStockOption(product, item.size, item.finish),
    ));
  }

  for (final product
      in state.products.where((product) => !product.isArchived)) {
    if (linkedProductIds.contains(product.id)) continue;
    if (product.variations.isEmpty) {
      options.add(_StockItemOption(
        productId: product.id,
        productName: product.name,
        stockSku: _stockSkuFor(product, null),
        brand: product.brand,
        size: product.sizeSpec,
        finish: product.finishColor,
        category: product.category,
        subcategory: product.subcategory,
        unitPrice: _priceNumber(product.sellingPrice),
      ));
      continue;
    }
    for (final variation in product.variations) {
      options.add(_StockItemOption(
        productId: product.id,
        productName: product.name,
        stockSku: _stockSkuFor(product, variation),
        brand: product.brand,
        size: variation.size.isEmpty ? product.sizeSpec : variation.size,
        finish:
            variation.finish.isEmpty ? product.finishColor : variation.finish,
        category: product.category,
        subcategory: product.subcategory,
        unitPrice: _priceNumber(variation.price),
      ));
    }
  }
  options.sort((left, right) => left.searchLabel
      .toLowerCase()
      .compareTo(right.searchLabel.toLowerCase()));
  return options;
}

List<_StockItemOption> _currentStockOptions(
  CatalogueState state,
  List<_StockItemOption> selectableOptions,
) {
  final options = [...selectableOptions];
  final identities = options.map((option) => option.identity).toSet();
  final movedIdentities = <String>{};
  final productsWithLegacyMovements = <String>{};
  final productsById = {
    for (final product in state.products) product.id: product,
  };
  for (final voucher in state.stockVouchers) {
    for (final line in voucher.items) {
      final product = productsById[line.productId];
      final option = _StockItemOption(
        stockItemId: line.stockItemId,
        productId: line.productId,
        productName: cleanText(line.productName).isNotEmpty
            ? line.productName
            : (product?.name ?? 'Stock item'),
        stockSku: line.stockSku,
        brand: line.brand,
        size: line.size,
        finish: line.finish,
        category: product?.category ?? '',
        subcategory: product?.subcategory ?? '',
      );
      movedIdentities.add(option.identity);
      if (cleanText(line.stockItemId).isEmpty) {
        productsWithLegacyMovements.add(line.productId);
      }
      if (identities.add(option.identity)) options.add(option);
    }
  }
  return options
      .where((option) =>
          cleanText(option.stockItemId).isEmpty ||
          movedIdentities.contains(option.identity) ||
          !productsWithLegacyMovements.contains(option.productId))
      .toList(growable: false);
}

