class _BulkStockImportResult {
  const _BulkStockImportResult({
    required this.lines,
    required this.skipped,
  });

  final List<_StockLineDraft> lines;
  final int skipped;
}

_BulkStockImportResult _parseBulkStockRows(
  String text,
  List<_StockItemOption> options,
  String defaultGodown,
) {
  final rows = text
      .split(RegExp(r'\r?\n'))
      .map((line) => line.split('\t').map(cleanText).toList())
      .where((row) => row.any((cell) => cell.isNotEmpty))
      .toList();
  if (rows.isEmpty) {
    return const _BulkStockImportResult(lines: [], skipped: 0);
  }

  var headers = <String>[];
  var start = 0;
  final first = rows.first.map((cell) => cell.toLowerCase()).toList();
  if (first.any((cell) => ['product', 'item', 'item name', 'sku', 'qty']
      .any((header) => cell.contains(header)))) {
    headers = first;
    start = 1;
  }

  int indexOf(List<String> names, int fallback) {
    for (final name in names) {
      final index = headers.indexWhere((header) =>
          header == name ||
          header.replaceAll(' ', '') == name.replaceAll(' ', ''));
      if (index >= 0) return index;
    }
    return fallback;
  }

  final productIndex = headers.isEmpty
      ? 0
      : indexOf(['product', 'item', 'item name', 'product name'], 0);
  final skuIndex =
      headers.isEmpty ? 1 : indexOf(['sku', 'code', 'product code'], 1);
  final brandIndex = headers.isEmpty ? 2 : indexOf(['brand'], 2);
  final sizeIndex = headers.isEmpty ? 3 : indexOf(['size'], 3);
  final finishIndex =
      headers.isEmpty ? 4 : indexOf(['finish', 'colour', 'color'], 4);
  final qtyIndex = headers.isEmpty ? 5 : indexOf(['qty', 'quantity', 'pcs'], 5);
  final godownIndex = headers.isEmpty ? 6 : indexOf(['godown', 'warehouse'], 6);

  String cell(List<String> row, int index) =>
      index >= 0 && index < row.length ? row[index] : '';
  final lines = <_StockLineDraft>[];
  var skipped = 0;
  for (var i = start; i < rows.length; i++) {
    final row = rows[i];
    final qty = double.tryParse(cell(row, qtyIndex).replaceAll(',', ''));
    if (qty == null || qty == 0) {
      skipped++;
      continue;
    }
    final searchParts = [
      cell(row, skuIndex),
      cell(row, productIndex),
      cell(row, brandIndex),
      cell(row, sizeIndex),
      cell(row, finishIndex),
    ].where((value) => value.isNotEmpty).join(' ');
    final matches = _filterOptions(options, searchParts);
    if (matches.isEmpty) {
      skipped++;
      continue;
    }
    lines.add(_StockLineDraft(
      option: matches.first,
      quantity: qty,
      godown: cell(row, godownIndex).isEmpty
          ? defaultGodown
          : cell(row, godownIndex),
    ));
  }
  return _BulkStockImportResult(lines: lines, skipped: skipped);
}

