    required this.onPlaceOrder,
  });

  final List<CustomerOrderItemDraft> items;
  final List<ProductDraft> products;
  final List<CategoryDraft> categories;
  final CrimsonProfile profile;
  final VoidCallback onOpenProducts;
  final ValueChanged<ProductDraft> onSelectProduct;
  final ValueChanged<ProductDraft> onEditProduct;
  final ValueChanged<CustomerOrderItemDraft> onAddCustomerCartItem;
  final void Function(int index, double quantity) onUpdateQuantity;
