class _CustomerCartScreenState extends State<_CustomerCartScreen> {
  bool _placing = false;

  @override
  Widget build(BuildContext context) {
    final editingOrder = widget.editingOrder;
    final pricedItems = editingOrder == null
        ? _cartItemsWithCurrentDiscounts(
            widget.items,
            widget.products,
            widget.categories,
          )
        : widget.items;
    final baseSubtotal = pricedItems.fold<double>(
      0,
      (sum, item) => sum + item.baseLineTotal,
    );
    final discountedSubtotal = pricedItems.fold<double>(
      0,
      (sum, item) => sum + item.lineTotal,
    );
    final lineSavings = baseSubtotal - discountedSubtotal;
    final extraPercent = editingOrder?.additionalDiscountPercent ?? 0;
    final extraSavings = discountedSubtotal * extraPercent / 100;
    final total = discountedSubtotal - extraSavings;
    return CustomScrollView(
      slivers: [
        SliverToBoxAdapter(
          child: _MobileTopBar(
            title: editingOrder == null ? 'Cart' : 'Edit Order',
            subtitle: editingOrder == null
                ? '${widget.items.length} selected items'
                : '${editingOrder.orderNumber} - pending approval',
            trailing: IconButton(
              tooltip: 'Browse products',
              onPressed: widget.onOpenProducts,
              icon: const Icon(Icons.search_rounded),
            ),
          ),
        ),
        const SliverToBoxAdapter(child: SizedBox(height: 12)),
        if (editingOrder != null)
          SliverToBoxAdapter(
            child: _SoftPanel(
              child: Row(
                children: [
                  const Icon(
                    Icons.edit_note_rounded,
                    color: _CrimsonColors.crimson,
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(
                      'You are editing ${editingOrder.orderNumber}. Changes will update the same pending order.',
                      style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                            fontWeight: FontWeight.w700,
                          ),
                    ),
                  ),
                  TextButton(
                    onPressed: widget.onClear,
                    child: const Text('Stop editing'),
                  ),
                ],
              ),
            ),
          ),
        if (editingOrder != null)
          const SliverToBoxAdapter(child: SizedBox(height: 12)),
        if (widget.items.isEmpty)
          SliverToBoxAdapter(
            child: _Surface(
              padding: const EdgeInsets.all(18),
              child: Column(
                children: [
                  const Icon(
                    Icons.shopping_bag_outlined,
                    color: _CrimsonColors.crimson,
                    size: 48,
                  ),
                  const SizedBox(height: 10),
                  Text(
                    'Your cart is empty',
                    style: Theme.of(context).textTheme.titleLarge?.copyWith(
                          fontWeight: FontWeight.w900,
                        ),
                  ),
                  const SizedBox(height: 6),
                  Text(
                    'Open a product, choose the size or finish, then tap Add to Cart.',
                    textAlign: TextAlign.center,
                    style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                          color: _CrimsonColors.textSecondary,
                        ),
                  ),
                  const SizedBox(height: 16),
                  FilledButton.icon(
                    onPressed: widget.onOpenProducts,
                    icon: const Icon(Icons.inventory_2_outlined),
                    label: const Text('Browse Products'),
                  ),
                ],
              ),
            ),
          )
        else ...[
          SliverList.separated(
            itemCount: pricedItems.length,
            separatorBuilder: (_, __) => const SizedBox(height: 10),
            itemBuilder: (context, index) => _CustomerCartItemCard(
              item: pricedItems[index],
              onTap: () => _openCartItemDetail(index),
              onIncrease: () => widget.onUpdateQuantity(
                index,
                widget.items[index].quantity + 1,
              ),
              onDecrease: () => widget.onUpdateQuantity(
                index,
                widget.items[index].quantity - 1,
              ),
              onRemove: () => widget.onRemoveItem(index),
            ),
          ),
          const SliverToBoxAdapter(child: SizedBox(height: 12)),
          SliverToBoxAdapter(
            child: _Surface(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const _SectionHeader(
                    title: 'Order summary',
                    subtitle:
                        'Review your current cart before placing the order.',
                  ),
                  const SizedBox(height: 14),
                  _DiscountSummaryRow(
                    label: 'Base subtotal',
                    amount: baseSubtotal,
                  ),
                  if (lineSavings > 0)
                    _DiscountSummaryRow(
                      label: 'Category / line discounts',
                      amount: -lineSavings,
                    ),
                  _DiscountSummaryRow(
                    label: extraPercent > 0
                        ? 'Additional discount (${formatCompactPrice(extraPercent)}%)'
                        : 'Additional discount',
                    amount: -extraSavings,
                  ),
                  const Divider(height: 20),
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          'Total ${_displayPrice(formatCompactPrice(total.toString()))}',
                          style:
                              Theme.of(context).textTheme.titleLarge?.copyWith(
                                    color: _CrimsonColors.crimson,
                                    fontWeight: FontWeight.w900,
                                  ),
                        ),
                      ),
                      TextButton(
                        onPressed: widget.onClear,
                        child: const Text('Clear'),
                      ),
                    ],
                  ),
                  const SizedBox(height: 12),
                  SizedBox(
                    width: double.infinity,
                    child: FilledButton.icon(
                      onPressed: _placing ? null : _placeOrder,
                      icon: _placing
                          ? const SizedBox(
                              width: 18,
                              height: 18,
                              child: CircularProgressIndicator(strokeWidth: 2),
                            )
                          : const Icon(Icons.check_circle_outline),
                      label:
                          Text(_placing ? 'Placing order...' : 'Place Order'),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
        const SliverToBoxAdapter(child: SizedBox(height: 18)),
      ],
    );
  }

  void _openCartItemDetail(int index) {
    if (index < 0 || index >= widget.items.length) return;
    final item = widget.items[index];
    ProductDraft? product;
    for (final candidate in widget.products) {
      if (candidate.id == item.productId) {
        product = candidate;
        break;
      }
    }
    if (product == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Product details are not available.')),
      );
      return;
    }
    _openMobileProductDetail(
      context,
      product,
      widget.onSelectProduct,
      widget.onEditProduct,
      widget.profile,
      widget.onAddCustomerCartItem,
      () {},
      initialCartItem: item,
      categoryDiscountPercent:
          categoryDiscountFor(widget.categories, product.category),
    );
  }

  Future<void> _placeOrder() async {
    if (widget.items.isEmpty) return;
    setState(() => _placing = true);
    try {
      await widget.onPlaceOrder(
        customerName: widget.profile.displayName,
        customerPhone: '',
        notes: '',
      );
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
              widget.editingOrder == null ? 'Order placed.' : 'Order updated.'),
        ),
      );
    } on Object catch (error) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Order failed: $error')),
        );
      }
    } finally {
      if (mounted) setState(() => _placing = false);
    }
  }
}

