}

class _OrderDiscountBreakdown extends StatelessWidget {
  const _OrderDiscountBreakdown({required this.order});

  final CustomerOrderDraft order;

  @override
  Widget build(BuildContext context) {
    final approved = _orderUsesApprovedPricing(order.status);
    final base = approved
        ? order.items.fold<double>(
            0,
            (sum, item) =>
                sum + item.effectiveApprovedQuantity * item.unitPrice,
          )
        : order.baseSubtotal;
    final lineSubtotal =
        approved ? order.approvedSubtotal : order.discountedSubtotal;
    final additional = lineSubtotal * order.additionalDiscountPercent / 100;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _DiscountSummaryRow(label: 'Base subtotal', amount: base),
        _DiscountSummaryRow(
          label: 'Category / line discounts',
          amount: -(base - lineSubtotal),
        ),
        _DiscountSummaryRow(
          label: order.additionalDiscountPercent > 0
              ? 'Additional discount (${formatCompactPrice(order.additionalDiscountPercent)}%)'
              : 'Additional discount',
          amount: -additional,
        ),
        const Divider(height: 20),
        _DiscountSummaryRow(
          label: 'Total',
          amount: lineSubtotal - additional,
        ),
      ],
    );
  }
}

