enum _OrderWorkspaceMode {
  newOrder,
  viewOrders,
  pendingApproval,
  dispatch,
}

class _OrdersScreen extends StatefulWidget {
  const _OrdersScreen({
    required this.state,
    required this.profile,
    required this.onSaveState,
    this.mode = _OrderWorkspaceMode.newOrder,
  });

  final CatalogueState state;
  final CrimsonProfile profile;
  final _OrderWorkspaceMode mode;
  final Future<void> Function(CatalogueState state) onSaveState;

  @override
  State<_OrdersScreen> createState() => _OrdersScreenState();
}

class _OrdersScreenState extends State<_OrdersScreen> {
  final _customerController = TextEditingController();
  final _phoneController = TextEditingController();
  final _salesmanController = TextEditingController();
  final _notesController = TextEditingController();
  final _searchController = TextEditingController();
  final _quantityController = TextEditingController(text: '1');
  final _discountController = TextEditingController();
  final _additionalDiscountController = TextEditingController(text: '0');
  final _searchFocusNode = FocusNode();
  final _quantityFocusNode = FocusNode();
  final List<_OrderLineDraft> _lines = [];
  String _query = '';
  int _highlightedOptionIndex = 0;
  _StockItemOption? _selectedOption;
  bool _saving = false;
  String _customerType = 'regular';
  ManagedCustomer? _selectedCustomer;
  Future<List<ManagedCustomer>>? _customerOptions;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final scope = _CustomerServiceScope.maybeOf(context);
    if (_customerOptions == null && scope != null && widget.profile.canManageCatalogue) {
      _customerOptions = scope.repository().then((repository) => repository.list());
    }
  }

  @override
  void dispose() {
    _customerController.dispose();
    _phoneController.dispose();
    _salesmanController.dispose();
    _notesController.dispose();
    _searchController.dispose();
    _quantityController.dispose();
    _discountController.dispose();
    _additionalDiscountController.dispose();
    _searchFocusNode.dispose();
    _quantityFocusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final options = _stockOptions(widget.state);
    final filteredOptions = _filterOptions(options, _query).take(30).toList();
    final lineSubtotal =
        _lines.fold<double>(0, (sum, line) => sum + line.total);
    final additionalPercent =
        _discountPercent(_additionalDiscountController.text);
    final total = lineSubtotal * (1 - additionalPercent / 100);
    final orders = widget.state.customerOrders.toList()
      ..sort((left, right) => right.createdAt.compareTo(left.createdAt));
    final visibleOrders = _ordersForMode(orders);
    final showCreateOrder = widget.mode == _OrderWorkspaceMode.newOrder;

    return SingleChildScrollView(
      padding: const EdgeInsets.only(bottom: 18),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (showCreateOrder)
            _Surface(
              padding: const EdgeInsets.all(18),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const _SectionHeader(
                    title: 'New Order',
                    subtitle:
                        'StockFlow-style order entry: customer, salesman, item, quantity, discount and save.',
                  ),
                  const SizedBox(height: 14),
                  Wrap(spacing: 12, crossAxisAlignment: WrapCrossAlignment.center, children: [
                    ChoiceChip(label: const Text('Regular customer'), selected: _customerType == 'regular', onSelected: (_) => setState(() { _customerType = 'regular'; _selectedCustomer = null; _customerController.clear(); })),
                    ChoiceChip(label: const Text('Retail customer'), selected: _customerType == 'retail', onSelected: (_) => setState(() { _customerType = 'retail'; _selectedCustomer = null; _customerController.clear(); })),
                  ]),
                  if (_customerType == 'regular')
                    FutureBuilder<List<ManagedCustomer>>(
                      future: _customerOptions,
                      builder: (context, snapshot) {
                        if (snapshot.hasError) return const Padding(padding: EdgeInsets.symmetric(vertical: 12), child: Text('Customer list is unavailable. Check your connection.'));
                        if (!snapshot.hasData) return const Padding(padding: EdgeInsets.symmetric(vertical: 12), child: Text('Loading customers…'));
                        final customers = snapshot.data!.where((c) => c.role == 'customer' && c.status != 'disabled').toList();
                        return Padding(padding: const EdgeInsets.symmetric(vertical: 12), child: DropdownButtonFormField<String>(
                          initialValue: _selectedCustomer?.userId,
                          decoration: _inputDecoration('Select customer'),
                          items: [for (final c in customers) DropdownMenuItem(value: c.userId, child: Text(c.name))],
                          onChanged: (id) => setState(() {
                            _selectedCustomer = customers.where((c) => c.userId == id).firstOrNull;
                            _customerController.text = _selectedCustomer?.name ?? '';
                            _phoneController.text = _selectedCustomer?.phone ?? '';
                          }),
                        ));
                      },
                    ),
                  Wrap(
                    spacing: 10,
                    runSpacing: 10,
                    children: [
                      SizedBox(
                        width: 280,
                        child: TextField(
                          controller: _customerController,
                          readOnly: _customerType == 'regular',
                          decoration: _inputDecoration('Customer / party name'),
                        ),
                      ),
                      SizedBox(
                        width: 220,
                        child: TextField(
                          controller: _phoneController,
                          decoration: _inputDecoration('Phone / WhatsApp'),
                        ),
                      ),
                      SizedBox(
                        width: 220,
                        child: TextField(
                          controller: _salesmanController,
                          decoration: _inputDecoration('Salesman'),
                        ),
                      ),
                      SizedBox(
                        width: 220,
                        child: TextField(
                          controller: _salesmanController,
                          decoration: _inputDecoration('Salesman'),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 16),
                  const _SectionHeader(
                    title: 'Add item',
                    subtitle:
                        'Use keyboard: type, Up/Down to choose, Enter, quantity, Enter.',
                  ),
                  const SizedBox(height: 10),
                  Wrap(
                    spacing: 10,
                    runSpacing: 10,
                    crossAxisAlignment: WrapCrossAlignment.center,
                    children: [
                      SizedBox(
                        width: 540,
                        child: Focus(
                          onKeyEvent: (node, event) =>
                              _handleSuggestionKey(event, filteredOptions),
                          child: TextField(
                            controller: _searchController,
                            focusNode: _searchFocusNode,
                            onChanged: (value) => setState(() {
                              _query = value;
                              _selectedOption = null;
                              _highlightedOptionIndex = 0;
                            }),
                            onSubmitted: (_) =>
                                _selectHighlightedOption(filteredOptions),
                            decoration: _inputDecoration('Search item / SKU')
                                .copyWith(prefixIcon: const Icon(Icons.search)),
                          ),
                        ),
                      ),
                      SizedBox(
                        width: 150,
                        child: TextField(
                          controller: _quantityController,
                          focusNode: _quantityFocusNode,
                          keyboardType: const TextInputType.numberWithOptions(
                              decimal: true),
                          onSubmitted: (_) => _addLine(),
                          decoration: _inputDecoration('Qty'),
                        ),
                      ),
                      SizedBox(
                        width: 170,
                        child: TextField(
                          controller: _discountController,
                          keyboardType: const TextInputType.numberWithOptions(
                              decimal: true),
                          onSubmitted: (_) => _addLine(),
                          decoration: _inputDecoration('Revised Disc'),
                        ),
                      ),
                      if (_selectedOption != null)
                        Padding(
                          padding: const EdgeInsets.only(right: 4),
                          child: Text(
                            'Rate locked: ${formatCompactPrice(_selectedOption!.unitPrice.toString())}',
                            style: const TextStyle(fontWeight: FontWeight.w800),
                          ),
                        ),
                      FilledButton.icon(
                        onPressed: _addLine,
                        icon: const Icon(Icons.add_rounded),
                        label: const Text('Add item'),
                      ),
                    ],
                  ),
                  if (_query.trim().isNotEmpty && _selectedOption == null) ...[
                    const SizedBox(height: 10),
                    _SuggestionPanel(
                      options: filteredOptions,
                      highlightedIndex: _highlightedOptionIndex,
                      onSelect: _selectOption,
                    ),
                  ],
                  const SizedBox(height: 14),
                  _OrderLinesTable(
                    lines: _lines,
                    onRemove: (index) => setState(() => _lines.removeAt(index)),
                    onEditDiscount: widget.profile.canManageCatalogue
                        ? _editDraftLineDiscount
                        : null,
                  ),
                  const SizedBox(height: 14),
                  TextField(
                    controller: _notesController,
                    minLines: 2,
                    maxLines: 4,
                    decoration: _inputDecoration('Order notes'),
                  ),
                  const SizedBox(height: 14),
                  SizedBox(
                    width: 230,
                    child: TextField(
                      controller: _additionalDiscountController,
                      enabled: widget.profile.canManageCatalogue,
                      keyboardType:
                          const TextInputType.numberWithOptions(decimal: true),
                      onChanged: (_) => setState(() {}),
                      decoration: _inputDecoration('Additional discount %'),
                    ),
                  ),
                  const SizedBox(height: 8),
                  _DiscountSummaryRow(
                    label: 'After item discounts',
                    amount: lineSubtotal,
                  ),
                  _DiscountSummaryRow(
                    label: 'Additional discount',
                    amount: -(lineSubtotal - total),
                  ),
                  const SizedBox(height: 14),
                  _SoftPanel(
                    child: Row(
                      children: [
                        _StatusPill(
                          label: _displayPrice(
                              formatCompactPrice(total.toString())),
                          color: _CrimsonColors.crimson,
                          background: _CrimsonColors.crimsonLight,
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Text(
                            'Order saves as Pending Approval. Stock is deducted when the bill is generated after dispatch.',
                            style:
                                Theme.of(context).textTheme.bodySmall?.copyWith(
                                      color: _CrimsonColors.textSecondary,
                                    ),
                          ),
                        ),
                        OutlinedButton.icon(
                          onPressed: _lines.isEmpty ? null : _clearDraft,
                          icon: const Icon(Icons.clear_rounded),
                          label: const Text('Clear'),
                        ),
                        const SizedBox(width: 10),
                        FilledButton.icon(
                          onPressed:
                              _saving || _lines.isEmpty ? null : _saveOrder,
                          icon: const Icon(Icons.save_outlined),
                          label: Text(_saving ? 'Saving...' : 'Save order'),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          if (showCreateOrder) const SizedBox(height: 14),
          _Surface(
            padding: const EdgeInsets.all(18),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _SectionHeader(
                  title: _ordersTitle,
                  subtitle: _ordersSubtitle,
                ),
                const SizedBox(height: 10),
                if (visibleOrders.isEmpty)
                  _SoftPanel(
                    child: Text(
                      _emptyOrdersMessage,
                      style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                            color: _CrimsonColors.textSecondary,
                          ),
                    ),
                  )
                else
                  for (final order in visibleOrders)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 8),
                      child: _OrderHistoryRow(
                        order: order,
                        canManage: widget.profile.canManageCatalogue,
                        onOpen: () => _showOrderDetail(order),
                        onStatusChanged: (status) =>
                            _updateOrderStatus(order, status),
                      ),
                    ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  List<CustomerOrderDraft> _ordersForMode(List<CustomerOrderDraft> orders) {
    return switch (widget.mode) {
      _OrderWorkspaceMode.newOrder || _OrderWorkspaceMode.viewOrders => orders,
      _OrderWorkspaceMode.pendingApproval => orders
          .where((order) =>
              order.status == CustomerOrderStatus.placed ||
              order.status == CustomerOrderStatus.draft)
          .toList(),
      _OrderWorkspaceMode.dispatch => orders
          .where((order) =>
              order.status == CustomerOrderStatus.confirmed ||
              order.status == CustomerOrderStatus.packed ||
              order.status == CustomerOrderStatus.dispatched)
          .toList(),
    };
  }

  String get _ordersTitle => switch (widget.mode) {
        _OrderWorkspaceMode.newOrder => 'Recent Orders',
        _OrderWorkspaceMode.viewOrders => 'View Orders',
        _OrderWorkspaceMode.pendingApproval => 'Pending Approval',
        _OrderWorkspaceMode.dispatch => 'Dispatch',
      };

  String get _ordersSubtitle => switch (widget.mode) {
        _OrderWorkspaceMode.newOrder =>
          'Recently saved orders and status updates.',
        _OrderWorkspaceMode.viewOrders =>
          'All saved customer orders in one place.',
        _OrderWorkspaceMode.pendingApproval =>
          'Orders waiting for admin confirmation or approval.',
        _OrderWorkspaceMode.dispatch =>
          'Confirmed, packed and dispatched orders for delivery follow-up.',
      };

  String get _emptyOrdersMessage => switch (widget.mode) {
        _OrderWorkspaceMode.newOrder => 'No orders saved yet.',
        _OrderWorkspaceMode.viewOrders => 'No orders saved yet.',
        _OrderWorkspaceMode.pendingApproval => 'No pending approval orders.',
        _OrderWorkspaceMode.dispatch => 'No dispatch-ready orders.',
      };

  KeyEventResult _handleSuggestionKey(
    KeyEvent event,
    List<_StockItemOption> options,
  ) {
    if (event is! KeyDownEvent || options.isEmpty) {
      return KeyEventResult.ignored;
    }
    if (event.logicalKey == LogicalKeyboardKey.arrowDown) {
      setState(() => _highlightedOptionIndex =
          (_highlightedOptionIndex + 1).clamp(0, options.length - 1));
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.arrowUp) {
      setState(() => _highlightedOptionIndex =
          (_highlightedOptionIndex - 1).clamp(0, options.length - 1));
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.enter) {
      _selectHighlightedOption(options);
      return KeyEventResult.handled;
    }
    return KeyEventResult.ignored;
  }

  void _selectHighlightedOption(List<_StockItemOption> options) {
    if (options.isEmpty) return;
    _selectOption(
        options[_highlightedOptionIndex.clamp(0, options.length - 1)]);
  }

  void _selectOption(_StockItemOption option) {
    setState(() {
      _selectedOption = option;
      _query = option.displayName;
      _searchController.text = option.displayName;
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _quantityFocusNode.requestFocus();
      _quantityController.selection = TextSelection(
        baseOffset: 0,
        extentOffset: _quantityController.text.length,
      );
    });
  }

  void _addLine() {
    final option = _selectedOption ??
        (_filterOptions(_stockOptions(widget.state), _query).firstOrNull);
    if (option == null) {
      _showMessage(context, 'Search and select an item first.');
      return;
    }
    final qty = double.tryParse(_quantityController.text.trim());
    if (qty == null || qty <= 0) {
      _showMessage(context, 'Enter quantity.');
      return;
    }
    final revisedText = _discountController.text.trim();
    final revisedValue = double.tryParse(revisedText.replaceAll('%', ''));
    if (revisedText.isNotEmpty &&
        (revisedValue == null ||
            !revisedValue.isFinite ||
            revisedValue < 0 ||
            revisedValue > 100)) {
      _showMessage(context, 'Enter an item discount from 0 to 100%.');
      return;
    }
    final categoryPercent =
        categoryDiscountFor(widget.state.categories, option.category);
    setState(() {
      _lines.add(_OrderLineDraft(
        option: option,
        quantity: qty,
        defaultDiscount: categoryPercent > 0 && option.unitPrice > 0
            ? '${formatCompactPrice(categoryPercent)}%'
            : '',
        revisedDiscount: _normalDiscountText(_discountController.text),
      ));
      _selectedOption = null;
      _query = '';
      _highlightedOptionIndex = 0;
      _searchController.clear();
      _quantityController.text = '1';
      _discountController.clear();
    });
    WidgetsBinding.instance
        .addPostFrameCallback((_) => _searchFocusNode.requestFocus());
  }

  Future<void> _editDraftLineDiscount(int index) async {
    if (!widget.profile.canManageCatalogue ||
        index < 0 ||
        index >= _lines.length) {
      return;
    }
    final line = _lines[index];
    final controller = TextEditingController(
      text: formatCompactPrice(_discountPercent(line.finalDiscount)),
    );
    try {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: Text('Discount · ${line.option.productName}'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                  'Category discount: ${line.defaultDiscount.isEmpty ? '0%' : line.defaultDiscount}'),
              const SizedBox(height: 12),
              TextField(
                controller: controller,
                keyboardType:
                    const TextInputType.numberWithOptions(decimal: true),
                decoration: _inputDecoration('Final item discount %'),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () {
                final value =
                    double.tryParse(controller.text.trim().replaceAll('%', ''));
                if (value == null ||
                    !value.isFinite ||
                    value < 0 ||
                    value > 100) {
                  _showMessage(
                      dialogContext, 'Enter a discount from 0 to 100%.');
                  return;
                }
                setState(() {
                  _lines[index] = _OrderLineDraft(
                    option: line.option,
                    quantity: line.quantity,
                    defaultDiscount: line.defaultDiscount,
                    revisedDiscount:
                        value == _discountPercent(line.defaultDiscount)
                            ? ''
                            : '${formatCompactPrice(value)}%',
                  );
                });
                Navigator.pop(dialogContext);
              },
              child: const Text('Apply'),
            ),
          ],
        ),
      );
    } finally {
      controller.dispose();
    }
  }

  Future<void> _saveOrder() async {
    if (_lines.isEmpty) return;
    if (cleanText(_customerController.text).isEmpty || (_customerType == 'regular' && _selectedCustomer == null)) {
      _showMessage(context, _customerType == 'regular' ? 'Select a registered customer.' : 'Enter the retail customer name.');
      return;
    }
    final additionalValue =
        double.tryParse(_additionalDiscountController.text.trim());
    if (additionalValue == null ||
        !additionalValue.isFinite ||
        additionalValue < 0 ||
        additionalValue > 100) {
      _showMessage(context, 'Enter an additional discount from 0 to 100%.');
      return;
    }
    setState(() => _saving = true);
    try {
      final now = DateTime.now();
      final productsById = {
        for (final product in widget.state.products) product.id: product
      };
      final order = CustomerOrderDraft(
        orderNumber: _nextOrderNumber(),
        customerType: _customerType,
        customerAccountId: _customerType == 'regular' ? (_selectedCustomer?.userId ?? '') : '',
        customerName: cleanText(_customerController.text),
        customerPhone: cleanText(_phoneController.text),
        customerNotes: cleanText(_notesController.text),
        salesman: cleanText(_salesmanController.text),
        additionalDiscountPercent: additionalValue,
        status: CustomerOrderStatus.placed,
        createdAt: now.toUtc().toIso8601String(),
        updatedAt: now.toUtc().toIso8601String(),
        items: _lines.map((line) {
          final product = productsById[line.option.productId];
          return CustomerOrderItemDraft(
            productId: line.option.productId,
            productName: line.option.productName,
            stockItemId: line.option.stockItemId,
            stockSku: line.option.stockSku,
            brand: line.option.brand,
            size: line.option.size,
            finish: line.option.finish,
            imagePath: product == null
                ? ''
                : (product.imagePaths.isNotEmpty
                    ? product.imagePaths.first
                    : product.imagePath),
            quantity: line.quantity,
            unitPrice: line.option.unitPrice,
            defaultDiscount: line.defaultDiscount,
            revisedDiscount: line.revisedDiscount,
            finalDiscount: line.finalDiscount,
          );
        }).toList(),
      );
      await widget.onSaveState(widget.state.copyWith(
        customerOrders: [...widget.state.customerOrders, order],
        updatedAt: now.toIso8601String(),
      ));
      if (!mounted) return;
      _showMessage(context, 'Order saved.');
      _clearDraft();
    } on Object catch (error) {
      if (mounted) _showMessage(context, 'Order save failed: $error');
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  Future<void> _updateOrderStatus(
    CustomerOrderDraft order,
    CustomerOrderStatus status,
  ) async {
    if (status == CustomerOrderStatus.confirmed) {
      await _showApprovalDialog(order);
      return;
    }
    if (status == CustomerOrderStatus.dispatched) {
      await _showDispatchDialog(order);
      return;
    }
    await _saveOrderStatus(order, status);
  }

  Future<void> _saveOrderStatus(
    CustomerOrderDraft order,
    CustomerOrderStatus status, {
    List<CustomerOrderItemDraft>? itemsOverride,
    String? approvedBy,
    String? dispatchDetails,
  }) async {
    final nextState = _stateAfterOrderWorkflowStatus(
      widget.state,
      order,
      status,
      itemsOverride: itemsOverride,
      approvedBy: approvedBy,
      dispatchDetails: dispatchDetails,
    );
    await widget.onSaveState(nextState);
  }

  Future<void> _showApprovalDialog(CustomerOrderDraft order) async {
    final approvedByController = TextEditingController(text: order.approvedBy);
    final controllers = [
      for (final item in order.items)
        TextEditingController(
          text: _formatQty(
            item.approvedQuantity > 0 ? item.approvedQuantity : item.quantity,
          ),
        ),
    ];
    try {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: Text('Approve ${order.orderNumber}'),
          content: SizedBox(
            width: math.min(760, MediaQuery.sizeOf(dialogContext).width * 0.9),
            child: SingleChildScrollView(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Text(
                    'Edit approved quantity for each line. Stock is deducted when the bill is generated.',
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: approvedByController,
                    decoration: const InputDecoration(
                      labelText: 'Approved by',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                  const SizedBox(height: 12),
                  for (var index = 0; index < order.items.length; index++)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 12),
                      child: _SoftPanel(
                        child: Row(
                          children: [
                            Expanded(
                              flex: 5,
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    order.items[index].productName,
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w900,
                                    ),
                                  ),
                                  const SizedBox(height: 4),
                                  Text(
                                    _orderItemVariantLabel(order.items[index]),
                                    style: const TextStyle(
                                      color: _CrimsonColors.textSecondary,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                            const SizedBox(width: 12),
                            SizedBox(
                              width: 104,
                              child: Text(
                                'Ordered\n${_formatQty(order.items[index].quantity)}',
                                textAlign: TextAlign.center,
                                style: const TextStyle(
                                  fontWeight: FontWeight.w800,
                                ),
                              ),
                            ),
                            const SizedBox(width: 12),
                            SizedBox(
                              width: 132,
                              child: TextField(
                                controller: controllers[index],
                                keyboardType:
                                    const TextInputType.numberWithOptions(
                                  decimal: true,
                                ),
                                decoration: const InputDecoration(
                                  labelText: 'Approve qty',
                                  border: OutlineInputBorder(),
                                  isDense: true,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () async {
                final approvedItems = <CustomerOrderItemDraft>[];
                for (var index = 0; index < order.items.length; index++) {
                  final item = order.items[index];
                  final qty = double.tryParse(controllers[index].text.trim());
                  if (qty == null || qty < 0 || qty > item.quantity) {
                    _showMessage(
                      dialogContext,
                      'Approved quantity must be between 0 and ordered quantity.',
                    );
                    return;
                  }
                  approvedItems.add(item.copyWith(
                    approvedQuantity: qty,
                    dispatchedQuantity: 0,
                  ));
                }
                final hasApprovedItems = approvedItems.any(
                  (item) => item.approvedQuantity > 0,
                );
                await _saveOrderStatus(
                  order,
                  hasApprovedItems
                      ? CustomerOrderStatus.confirmed
                      : CustomerOrderStatus.rejected,
                  itemsOverride: approvedItems,
                  approvedBy: cleanText(approvedByController.text),
                );
                if (dialogContext.mounted) Navigator.pop(dialogContext);
              },
              child: const Text('Save approval'),
            ),
          ],
        ),
      );
    } finally {
      approvedByController.dispose();
      for (final controller in controllers) {
        controller.dispose();
      }
    }
  }

  Future<void> _showDispatchDialog(CustomerOrderDraft order) async {
    final controllers = [
      for (final item in order.items)
        TextEditingController(
          text: _formatQty(
            item.dispatchedQuantity > 0
                ? item.dispatchedQuantity
                : item.effectiveApprovedQuantity,
          ),
        ),
    ];
    try {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: Text('Dispatch ${order.orderNumber}'),
          content: SizedBox(
            width: math.min(760, MediaQuery.sizeOf(dialogContext).width * 0.9),
            child: SingleChildScrollView(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Text(
                    'Confirm dispatch quantity. Stock is deducted when a bill is generated.',
                  ),
                  const SizedBox(height: 12),
                  for (var index = 0; index < order.items.length; index++)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 12),
                      child: _SoftPanel(
                        child: Row(
                          children: [
                            Expanded(
                              flex: 5,
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    order.items[index].productName,
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w900,
                                    ),
                                  ),
                                  const SizedBox(height: 4),
                                  Text(
                                    _orderItemVariantLabel(order.items[index]),
                                    style: const TextStyle(
                                      color: _CrimsonColors.textSecondary,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                            const SizedBox(width: 12),
                            SizedBox(
                              width: 112,
                              child: Text(
                                'Approved\n${_formatQty(order.items[index].effectiveApprovedQuantity)}',
                                textAlign: TextAlign.center,
                                style: const TextStyle(
                                  fontWeight: FontWeight.w800,
                                ),
                              ),
                            ),
                            const SizedBox(width: 12),
                            SizedBox(
                              width: 136,
                              child: TextField(
                                controller: controllers[index],
                                keyboardType:
                                    const TextInputType.numberWithOptions(
                                  decimal: true,
                                ),
                                decoration: const InputDecoration(
                                  labelText: 'Dispatch qty',
                                  border: OutlineInputBorder(),
                                  isDense: true,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () async {
                final dispatchItems = <CustomerOrderItemDraft>[];
                for (var index = 0; index < order.items.length; index++) {
                  final item = order.items[index];
                  final approved = item.effectiveApprovedQuantity;
                  final qty = double.tryParse(controllers[index].text.trim());
                  if (qty == null || qty < 0 || qty > approved) {
                    _showMessage(
                      dialogContext,
                      'Dispatch quantity must be between 0 and approved quantity.',
                    );
                    return;
                  }
                  dispatchItems.add(item.copyWith(dispatchedQuantity: qty));
                }
                if (!dispatchItems.any((item) => item.dispatchedQuantity > 0)) {
                  _showMessage(
                      dialogContext, 'Enter at least one dispatch quantity.');
                  return;
                }
                await _saveOrderStatus(
                  order,
                  CustomerOrderStatus.dispatched,
                  itemsOverride: dispatchItems,
                );
                if (dialogContext.mounted) Navigator.pop(dialogContext);
              },
              child: const Text('Save dispatch'),
            ),
          ],
        ),
      );
    } finally {
      for (final controller in controllers) {
        controller.dispose();
      }
    }
  }

  Future<void> _generateSimpleBill(CustomerOrderDraft order) async {
    try {
      final preview = previewSimpleBill(order);
      final confirmed = await showDialog<bool>(context: context, builder: (context) => AlertDialog(
        title: Text('Generate bill · ${order.orderNumber}'),
        content: Text('Generate a simple bill for ${preview.lines.length} dispatched item lines?\n\nEstimated total: Rs. ${formatCompactPrice(preview.total.toString())}\nThe final bill is calculated by the server. Stock will be deducted once when it is created.'),
        actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Generate bill'))],
      ));
      if (confirmed != true || !mounted) return;
      final scope = _CustomerServiceScope.maybeOf(context);
      final cloud = await scope?.catalogue();
      if (cloud == null) throw StateError('Cloud connection required.');
      await cloud.generateSimpleBill(order.id);
      await scope?.refresh();
      if (mounted) _showMessage(context, 'Bill generated.');
    } on Object catch (error) {
      if (mounted) _showMessage(context, 'Could not generate bill: $error');
    }
  }

  void _showOrderDetail(CustomerOrderDraft order) {
    final orderedPackets = order.items.fold<double>(
      0,
      (sum, item) => sum + item.quantity,
    );
    final pendingDispatch = order.items.fold<double>(
      0,
      (sum, item) =>
          sum +
          math.max(0, item.effectiveApprovedQuantity - item.dispatchedQuantity),
    );
    final amount = _orderWorkflowTotal(order);
    showDialog<void>(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(
          [order.orderNumber, order.customerName]
              .where((value) => cleanText(value).isNotEmpty)
              .join(' - '),
        ),
        content: SizedBox(
          width: math.min(980, MediaQuery.sizeOf(context).width * 0.9),
          child: SingleChildScrollView(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Wrap(
                  spacing: 10,
                  runSpacing: 10,
                  children: [
                    _StatusPill(
                      label: 'Status: ${order.status.label}',
                      color: _CrimsonColors.textPrimary,
                      background: _CrimsonColors.surfaceGrey,
                    ),
                    _StatusPill(
                      label: 'Packets: ${_formatQty(orderedPackets)}',
                      color: _CrimsonColors.textPrimary,
                      background: _CrimsonColors.surfaceGrey,
                    ),
                    _StatusPill(
                      label: 'Amount: ${formatCompactPrice(amount.toString())}',
                      color: _CrimsonColors.textPrimary,
                      background: _CrimsonColors.surfaceGrey,
                    ),
                    _StatusPill(
                      label: 'Pending Dispatch: ${_formatQty(pendingDispatch)}',
                      color: _CrimsonColors.textPrimary,
                      background: _CrimsonColors.surfaceGrey,
                    ),
                    if (cleanText(order.salesman).isNotEmpty)
                      _StatusPill(
                        label: 'Salesman: ${order.salesman}',
                        color: _CrimsonColors.crimson,
                        background: _CrimsonColors.crimsonLight,
                      ),
                  ],
                ),
                const SizedBox(height: 8),
                _SoftPanel(
                  child: Text(_orderWorkflowHelp(order.status)),
                ),
                const SizedBox(height: 12),
                _OrderItemsDataTable(items: order.items),
                const SizedBox(height: 12),
                _OrderDiscountBreakdown(order: order),
              ],
            ),
          ),
        ),
        actions: [
          if (widget.profile.canManageCatalogue)
            TextButton.icon(
              onPressed: () {
                final repository = _CustomerServiceScope.maybeOf(this.context)?.catalogue;
                Navigator.pop(context);
                if (repository != null) Navigator.of(this.context).push(MaterialPageRoute<void>(
                  builder: (_) => CustomerBillsScreen(repository: repository, title: 'Bills'),
                ));
              },
              icon: const Icon(Icons.receipt_long_outlined),
              label: const Text('View bills'),
            ),
          if (widget.profile.canManageCatalogue &&
              (order.status == CustomerOrderStatus.dispatched || order.status == CustomerOrderStatus.delivered))
            OutlinedButton.icon(
              onPressed: () { Navigator.pop(context); _generateSimpleBill(order); },
              icon: const Icon(Icons.receipt_long_outlined),
              label: const Text('Generate bill'),
            ),
          if (widget.profile.canManageCatalogue &&
              (order.status == CustomerOrderStatus.placed ||
                  order.status == CustomerOrderStatus.confirmed ||
                  order.status == CustomerOrderStatus.packed))
            OutlinedButton.icon(
              onPressed: () {
                Navigator.pop(context);
                _showOrderDiscountEditor(order);
              },
              icon: const Icon(Icons.percent_rounded),
              label: const Text('Edit discounts'),
            ),
          for (final status in _nextOrderWorkflowStatuses(order.status))
            status == CustomerOrderStatus.cancelled
                ? TextButton(
                    onPressed: () {
                      Navigator.pop(context);
                      _updateOrderStatus(order, status);
                    },
                    child: const Text('Cancel'),
                  )
                : FilledButton(
                    onPressed: () {
                      Navigator.pop(context);
                      _updateOrderStatus(order, status);
                    },
                    child: Text(_orderWorkflowActionLabel(status)),
                  ),
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Close'),
          ),
        ],
      ),
    );
  }

  Future<void> _showOrderDiscountEditor(CustomerOrderDraft order) async {
    if (!widget.profile.canManageCatalogue) return;
    final controllers = [
      for (final item in order.items)
        TextEditingController(
          text:
              formatCompactPrice(_discountPercent(item.effectiveDiscountText)),
        ),
    ];
    final additionalController = TextEditingController(
      text: formatCompactPrice(order.additionalDiscountPercent),
    );
    var saving = false;
    try {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) {
            final previewItems = [
              for (var index = 0; index < order.items.length; index++)
                order.items[index].copyWith(
                  finalDiscount: _normalDiscountText(controllers[index].text),
                ),
            ];
            final previewSubtotal = previewItems.fold<double>(
              0,
              (sum, item) => sum + item.lineTotal,
            );
            final previewAdditional =
                _discountPercent(additionalController.text);
            final previewTotal =
                previewSubtotal * (1 - previewAdditional / 100);
            return AlertDialog(
              title: Text('Discounts · ${order.orderNumber}'),
              content: SizedBox(
                width:
                    math.min(620, MediaQuery.sizeOf(dialogContext).width * 0.9),
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                          'Set the final discount for each item in this order.'),
                      const SizedBox(height: 12),
                      for (var index = 0; index < order.items.length; index++)
                        Padding(
                          padding: const EdgeInsets.only(bottom: 10),
                          child: _SoftPanel(
                            child: Row(
                              children: [
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(order.items[index].productName,
                                          style: const TextStyle(
                                              fontWeight: FontWeight.w900)),
                                      Text(
                                        '${_orderItemVariantLabel(order.items[index])} · Category ${order.items[index].defaultDiscount.isEmpty ? '0%' : order.items[index].defaultDiscount}',
                                        style: Theme.of(dialogContext)
                                            .textTheme
                                            .bodySmall,
                                      ),
                                    ],
                                  ),
                                ),
                                const SizedBox(width: 12),
                                SizedBox(
                                  width: 100,
                                  child: TextField(
                                    controller: controllers[index],
                                    keyboardType:
                                        const TextInputType.numberWithOptions(
                                            decimal: true),
                                    onChanged: (_) => setDialogState(() {}),
                                    decoration: _inputDecoration('Final %'),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      const SizedBox(height: 10),
                      TextField(
                        controller: additionalController,
                        keyboardType: const TextInputType.numberWithOptions(
                            decimal: true),
                        onChanged: (_) => setDialogState(() {}),
                        decoration:
                            _inputDecoration('Additional order discount %'),
                      ),
                      const SizedBox(height: 12),
                      _DiscountSummaryRow(
                        label: 'After item discounts',
                        amount: previewSubtotal,
                      ),
                      _DiscountSummaryRow(
                        label: 'Additional discount',
                        amount: -(previewSubtotal - previewTotal),
                      ),
                      const Divider(height: 20),
                      _DiscountSummaryRow(
                        label: 'Order total',
                        amount: previewTotal,
                      ),
                    ],
                  ),
                ),
              ),
              actions: [
                TextButton(
                  onPressed: saving ? null : () => Navigator.pop(dialogContext),
                  child: const Text('Cancel'),
                ),
                FilledButton.icon(
                  onPressed: saving
                      ? null
                      : () async {
                          final linePercents = <double>[];
                          for (final controller in controllers) {
                            final value = double.tryParse(
                                controller.text.trim().replaceAll('%', ''));
                            if (value == null ||
                                !value.isFinite ||
                                value < 0 ||
                                value > 100) {
                              _showMessage(dialogContext,
                                  'Each item discount must be 0 to 100%.');
                              return;
                            }
                            linePercents.add(value);
                          }
                          final extra = double.tryParse(additionalController
                              .text
                              .trim()
                              .replaceAll('%', ''));
                          if (extra == null ||
                              !extra.isFinite ||
                              extra < 0 ||
                              extra > 100) {
                            _showMessage(dialogContext,
                                'Additional discount must be 0 to 100%.');
                            return;
                          }
                          setDialogState(() => saving = true);
                          try {
                            final now =
                                DateTime.now().toUtc().toIso8601String();
                            final updatedItems = [
                              for (var index = 0;
                                  index < order.items.length;
                                  index++)
                                order.items[index].copyWith(
                                  revisedDiscount: linePercents[index] ==
                                          _discountPercent(order
                                              .items[index].defaultDiscount)
                                      ? ''
                                      : '${formatCompactPrice(linePercents[index])}%',
                                  finalDiscount:
                                      '${formatCompactPrice(linePercents[index])}%',
                                ),
                            ];
                            final updated = order.copyWith(
                              items: updatedItems,
                              additionalDiscountPercent: extra,
                              updatedAt: now,
                            );
                            await widget.onSaveState(widget.state.copyWith(
                              customerOrders: [
                                for (final item in widget.state.customerOrders)
                                  item.id == order.id ? updated : item,
                              ],
                              updatedAt: now,
                            ));
                            if (!dialogContext.mounted) return;
                            Navigator.pop(dialogContext);
                            if (mounted) {
                              _showMessage(context, 'Order discounts saved.');
                            }
                          } on Object catch (error) {
                            if (dialogContext.mounted) {
                              _showMessage(dialogContext,
                                  'Discount save failed: $error');
                              setDialogState(() => saving = false);
                            }
                          }
                        },
                  icon: const Icon(Icons.save_outlined),
                  label: Text(saving ? 'Saving...' : 'Save discounts'),
                ),
              ],
            );
          },
        ),
      );
    } finally {
      for (final controller in controllers) {
        controller.dispose();
      }
      additionalController.dispose();
    }
  }

  void _clearDraft() => setState(() {
        _lines.clear();
        _selectedOption = null;
        _query = '';
        _highlightedOptionIndex = 0;
        _searchController.clear();
        _quantityController.text = '1';
        _discountController.clear();
        _additionalDiscountController.text = '0';
        _salesmanController.clear();
        _notesController.clear();
        _selectedCustomer = null;
        _customerController.clear();
        _phoneController.clear();
      });

  String _nextOrderNumber() {
    return _nextOrderNumberFrom(widget.state.customerOrders);
  }
}

double _orderWorkflowTotal(CustomerOrderDraft order) {
  if (_orderUsesApprovedPricing(order.status)) return order.approvedTotal;
  return order.total;
}

bool _orderUsesApprovedPricing(CustomerOrderStatus status) {
  return status == CustomerOrderStatus.confirmed ||
      status == CustomerOrderStatus.packed ||
      status == CustomerOrderStatus.dispatched ||
      status == CustomerOrderStatus.delivered;
}

CatalogueState _stateAfterOrderWorkflowStatus(
  CatalogueState state,
  CustomerOrderDraft order,
  CustomerOrderStatus status, {
  List<CustomerOrderItemDraft>? itemsOverride,
  String? approvedBy,
  String? dispatchDetails,
}) {
  final now = DateTime.now();
  final nowUtc = now.toUtc().toIso8601String();
  final updatedOrders = state.customerOrders.map((item) {
    if (item.id != order.id) return item;
    final sourceItems = itemsOverride ?? item.items;
    final updatedItems = sourceItems.map((line) {
      if (status == CustomerOrderStatus.confirmed) {
        final approved = itemsOverride == null
            ? (line.approvedQuantity > 0
                ? line.approvedQuantity
                : line.quantity)
            : math.min(math.max(0, line.approvedQuantity), line.quantity);
        return line.copyWith(
          approvedQuantity: approved.toDouble(),
          dispatchedQuantity: 0,
        );
      }
      if (status == CustomerOrderStatus.cancelled ||
          status == CustomerOrderStatus.rejected) {
        return line.copyWith(
          approvedQuantity: 0,
          dispatchedQuantity: 0,
        );
      }
      if (status == CustomerOrderStatus.dispatched) {
        final approved = line.effectiveApprovedQuantity > 0
            ? line.effectiveApprovedQuantity
            : line.quantity;
        final dispatched = itemsOverride == null
            ? approved
            : math.min(math.max(0, line.dispatchedQuantity), approved);
        return line.copyWith(
          approvedQuantity: approved.toDouble(),
          dispatchedQuantity: dispatched.toDouble(),
        );
      }
      return line;
    }).toList();
    return item.copyWith(
      status: status,
      items: updatedItems,
      approvedBy: approvedBy ?? item.approvedBy,
      dispatchDetails: dispatchDetails ?? item.dispatchDetails,
      updatedAt: nowUtc,
    );
  }).toList();

  return state.copyWith(
    customerOrders: updatedOrders,
    updatedAt: now.toIso8601String(),
  );
}

class _OrderLineDraft {
  const _OrderLineDraft({
    required this.option,
    required this.quantity,
    this.defaultDiscount = '',
    this.revisedDiscount = '',
  });

  final _StockItemOption option;
  final double quantity;
  final String defaultDiscount;
  final String revisedDiscount;

  String get finalDiscount => revisedDiscount.trim().isEmpty
      ? defaultDiscount.trim()
      : revisedDiscount.trim();
  double get discountMultiplier => 1 - (_discountPercent(finalDiscount) / 100);
  double get total => quantity * option.unitPrice * discountMultiplier;
}

class _OrderLinesTable extends StatelessWidget {
  const _OrderLinesTable({
    required this.lines,
    required this.onRemove,
    this.onEditDiscount,
  });

  final List<_OrderLineDraft> lines;
  final ValueChanged<int> onRemove;
  final ValueChanged<int>? onEditDiscount;

  @override
  Widget build(BuildContext context) {
    if (lines.isEmpty) {
      return _SoftPanel(
        child: Center(
          child: Padding(
            padding: const EdgeInsets.all(18),
            child: Text(
              'No items added yet.',
              style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                    color: _CrimsonColors.textSecondary,
                  ),
            ),
          ),
        ),
      );
    }
    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: DataTable(
        headingRowColor: WidgetStateProperty.all(_CrimsonColors.crimsonLight),
        columns: const [
          DataColumn(label: Text('Product')),
          DataColumn(label: Text('SKU')),
          DataColumn(label: Text('Variant')),
          DataColumn(label: Text('Qty')),
          DataColumn(label: Text('Rate')),
          DataColumn(label: Text('Default Disc')),
          DataColumn(label: Text('Revised Disc')),
          DataColumn(label: Text('Final Disc')),
          DataColumn(label: Text('Total')),
          DataColumn(label: Text('')),
        ],
        rows: [
          for (var index = 0; index < lines.length; index++)
            DataRow(cells: [
              DataCell(Text(lines[index].option.productName)),
              DataCell(Text(lines[index].option.stockSku)),
              DataCell(Text([
                lines[index].option.size,
                lines[index].option.finish
              ].where((value) => cleanText(value).isNotEmpty).join(' / '))),
              DataCell(Text(_formatQty(lines[index].quantity))),
              DataCell(Text(formatCompactPrice(
                  lines[index].option.unitPrice.toString()))),
              DataCell(Text(lines[index].defaultDiscount.isEmpty
                  ? '-'
                  : lines[index].defaultDiscount)),
              DataCell(Text(lines[index].revisedDiscount.isEmpty
                  ? '-'
                  : lines[index].revisedDiscount)),
              DataCell(Text(lines[index].finalDiscount.isEmpty
                  ? '-'
                  : lines[index].finalDiscount)),
              DataCell(Text(formatCompactPrice(lines[index].total.toString()))),
              DataCell(Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (onEditDiscount != null)
                    IconButton(
                      tooltip: 'Edit item discount',
                      icon: const Icon(Icons.percent_rounded),
                      onPressed: () => onEditDiscount!(index),
                    ),
                  IconButton(
                    tooltip: 'Remove item',
                    icon: const Icon(Icons.delete_outline_rounded),
                    onPressed: () => onRemove(index),
                  ),
                ],
              )),
            ]),
        ],
      ),
    );
  }
}

