class _CustomerStorefrontHome extends StatelessWidget {
  const _CustomerStorefrontHome({
    required this.state,
    required this.profile,
    required this.compact,
    required this.onOpenProducts,
    required this.onOpenProductCategory,
    required this.onSelectProduct,
  });

  final CatalogueState state;
  final CrimsonProfile profile;
  final bool compact;
  final VoidCallback onOpenProducts;
  final ValueChanged<String> onOpenProductCategory;
  final ValueChanged<ProductDraft> onSelectProduct;

  @override
  Widget build(BuildContext context) {
    final products = _activeProductsForRole(state, profile);
    final categories = _CategorySummary.fromProducts(
      products,
      categories: state.categories,
    )
        .where((summary) => summary.name.isNotEmpty)
        .take(compact ? 8 : 10)
        .toList();
    final stockTotals = _displayProductStockTotals(state);
    final featuredProducts = [
      ...products.where((product) => _primaryImagePath(product) != null),
      ...products.where((product) => _primaryImagePath(product) == null),
    ].take(compact ? 6 : 8).toList();

    return SingleChildScrollView(
      padding: EdgeInsets.only(bottom: compact ? 18 : 24),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _CustomerBannerCarousel(
            imagePaths: state.bannerImagePaths,
            compact: compact,
          ),
          SizedBox(height: compact ? 18 : 24),
          _CustomerSectionHeader(
            title: 'Featured categories',
            actionLabel: 'View all',
            onAction: onOpenProducts,
          ),
          const SizedBox(height: 12),
          if (categories.isEmpty)
            const _EmptyListMessage()
          else if (compact)
            SizedBox(
              height: 174,
              child: ListView.separated(
                scrollDirection: Axis.horizontal,
                itemCount: categories.length,
                separatorBuilder: (_, __) => const SizedBox(width: 12),
                itemBuilder: (context, index) => SizedBox(
                  width: 158,
                  child: _CustomerCategoryCard(
                    summary: categories[index],
                    compact: true,
                    onTap: () => onOpenProductCategory(categories[index].name),
                  ),
                ),
              ),
            )
          else
            GridView.builder(
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: 4,
                crossAxisSpacing: 14,
                mainAxisSpacing: 14,
                childAspectRatio: 1.85,
              ),
              itemCount: categories.length,
              itemBuilder: (context, index) => _CustomerCategoryCard(
                summary: categories[index],
                compact: false,
                onTap: () => onOpenProductCategory(categories[index].name),
              ),
            ),
          SizedBox(height: compact ? 22 : 28),
          _CustomerSectionHeader(
            title: 'Featured products',
            actionLabel: 'Browse catalogue',
            onAction: onOpenProducts,
          ),
          const SizedBox(height: 12),
          if (featuredProducts.isEmpty)
            const _EmptyListMessage()
          else if (compact)
            GridView.builder(
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: 2,
                crossAxisSpacing: 12,
                mainAxisSpacing: 12,
                childAspectRatio: 0.72,
              ),
              itemCount: featuredProducts.length,
              itemBuilder: (context, index) => _MobileProductCard(
                product: featuredProducts[index],
                stockQuantity: stockTotals[featuredProducts[index].id],
                selected: false,
                onTap: () => onSelectProduct(featuredProducts[index]),
              ),
            )
          else
            GridView.builder(
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: 4,
                crossAxisSpacing: 14,
                mainAxisSpacing: 14,
                childAspectRatio: 0.95,
              ),
              itemCount: featuredProducts.length,
              itemBuilder: (context, index) => _ProductGridCard(
                product: featuredProducts[index],
                stockQuantity: stockTotals[featuredProducts[index].id],
                selected: false,
                showSubcategory: profile.role != CrimsonUserRole.customer,
                onTap: () => onSelectProduct(featuredProducts[index]),
              ),
            ),
        ],
      ),
    );
  }
}

class _CustomerBannerCarousel extends StatefulWidget {
  const _CustomerBannerCarousel({
    required this.imagePaths,
    required this.compact,
  });

  final List<String> imagePaths;
  final bool compact;

  @override
  State<_CustomerBannerCarousel> createState() =>
      _CustomerBannerCarouselState();
}

class _CustomerBannerCarouselState extends State<_CustomerBannerCarousel> {
  late final PageController _controller;
  Timer? _timer;
  int _page = 0;

  List<String> get _paths => widget.imagePaths
      .map(cleanText)
      .where((path) => path.isNotEmpty)
      .take(3)
      .toList();

  @override
  void initState() {
    super.initState();
    _controller = PageController();
    _startTimer();
  }

  @override
  void didUpdateWidget(covariant _CustomerBannerCarousel oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.imagePaths.join('|') != widget.imagePaths.join('|')) {
      _page = 0;
      _timer?.cancel();
      _startTimer();
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    _controller.dispose();
    super.dispose();
  }

  void _startTimer() {
    if (_paths.length < 2) return;
    _timer = Timer.periodic(const Duration(seconds: 4), (_) {
      if (!mounted || !_controller.hasClients) return;
      final next = (_page + 1) % _paths.length;
      _controller.animateToPage(
        next,
        duration: const Duration(milliseconds: 420),
        curve: Curves.easeOutCubic,
      );
    });
  }

  @override
  Widget build(BuildContext context) {
    final paths = _paths;
    final radius = BorderRadius.circular(widget.compact ? 22 : 26);
    return LayoutBuilder(
      builder: (context, constraints) {
        final availableWidth = constraints.maxWidth.isFinite
            ? constraints.maxWidth
            : MediaQuery.sizeOf(context).width;
        final bannerWidth = availableWidth;
        final bannerHeight = widget.compact
            ? availableWidth.clamp(170.0, 190.0).toDouble()
            : availableWidth.clamp(210.0, 230.0).toDouble();
        return Align(
          alignment: Alignment.center,
          child: SizedBox(
            width: bannerWidth,
            height: bannerHeight,
            child: ClipRRect(
              borderRadius: radius,
              child: DecoratedBox(
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: radius,
                  boxShadow: const [
                    BoxShadow(
                      color: Color(0x18000000),
                      blurRadius: 18,
                      offset: Offset(0, 8),
                    ),
                  ],
                ),
                child: Stack(
                  children: [
                    if (paths.isEmpty)
                      const Positioned.fill(child: _CustomerFallbackBanner())
                    else
                      Positioned.fill(
                        child: PageView.builder(
                          controller: _controller,
                          itemCount: paths.length,
                          onPageChanged: (value) =>
                              setState(() => _page = value),
                          itemBuilder: (context, index) => _CustomerBannerImage(
                            path: paths[index],
                          ),
                        ),
                      ),
                    if (paths.length > 1)
                      Positioned(
                        right: 18,
                        bottom: 14,
                        child: Row(
                          children: [
                            for (var index = 0; index < paths.length; index++)
                              AnimatedContainer(
                                duration: const Duration(milliseconds: 300),
                                margin: const EdgeInsets.only(left: 6),
                                width: _page == index ? 22 : 8,
                                height: 8,
                                decoration: BoxDecoration(
                                  color: _page == index
                                      ? _CrimsonColors.crimson
                                      : Colors.black.withValues(alpha: 0.25),
                                  borderRadius: BorderRadius.circular(999),
                                ),
                              ),
                          ],
                        ),
                      ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

class _CustomerBannerImage extends StatelessWidget {
  const _CustomerBannerImage({required this.path});

  final String path;

  @override
  Widget build(BuildContext context) {
    final cleanPath = cleanText(path);
    Widget fallback() => const _CustomerFallbackBanner();
    if (cleanPath.isEmpty) return fallback();
    if (_isNetworkImagePath(cleanPath)) {
      return CachedCatalogueImage(
        url: cleanPath,
        fit: BoxFit.cover,
        alignment: Alignment.center,
        width: double.infinity,
        height: double.infinity,
        cacheWidth: 1800,
        fallbackBuilder: (_) => fallback(),
      );
    }
    return Image.file(
      File(cleanPath),
      fit: BoxFit.cover,
      alignment: Alignment.center,
      width: double.infinity,
      height: double.infinity,
      cacheWidth: 1800,
      errorBuilder: (_, __, ___) => fallback(),
    );
  }
}

