class _DashboardScreen extends StatelessWidget {
  const _DashboardScreen({
    required this.state,
    required this.profile,
    required this.onLogout,
    required this.onSelectProduct,
    required this.onOpenProducts,
    required this.onOpenProductCategory,
  });

  final CatalogueState state;
  final CrimsonProfile profile;
  final Future<void> Function() onLogout;
  final ValueChanged<ProductDraft> onSelectProduct;
  final VoidCallback onOpenProducts;
  final ValueChanged<String> onOpenProductCategory;

  @override
  Widget build(BuildContext context) {
    final products = _activeProductsForRole(state, profile);
    final variationCount = products.fold<int>(
        0, (sum, product) => sum + product.variations.length);
    final imageCount = products.fold<int>(
        0, (sum, product) => sum + product.imagePaths.length);
    final categories = state.categories.isEmpty
        ? products.map((product) => product.category).toSet().length
        : state.categories.length;

    if (!profile.canManageCatalogue) {
      return _CustomerStorefrontHome(
        state: state,
        profile: profile,
        compact: false,
        onOpenProducts: onOpenProducts,
        onOpenProductCategory: onOpenProductCategory,
        onSelectProduct: onSelectProduct,
      );
    }

    return Column(
      children: [
        Row(
          children: [
            Expanded(
              child: _MetricCard(
                label: 'Products',
                value: products.length.toString(),
                helper: 'catalogue items',
                icon: Icons.inventory_2_outlined,
              ),
            ),
            const SizedBox(width: 14),
            Expanded(
              child: _MetricCard(
                label: 'Categories',
                value: categories.toString(),
                helper: 'managed families',
                icon: Icons.category_outlined,
              ),
            ),
            const SizedBox(width: 14),
            Expanded(
              child: _MetricCard(
                label: 'Variations',
                value: variationCount.toString(),
                helper: 'finish x size rows',
                icon: Icons.grid_on_outlined,
              ),
            ),
            const SizedBox(width: 14),
            Expanded(
              child: _MetricCard(
                label: 'Images',
                value: imageCount.toString(),
                helper: 'saved product photos',
                icon: Icons.image_outlined,
              ),
            ),
          ],
        ),
        const SizedBox(height: 18),
        Expanded(
          child: Row(
            children: [
              Expanded(
                flex: 6,
                child: _RecentProductsPanel(
                  products: products,
                  onSelectProduct: onSelectProduct,
                  onOpenProducts: onOpenProducts,
