class _ProductsBrowserScreen extends StatefulWidget {
  const _ProductsBrowserScreen({
    required this.state,
    required this.profile,
    required this.selectedProduct,
    required this.initialCategory,
    required this.initialSubcategory,
    required this.onInitialCategoryConsumed,
    required this.onOpenNavigation,
    required this.canGoBack,
    required this.onBack,
    required this.onSectionBackChanged,
    required this.onAddProduct,
    required this.cloudStatus,
    required this.onRefreshCatalogue,
    required this.onSelectProduct,
    required this.onEditProduct,
    required this.onArchiveProduct,
    required this.onRestoreProduct,
    required this.onToggleProductPublished,
    required this.onSetProductsPublished,
    required this.onAddCustomerCartItem,
    required this.onOpenCart,
  });

  final CatalogueState state;
  final CrimsonProfile profile;
  final ProductDraft? selectedProduct;
  final String initialCategory;
  final String initialSubcategory;
  final VoidCallback onInitialCategoryConsumed;
  final VoidCallback onOpenNavigation;
  final bool canGoBack;
  final VoidCallback onBack;
  final void Function(VoidCallback? handler) onSectionBackChanged;
  final VoidCallback onAddProduct;
  final CloudSyncStatus cloudStatus;
  final Future<void> Function() onRefreshCatalogue;
  final ValueChanged<ProductDraft> onSelectProduct;
  final ValueChanged<ProductDraft> onEditProduct;
  final ValueChanged<ProductDraft> onArchiveProduct;
  final ValueChanged<ProductDraft> onRestoreProduct;
  final void Function(ProductDraft product, bool isPublished)
      onToggleProductPublished;
  final Future<void> Function(Set<String> productIds, bool isPublished)
      onSetProductsPublished;
  final ValueChanged<CustomerOrderItemDraft> onAddCustomerCartItem;
  final VoidCallback onOpenCart;

  @override
  State<_ProductsBrowserScreen> createState() => _ProductsBrowserScreenState();
}

class _ProductsBrowserScreenState extends State<_ProductsBrowserScreen> {
  final _searchController = TextEditingController();
  final _minPriceController = TextEditingController();
  final _maxPriceController = TextEditingController();
  Timer? _productSearchDebounce;
  bool _showArchived = false;
  String _categoryFilter = '';
  String _subcategoryFilter = '';
  String _brandFilter = '';
  String _finishFilter = '';
  String _sizeFilter = '';
  String _categorySearchReturnQuery = '';
  final Set<String> _selectedProductIds = {};
  final _multiExportService = const MultiProductExportService();
  final _fileDialogs = const WindowsFileDialogs();
  bool _exportingSelection = false;
  bool _updatingSelectionVisibility = false;
  bool? _registeredBackAvailable;
  CatalogueState? _cachedBaseState;
  CrimsonUserRole? _cachedBaseRole;
  bool? _cachedBaseArchived;
  List<ProductDraft>? _cachedBaseProducts;

  List<ProductDraft> _baseProducts({required bool canManageCatalogue}) {
    final archivedMode = canManageCatalogue && _showArchived;
    if (identical(_cachedBaseState, widget.state) &&
        _cachedBaseRole == widget.profile.role &&
        _cachedBaseArchived == archivedMode &&
        _cachedBaseProducts != null) {
      return _cachedBaseProducts!;
    }
    final products = archivedMode
        ? (widget.state.products.where((product) => product.isArchived).toList()
          ..sort(_compareProductsForCatalogue))
        : _activeProductsForRole(widget.state, widget.profile);
    _cachedBaseState = widget.state;
    _cachedBaseRole = widget.profile.role;
    _cachedBaseArchived = archivedMode;
    _cachedBaseProducts = products;
    return products;
  }

  @override
  void initState() {
    super.initState();
    _applyInitialCategory();
  }

  @override
  void didUpdateWidget(covariant _ProductsBrowserScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.initialCategory != oldWidget.initialCategory ||
        widget.initialSubcategory != oldWidget.initialSubcategory) {
      _applyInitialCategory();
    }
  }

  void _applyInitialCategory() {
    final category = cleanText(widget.initialCategory);
    if (category.isEmpty) return;
    _searchController.clear();
    _minPriceController.clear();
    _maxPriceController.clear();
    _showArchived = false;
    _selectedProductIds.clear();
    _categoryFilter = category;
    _subcategoryFilter = cleanText(widget.initialSubcategory);
    _brandFilter = '';
    _finishFilter = '';
    _sizeFilter = '';
    _categorySearchReturnQuery = '';
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) widget.onInitialCategoryConsumed();
    });
  }

  @override
  void dispose() {
    widget.onSectionBackChanged(null);
    _productSearchDebounce?.cancel();
    _searchController.dispose();
    _minPriceController.dispose();
    _maxPriceController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    _syncDesktopProductsBackHandler();
    final canSelectForExport =
        widget.profile.canExportPdf || widget.profile.canShare;
    final canManageCatalogue = widget.profile.canManageCatalogue;
    final canSelectProducts = canSelectForExport || canManageCatalogue;
    final baseProducts = _baseProducts(canManageCatalogue: canManageCatalogue);
    final searchActiveNow = cleanText(_searchController.text).isNotEmpty;
    final filteredProducts = filterCatalogueProducts(
      baseProducts,
      CatalogueProductFilter(
        query: _searchController.text,
        category: _categoryFilter,
        subcategory: _subcategoryFilter == '__all__' ? '' : _subcategoryFilter,
        brand: _brandFilter,
        finish: _finishFilter,
        size: _sizeFilter,
        minPrice: double.tryParse(cleanText(_minPriceController.text)),
        maxPrice: double.tryParse(cleanText(_maxPriceController.text)),
      ),
      categories: widget.state.categories,
      terminology: widget.state.searchTerminology,
    );
    if (!searchActiveNow) filteredProducts.sort(_compareProductsForCatalogue);
    final stockTotals = _displayProductStockTotals(widget.state);
    final filterOptions = _ProductFilterOptions.fromProducts(baseProducts);
    final activeCount = _showArchived
        ? widget.state.products.where((product) => !product.isArchived).length
        : baseProducts.length;
    final archivedCount = canManageCatalogue
        ? widget.state.products.where((product) => product.isArchived).length
        : 0;
    final categoryStats = _CategorySummary.fromProducts(
      baseProducts,
      categories: widget.state.categories,
    );
    final matchingCategories = canManageCatalogue &&
            searchActiveNow &&
            cleanText(_categoryFilter).isEmpty
        ? categoryStats
            .where((summary) =>
                categoryNameMatchesSearch(
                    summary.name, _searchController.text))
            .toList(growable: false)
        : const <_CategorySummary>[];
    final productSearchMode = cleanText(_searchController.text).isNotEmpty ||
        cleanText(_brandFilter).isNotEmpty ||
        cleanText(_finishFilter).isNotEmpty ||
        cleanText(_sizeFilter).isNotEmpty ||
        cleanText(_minPriceController.text).isNotEmpty ||
        cleanText(_maxPriceController.text).isNotEmpty ||
        _showArchived;
    final selectedCategoryProducts = _categoryFilter.isEmpty
        ? baseProducts
        : baseProducts
            .where((product) =>
                _normalUi(product.category) == _normalUi(_categoryFilter))
            .toList();
    final selectedCategoryDraft =
        widget.state.categories.cast<CategoryDraft?>().firstWhere(
              (category) =>
                  category != null && _sameName(category.name, _categoryFilter),
              orElse: () => null,
            );
    final subcategoryStats = _SubcategorySummary.fromProducts(
      selectedCategoryProducts,
      category: selectedCategoryDraft,
    );
    final customerCatalogueView =
        widget.profile.role == CrimsonUserRole.customer;
    final showCategoryBrowser =
        !productSearchMode && cleanText(_categoryFilter).isEmpty;
    final showSubcategoryBrowser = !customerCatalogueView &&
        !productSearchMode &&
        cleanText(_categoryFilter).isNotEmpty &&
        cleanText(_subcategoryFilter).isEmpty &&
        subcategoryStats.isNotEmpty;
    final showProductGrid = !showCategoryBrowser && !showSubcategoryBrowser;

    return Column(
      children: [
        _ProductsTopBar(
          searchController: _searchController,
          filterCount: _activeFilterCount,
          cloudStatus: widget.cloudStatus,
          onSearchChanged: _handleSearchChanged,
          onOpenFilters: () => _showFilters(filterOptions),
          onOpenNavigation: widget.onOpenNavigation,
          canGoBack: widget.canGoBack || _canBackWithinDesktopProducts,
          onBack: _canBackWithinDesktopProducts
              ? _backWithinDesktopProducts
              : widget.onBack,
          onRefreshCatalogue: widget.onRefreshCatalogue,
          canAddProduct: canManageCatalogue,
          onAddProduct: widget.onAddProduct,
        ),
        const SizedBox(height: 14),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _BrowsePathBar(
                category: _categoryFilter,
                subcategory: _subcategoryFilter,
                rootLabel: _categorySearchReturnQuery.isEmpty
                    ? 'Categories'
                    : 'Search results',
                visibleCount: filteredProducts.length,
                activeCount: activeCount,
                archivedCount: archivedCount,
                showArchived: _showArchived,
                hasFilters: _hasFilters,
                onClearFilters: _clearFilters,
                onBackToCategories: () {
                  setState(() {
                    _returnToDesktopCategories();
                  });
                },
                onBackToSubcategories: () {
                  setState(() {
                    _subcategoryFilter = '';
                  });
                },
              ),
              if (canSelectProducts &&
                  (_selectedProductIds.isNotEmpty || showProductGrid)) ...[
                const SizedBox(height: 8),
                CatalogueSelectionBar(
                  selectedCount: _selectedProductIds.length,
                  visibleCount: filteredProducts.length,
                  busy: _exportingSelection || _updatingSelectionVisibility,
                  onSelectAll: () => _toggleDesktopSelectionGroup(
                    filteredProducts.map((product) => product.id),
                  ),
                  onClear: () => setState(_selectedProductIds.clear),
                  onExportImage: _exportDesktopCatalogueImages,
                  onExportPdf: _exportDesktopCataloguePdf,
                  onExportStickers: _exportDesktopStickerSheets,
                  onMakeLive: canManageCatalogue
                      ? () => _updateDesktopSelectionVisibility(true)
                      : null,
                  onMakeHidden: canManageCatalogue
                      ? () => _updateDesktopSelectionVisibility(false)
                      : null,
                ),
              ],
              const SizedBox(height: 10),
              Expanded(
                child: showCategoryBrowser
                    ? _CategoryBrowseGrid(
                        summaries: categoryStats
                            .where((summary) => summary.name.isNotEmpty)
                            .toList(),
                        products: baseProducts,
                        selectedProductIds: _selectedProductIds,
                        showSubcategoryCount: !customerCatalogueView,
                        onSelectionChanged: canSelectProducts
                            ? _toggleDesktopSelectionGroup
                            : null,
                        onSelected: (category) {
                          setState(() {
                            _categoryFilter = category;
                            _subcategoryFilter = '';
                            _categorySearchReturnQuery = '';
                          });
                        },
                      )
                    : showSubcategoryBrowser
                        ? _SubcategoryBrowseGrid(
                            category: _categoryFilter,
                            summaries: subcategoryStats,
                            categoryProductCount:
                                selectedCategoryProducts.length,
                            products: selectedCategoryProducts,
                            selectedProductIds: _selectedProductIds,
                            onSelectionChanged: canSelectProducts
                                ? _toggleDesktopSelectionGroup
                                : null,
                            onShowAllProducts: () {
                              setState(() {
                                _subcategoryFilter = '__all__';
                              });
                            },
                            onSelected: (subcategory) {
                              setState(() {
                                _subcategoryFilter =
                                    customerCatalogueView ? '' : subcategory;
                              });
                            },
                          )
                        : filteredProducts.isEmpty &&
                                matchingCategories.isEmpty
                            ? const _Surface(child: _EmptyListMessage())
                            : CustomScrollView(
                                slivers: [
                                  if (matchingCategories.isNotEmpty)
                                    SliverToBoxAdapter(
                                      child: _CategorySearchResults(
                                        categories: matchingCategories,
                                        onOpenCategory:
                                            _openDesktopSearchedCategory,
                                      ),
                                    ),
                                  if (searchActiveNow &&
                                      filteredProducts.isNotEmpty)
                                    SliverToBoxAdapter(
                                      child: _SearchResultsHeading(
                                        title: 'Products',
                                        count: filteredProducts.length,
                                      ),
                                    ),
                                  SliverPadding(
                                    padding: const EdgeInsets.only(bottom: 10),
                                    sliver: SliverGrid.builder(
                                      gridDelegate:
                                          const SliverGridDelegateWithMaxCrossAxisExtent(
                                        maxCrossAxisExtent: 246,
                                        childAspectRatio: 0.94,
                                        crossAxisSpacing: 10,
                                        mainAxisSpacing: 10,
                                      ),
                                      itemCount: filteredProducts.length,
                                      itemBuilder: (context, index) {
                                        final product = filteredProducts[index];
                                        return _ProductGridCard(
                                          product: product,
                                          stockQuantity: stockTotals[product.id],
                                          showSubcategory: widget.profile.role !=
                                              CrimsonUserRole.customer,
                                          selected: _selectedProductIds
                                              .contains(product.id),
                                          onSelectionToggle: canSelectProducts
                                              ? () => _toggleDesktopProduct(
                                                    product.id,
                                                  )
                                              : null,
                                          onTogglePublished: canManageCatalogue
                                              ? () => widget
                                                  .onToggleProductPublished(
                                                    product,
                                                    !product.isPublished,
                                                  )
                                              : null,
                                          onTap: () => _openProduct(product),
                                        );
                                      },
                                    ),
                                  ),
                                ],
                              ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  bool get _canBackWithinDesktopProducts =>
      _selectedProductIds.isNotEmpty ||
      cleanText(_subcategoryFilter).isNotEmpty ||
      cleanText(_categoryFilter).isNotEmpty ||
      cleanText(_searchController.text).isNotEmpty ||
      cleanText(_brandFilter).isNotEmpty ||
      cleanText(_finishFilter).isNotEmpty ||
      cleanText(_sizeFilter).isNotEmpty ||
      cleanText(_minPriceController.text).isNotEmpty ||
      cleanText(_maxPriceController.text).isNotEmpty ||
      _showArchived;

  void _openDesktopSearchedCategory(String category) {
    setState(() {
      _categorySearchReturnQuery = _searchController.text;
      _searchController.clear();
      _categoryFilter = category;
      _subcategoryFilter = '';
    });
  }

  void _returnToDesktopCategories() {
    _categoryFilter = '';
    _subcategoryFilter = '';
    if (_categorySearchReturnQuery.isNotEmpty) {
      _searchController.text = _categorySearchReturnQuery;
      _categorySearchReturnQuery = '';
    }
  }

  void _syncDesktopProductsBackHandler() {
    final available = _canBackWithinDesktopProducts;
    if (_registeredBackAvailable == available) return;
    _registeredBackAvailable = available;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      widget
          .onSectionBackChanged(available ? _backWithinDesktopProducts : null);
    });
  }

  void _backWithinDesktopProducts() {
    if (!mounted) return;
    setState(() {
      if (_selectedProductIds.isNotEmpty) {
        _selectedProductIds.clear();
      } else if (cleanText(_subcategoryFilter).isNotEmpty) {
        _subcategoryFilter = '';
      } else if (cleanText(_categoryFilter).isNotEmpty) {
        _returnToDesktopCategories();
      } else if (cleanText(_searchController.text).isNotEmpty) {
        _searchController.clear();
      } else if (cleanText(_brandFilter).isNotEmpty ||
          cleanText(_finishFilter).isNotEmpty ||
          cleanText(_sizeFilter).isNotEmpty ||
          cleanText(_minPriceController.text).isNotEmpty ||
          cleanText(_maxPriceController.text).isNotEmpty ||
          _showArchived) {
        _brandFilter = '';
        _finishFilter = '';
        _sizeFilter = '';
        _minPriceController.clear();
        _maxPriceController.clear();
        _showArchived = false;
      }
    });
  }

  void _toggleDesktopProduct(String productId) {
    setState(() {
      final next = toggleProductSelection(_selectedProductIds, productId);
      _selectedProductIds
        ..clear()
        ..addAll(next);
    });
  }

  void _toggleDesktopSelectionGroup(Iterable<String> productIds) {
    setState(() {
      final next = toggleSelectionGroup(_selectedProductIds, productIds);
      _selectedProductIds
        ..clear()
        ..addAll(next);
    });
  }

  Future<void> _updateDesktopSelectionVisibility(bool isPublished) async {
    if (_selectedProductIds.isEmpty || _updatingSelectionVisibility) return;
    final ids = Set<String>.from(_selectedProductIds);
    setState(() => _updatingSelectionVisibility = true);
    try {
      await widget.onSetProductsPublished(ids, isPublished);
      if (mounted) {
        _showMessage(
          context,
          isPublished
              ? '${ids.length} selected products are now live.'
              : '${ids.length} selected products are now hidden.',
        );
      }
    } finally {
      if (mounted) setState(() => _updatingSelectionVisibility = false);
    }
  }

  List<ProductDraft> get _desktopSelectedProducts => (widget.state.products
      .where((product) =>
          _selectedProductIds.contains(product.id) && !product.isComingSoon)
      .toList(growable: false)
    ..sort(_compareProductsForCatalogue));

  Future<void> _exportDesktopCatalogueImages() async {
    final products = _desktopSelectedProducts;
    if (products.isEmpty) {
      _showMessage(
          context, 'Select a live product to create a priced catalogue.');
      return;
    }
    final imageLayout = await _chooseCatalogueImageLayout(context);
    if (!mounted || imageLayout == null) return;
    final path = await _fileDialogs.pickPngSavePath(
      suggestedName: 'Crimson_Selected_Catalogue.png',
    );
    if (path == null) return;
    await _runDesktopSelectionExport(() async {
      final pages = await _multiExportService.exportImages(
        products: products,
        path: path,
        imageLayout: imageLayout,
      );
      if (mounted) {
        _showMessage(context,
            '${pages.length} catalogue image${pages.length == 1 ? '' : 's'} saved.');
      }
    });
  }

  Future<void> _exportDesktopStickerSheets() async {
    final products = _desktopSelectedProducts;
    if (products.isEmpty) {
      _showMessage(
          context, 'Select a live product to create a priced catalogue.');
      return;
    }
    final path = await _fileDialogs.pickPngSavePath(
      suggestedName: 'Crimson_Selected_60x40_Stickers.png',
    );
    if (path == null) return;
    await _runDesktopSelectionExport(() async {
      final pages = await _multiExportService.exportStickerSheetImages(
        products: products,
        path: path,
      );
      if (mounted) {
        _showMessage(context,
            '${pages.length} sticker sheet${pages.length == 1 ? '' : 's'} saved.');
      }
    });
  }

  Future<void> _exportDesktopCataloguePdf() async {
    final products = _desktopSelectedProducts;
    if (products.isEmpty) {
      _showMessage(
          context, 'Select a live product to create a priced catalogue.');
      return;
    }
    final imageLayout = await _chooseCatalogueImageLayout(context);
    if (!mounted || imageLayout == null) return;
    final path = await _fileDialogs.pickPdfSavePath(
      suggestedName: 'Crimson_Selected_Catalogue.pdf',
    );
    if (path == null) return;
    await _runDesktopSelectionExport(() async {
      await _multiExportService.exportPdf(
        products: products,
        path: path,
        imageLayout: imageLayout,
      );
      if (mounted) _showMessage(context, 'Catalogue PDF saved: $path');
    });
  }

  Future<void> _runDesktopSelectionExport(
      Future<void> Function() action) async {
    if (_exportingSelection) return;
    setState(() => _exportingSelection = true);
    try {
      await action();
    } on Object catch (error) {
      if (mounted) _showMessage(context, 'Catalogue export failed: $error');
    } finally {
      if (mounted) setState(() => _exportingSelection = false);
    }
  }

  void _handleSearchChanged() {
    _categorySearchReturnQuery = '';
    _productSearchDebounce?.cancel();
    _productSearchDebounce = Timer(const Duration(milliseconds: 75), () {
      if (mounted) setState(() {});
    });
  }

  int get _activeFilterCount => [
        _categoryFilter,
        _subcategoryFilter == '__all__' ? '' : _subcategoryFilter,
        _brandFilter,
        _finishFilter,
        _sizeFilter,
        _minPriceController.text,
        _maxPriceController.text,
      ].where((value) => cleanText(value).isNotEmpty).length;

  bool get _hasFilters => _activeFilterCount > 0;

  Future<void> _openProduct(ProductDraft product) async {
    widget.onSelectProduct(product);
    if (product.isComingSoon) {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => Dialog(
          child: SizedBox(
            width: 760,
            height: 690,
            child: _ComingSoonProductPanel(
              product: product,
              onEdit: widget.profile.canEditProducts
                  ? () {
                      Navigator.pop(dialogContext);
                      widget.onEditProduct(product);
                    }
                  : null,
              onReturnToDraft: widget.profile.canManageCatalogue
                  ? () {
                      Navigator.pop(dialogContext);
                      widget.onToggleProductPublished(product, false);
                    }
                  : null,
              onMakeLive: widget.profile.canManageCatalogue
                  ? () {
                      Navigator.pop(dialogContext);
                      widget.onToggleProductPublished(product, true);
                    }
                  : null,
            ),
          ),
        ),
      );
      return;
    }
    await showDialog<void>(
      context: context,
      barrierColor: const Color(0x99000000),
      builder: (dialogContext) => _ProductDetailDialog(
        product: product,
        profile: widget.profile,
        categoryDiscountPercent: categoryDiscountFor(
          widget.state.categories,
          product.category,
        ),
        onEditProduct: () {
          Navigator.pop(dialogContext);
          widget.onEditProduct(product);
        },
        onArchiveProduct: () {
          Navigator.pop(dialogContext);
          widget.onArchiveProduct(product);
        },
        onRestoreProduct: () {
          Navigator.pop(dialogContext);
          widget.onRestoreProduct(product);
        },
        onTogglePublished: () {
          Navigator.pop(dialogContext);
          widget.onToggleProductPublished(product, !product.isPublished);
        },
        onAddCustomerCartItem: widget.onAddCustomerCartItem,
        onOpenCart: widget.onOpenCart,
      ),
    );
  }

  Future<void> _showFilters(_ProductFilterOptions options) async {
