class _CategorySummary {
  const _CategorySummary({
    required this.name,
    required this.productCount,
    required this.subcategoryCount,
    this.imagePath = '',
  });

  final String name;
  final int productCount;
  final int subcategoryCount;
  final String imagePath;

  static List<_CategorySummary> fromProducts(
    List<ProductDraft> products, {
    List<CategoryDraft> categories = const [],
  }) {
    final categoryProducts = <String, List<ProductDraft>>{};
    final displayNames = <String, String>{};
    for (final product in products) {
      final category = cleanText(product.category);
      if (category.isEmpty) continue;
      final key = _normalUi(category);
      displayNames.putIfAbsent(key, () => category);
      categoryProducts.putIfAbsent(key, () => <ProductDraft>[]).add(product);
    }

    final summaries = [
      _CategorySummary(
        name: '',
        productCount: products.length,
        subcategoryCount: categoryProducts.length,
      ),
      for (final entry in categoryProducts.entries)
        _CategorySummary(
          name: displayNames[entry.key] ?? entry.key,
          productCount: entry.value.length,
          subcategoryCount: entry.value
              .map((product) => _normalUi(product.subcategory))
              .where((value) => value.isNotEmpty)
              .toSet()
              .length,
          imagePath: _taxonomyCoverPath(
            savedPath: _categoryDraftFor(
                  categories,
                  displayNames[entry.key] ?? entry.key,
                )?.imagePath ??
                '',
            products: entry.value,
          ),
        ),
    ];
    summaries.sort((left, right) {
      if (left.name.isEmpty) return -1;
      if (right.name.isEmpty) return 1;
      return _compareUiText(left.name, right.name);
    });
    return summaries;
  }
}

class _SubcategorySummary {
  const _SubcategorySummary({
    required this.name,
    required this.productCount,
    required this.brandCount,
    this.imagePath = '',
  });

  final String name;
  final int productCount;
  final int brandCount;
  final String imagePath;

  static List<_SubcategorySummary> fromProducts(
    List<ProductDraft> products, {
    CategoryDraft? category,
  }) {
    final grouped = <String, List<ProductDraft>>{};
    final displayNames = <String, String>{};
    for (final product in products) {
      final subcategory = cleanText(product.subcategory);
      if (subcategory.isEmpty) continue;
      final key = _normalUi(subcategory);
      displayNames.putIfAbsent(key, () => subcategory);
      grouped.putIfAbsent(key, () => <ProductDraft>[]).add(product);
    }
    final summaries = [
      for (final entry in grouped.entries)
        _SubcategorySummary(
          name: displayNames[entry.key] ?? entry.key,
          productCount: entry.value.length,
          brandCount: entry.value
              .map((product) => _normalUi(product.brand))
              .where((value) => value.isNotEmpty)
              .toSet()
              .length,
          imagePath: _taxonomyCoverPath(
            savedPath: _namedMapValue(
              category?.subcategoryImages ?? const {},
              displayNames[entry.key] ?? entry.key,
            ),
            products: entry.value,
          ),
        ),
    ]..sort((left, right) => _compareUiText(left.name, right.name));
    return summaries;
  }
}

