class _CategoryBrowseGrid extends StatelessWidget {
  const _CategoryBrowseGrid({
    required this.summaries,
    required this.products,
    required this.selectedProductIds,
    required this.showSubcategoryCount,
    required this.onSelectionChanged,
    required this.onSelected,
  });

  final List<_CategorySummary> summaries;
  final List<ProductDraft> products;
  final Set<String> selectedProductIds;
  final bool showSubcategoryCount;
  final ValueChanged<Iterable<String>>? onSelectionChanged;
  final ValueChanged<String> onSelected;

  @override
  Widget build(BuildContext context) {
    if (summaries.isEmpty) return const _Surface(child: _EmptyListMessage());
    return GridView.builder(
      padding: const EdgeInsets.only(bottom: 10),
      gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
        maxCrossAxisExtent: 340,
        childAspectRatio: 1.48,
        crossAxisSpacing: 12,
        mainAxisSpacing: 12,
      ),
      itemCount: summaries.length,
      itemBuilder: (context, index) {
        final summary = summaries[index];
        final ids = productIdsForCategory(products, summary.name);
        return _BrowseTile(
          icon: Icons.category_outlined,
          imagePath: summary.imagePath,
          title: summary.name,
          subtitle:
              '${summary.productCount} products  |  ${summary.subcategoryCount} subcategories',
          badge: summary.productCount.toString(),
          selected: isSelectionGroupComplete(selectedProductIds, ids),
