class _ProductFilterOptions {
  const _ProductFilterOptions({
    required this.categories,
    required this.subcategories,
    required this.brands,
    required this.finishes,
    required this.sizes,
    required this.subcategoriesByCategory,
  });

  final List<String> categories;
  final List<String> subcategories;
  final List<String> brands;
  final List<String> finishes;
  final List<String> sizes;
  final Map<String, List<String>> subcategoriesByCategory;

  List<String> subcategoriesFor(String category) {
    return subcategoriesByCategory[_normalUi(category)] ?? const [];
  }

  static _ProductFilterOptions fromProducts(List<ProductDraft> products) {
    final categories = <String>[];
    final subcategories = <String>[];
    final brands = <String>[];
    final finishes = <String>[];
    final sizes = <String>[];
    final subcategoriesByCategory = <String, List<String>>{};

    for (final product in products) {
      _addUnique(categories, product.category);
      _addUnique(subcategories, product.subcategory);
      _addUnique(brands, product.brand);
      final categoryKey = _normalUi(product.category);
      subcategoriesByCategory.putIfAbsent(categoryKey, () => <String>[]);
      _addUnique(subcategoriesByCategory[categoryKey]!, product.subcategory);

      for (final variation in product.variations) {
        _addUnique(finishes, variation.finish);
        _addUnique(sizes, variation.size);
      }
      for (final finish in product.finishColor.split(',')) {
        _addUnique(finishes, finish);
      }
      for (final size in product.sizeSpec.split(',')) {
        _addUnique(sizes, size);
      }
    }

    for (final values in subcategoriesByCategory.values) {
      values.sort(_compareUiText);
    }

    return _ProductFilterOptions(
      categories: _sortedUiValues(categories),
      subcategories: _sortedUiValues(subcategories),
      brands: _sortedUiValues(brands),
      finishes: _sortedUiValues(finishes),
      sizes: sortSizeLabels(sizes),
      subcategoriesByCategory: subcategoriesByCategory,
    );
  }

  static void _addUnique(List<String> values, String value) {
    final clean = cleanText(value);
    if (clean.isEmpty) return;
    if (!values.any((item) => _normalUi(item) == _normalUi(clean))) {
      values.add(clean);
    }
  }
}

String _normalUi(String value) => cleanText(value).toLowerCase();

List<ProductDraft> _activeProductsForRole(
  CatalogueState state,
  CrimsonProfile profile,
) {
  final products = profile.role == CrimsonUserRole.customer
      ? customerVisibleProducts(state)
      : state.products.where((product) => !product.isArchived).toList();
  return products..sort(_compareProductsForCatalogue);
}

int _compareProductsForCatalogue(ProductDraft left, ProductDraft right) {
  final name = _compareUiText(left.name, right.name);
  if (name != 0) return name;
  final category = _compareUiText(left.category, right.category);
  if (category != 0) return category;
  final subcategory = _compareUiText(left.subcategory, right.subcategory);
  if (subcategory != 0) return subcategory;
  return _compareUiText(left.sku, right.sku);
}

List<String> _sortedUiValues(Iterable<String> values) {
  final result = values.toList(growable: false)..sort(_compareUiText);
  return result;
}

int _compareUiText(String left, String right) {
  final leftText = cleanText(left).toLowerCase();
  final rightText = cleanText(right).toLowerCase();
  final leftParts = _naturalSortParts(leftText);
  final rightParts = _naturalSortParts(rightText);
  final limit = math.min(leftParts.length, rightParts.length);
  for (var index = 0; index < limit; index++) {
    final leftPart = leftParts[index];
    final rightPart = rightParts[index];
    final leftNumber = int.tryParse(leftPart);
    final rightNumber = int.tryParse(rightPart);
    final comparison = leftNumber != null && rightNumber != null
        ? leftNumber.compareTo(rightNumber)
        : leftPart.compareTo(rightPart);
    if (comparison != 0) return comparison;
  }
  return leftParts.length.compareTo(rightParts.length);
}

List<String> _naturalSortParts(String value) {
  return RegExp(r'\d+|\D+')
      .allMatches(value)
      .map((match) => match.group(0) ?? '')
      .toList(growable: false);
}

List<String> _uniqueDropdownValues(Iterable<String> values) {
  final result = <String>[];
  for (final value in values) {
    final clean = cleanText(value);
    if (clean.isEmpty) continue;
    if (!result.any((item) => _normalUi(item) == _normalUi(clean))) {
      result.add(clean);
    }
  }
  return _sortedUiValues(result);
}

String? _singleDropdownValue(List<String> options, String value) {
  final clean = cleanText(value);
  if (clean.isEmpty) return null;
  final matches =
      options.where((option) => _normalUi(option) == _normalUi(clean)).toList();
  return matches.length == 1 ? matches.first : null;
}

class _CategoriesScreen extends StatefulWidget {
