  final ValueChanged<List<String>> onSaveBrands;
  final Future<void> Function(CatalogueState state) onSaveState;
  final VoidCallback onOpenProducts;

  @override
  State<_CategoriesScreen> createState() => _CategoriesScreenState();
}

class _CategoriesScreenState extends State<_CategoriesScreen> {
  final _categoryController = TextEditingController();
  final _subcategoryController = TextEditingController();
  final _brandController = TextEditingController();
  late List<CategoryDraft> _categories;
  late List<String> _brands;
  String? _selectedCategory;

  @override
  void initState() {
    super.initState();
    _categories = _managedCategories();
    _brands = _managedBrands();
    _selectedCategory = _categories.isEmpty ? null : _categories.first.name;
  }

  @override
  void didUpdateWidget(covariant _CategoriesScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.state != widget.state) {
      _categories = _managedCategories();
      _brands = _managedBrands();
      if (_selectedCategory != null &&
          !_categories.any(
              (category) => _sameName(category.name, _selectedCategory!))) {
        _selectedCategory = _categories.isEmpty ? null : _categories.first.name;
      }
    }
  }

  @override
  void dispose() {
    _categoryController.dispose();
    _subcategoryController.dispose();
    _brandController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return CatalogueManagerScreen(
      state: widget.state,
      onSaveState: widget.onSaveState,
      onOpenProducts: widget.onOpenProducts,
    );
  }

  // ignore: unused_element
  Widget _buildLegacy(BuildContext context) {
    final activeProducts = widget.state.products
        .where((product) => !product.isArchived)
        .toList()
      ..sort(_compareProductsForCatalogue);
    final selectedCategory = _selectedCategory == null
        ? null
        : _categories.firstWhere(
            (category) => _sameName(category.name, _selectedCategory!),
            orElse: () => _categories.isEmpty
                ? const CategoryDraft(name: '')
                : _categories.first,
          );

    return _Surface(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Padding(
            padding: const EdgeInsets.all(20),
            child: Row(
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Categories',
                        style: Theme.of(context).textTheme.titleLarge?.copyWith(
                              fontWeight: FontWeight.w900,
                            ),
                      ),
                      Text(
                        'Manage product families, subcategories and reusable brands for clean product entry.',
                        style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                              color: _CrimsonColors.textSecondary,
                            ),
                      ),
                    ],
                  ),
                ),
                OutlinedButton.icon(
                  onPressed: widget.onOpenProducts,
                  icon: const Icon(Icons.inventory_2_outlined),
                  label: const Text('View Products'),
                ),
              ],
            ),
          ),
          Expanded(
            child: Row(
              children: [
                Expanded(
                  flex: 5,
                  child: GridView.count(
                    padding: const EdgeInsets.fromLTRB(20, 0, 10, 20),
                    crossAxisCount: 2,
                    crossAxisSpacing: 16,
                    mainAxisSpacing: 16,
                    childAspectRatio: 1.32,
                    children: [
                      for (final category in _categories)
                        _CategoryCard(
                          category: category,
                          productCount: activeProducts
                              .where((product) =>
                                  _sameName(product.category, category.name))
                              .length,
                          selected:
                              _sameName(category.name, _selectedCategory ?? ''),
                          onTap: () =>
                              setState(() => _selectedCategory = category.name),
                        ),
                    ],
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  flex: 4,
                  child: SingleChildScrollView(
                    padding: const EdgeInsets.fromLTRB(10, 0, 20, 20),
                    child: Column(
                      children: [
                        _InputCard(
                          title: 'Add Category',
                          children: [
                            Row(
                              children: [
                                Expanded(
                                  child: _AppTextField(
                                    controller: _categoryController,
                                    label: 'Category name',
                                  ),
                                ),
                                const SizedBox(width: 10),
                                Padding(
                                  padding: const EdgeInsets.only(bottom: 12),
                                  child: FilledButton.icon(
                                    onPressed: _addCategory,
                                    icon: const Icon(Icons.add_rounded),
                                    label: const Text('Add'),
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                        const SizedBox(height: 14),
                        _InputCard(
                          title: 'Subcategories',
                          children: [
                            Text(
                              selectedCategory?.name.isEmpty == false
                                  ? 'Under ${selectedCategory!.name}'
                                  : 'Select a category first.',
                              style: const TextStyle(
                                  color: _CrimsonColors.textSecondary),
                            ),
                            const SizedBox(height: 10),
                            Row(
                              children: [
                                Expanded(
                                  child: _AppTextField(
                                    controller: _subcategoryController,
                                    label: 'Subcategory name',
                                  ),
                                ),
                                const SizedBox(width: 10),
                                Padding(
                                  padding: const EdgeInsets.only(bottom: 12),
                                  child: OutlinedButton.icon(
                                    onPressed: _addSubcategory,
                                    icon:
                                        const Icon(Icons.playlist_add_rounded),
                                    label: const Text('Add'),
                                  ),
                                ),
                              ],
                            ),
                            _ManagedChipList(
                              values:
                                  selectedCategory?.subcategories ?? const [],
                              emptyText: 'No subcategories added yet.',
                            ),
                          ],
                        ),
                        const SizedBox(height: 14),
                        _InputCard(
                          title: 'Brands',
                          children: [
                            Row(
                              children: [
                                Expanded(
                                  child: _AppTextField(
                                    controller: _brandController,
                                    label: 'Brand name',
                                  ),
                                ),
                                const SizedBox(width: 10),
                                Padding(
                                  padding: const EdgeInsets.only(bottom: 12),
                                  child: FilledButton.icon(
                                    onPressed: _addBrand,
                                    icon: const Icon(Icons.sell_outlined),
                                    label: const Text('Add'),
                                  ),
                                ),
                              ],
                            ),
                            _ManagedChipList(
                              values: _brands,
                              emptyText: 'No managed brands yet.',
                            ),
                          ],
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  List<CategoryDraft> _managedCategories() {
    final result = [...widget.state.categories];
    for (final product in widget.state.products) {
      final categoryName = cleanText(product.category);
      final subcategoryName = cleanText(product.subcategory);
      if (categoryName.isEmpty) continue;
      final index = result
          .indexWhere((category) => _sameName(category.name, categoryName));
      if (index < 0) {
        result.add(CategoryDraft(
          name: categoryName,
          subcategories: subcategoryName.isEmpty ? const [] : [subcategoryName],
        ));
      } else if (subcategoryName.isNotEmpty &&
          !result[index]
              .subcategories
              .any((item) => _sameName(item, subcategoryName))) {
        result[index] = result[index].copyWith(
          subcategories: [...result[index].subcategories, subcategoryName],
        );
      }
    }
    return result;
  }

  List<String> _managedBrands() {
    final result = <String>[];
    for (final brand in widget.state.brands) {
      _addManagedString(result, brand);
    }
    for (final product in widget.state.products) {
      _addManagedString(result, product.brand);
    }
    return result;
  }

  void _addCategory() {
    final name = cleanText(_categoryController.text);
    if (name.isEmpty) return;
    if (_categories.any((category) => _sameName(category.name, name))) {
      _showMessage(context, 'Category already exists.');
      return;
    }
    setState(() {
      _categories.add(CategoryDraft(name: name));
      _selectedCategory = name;
      _categoryController.clear();
    });
    widget.onSaveCategories(_categories);
  }

  void _addSubcategory() {
    final categoryName = cleanText(_selectedCategory);
    final subcategoryName = cleanText(_subcategoryController.text);
    if (categoryName.isEmpty) {
      _showMessage(context, 'Select a category first.');
      return;
    }
    if (subcategoryName.isEmpty) return;
    final index = _categories
        .indexWhere((category) => _sameName(category.name, categoryName));
    if (index < 0) return;
    if (_categories[index]
        .subcategories
        .any((item) => _sameName(item, subcategoryName))) {
      _showMessage(context, 'Subcategory already exists.');
      return;
    }
    setState(() {
      _categories[index] = _categories[index].copyWith(
        subcategories: [..._categories[index].subcategories, subcategoryName],
      );
      _subcategoryController.clear();
    });
    widget.onSaveCategories(_categories);
  }

  void _addBrand() {
    final brand = cleanText(_brandController.text);
    if (brand.isEmpty) return;
    if (_brands.any((item) => _sameName(item, brand))) {
      _showMessage(context, 'Brand already exists.');
      return;
    }
    setState(() {
      _brands.add(brand);
      _brandController.clear();
    });
    widget.onSaveBrands(_brands);
  }

  static void _addManagedString(List<String> values, String value) {
    final clean = cleanText(value);
    if (clean.isEmpty) return;
    if (!values.any((item) => _sameName(item, clean))) {
      values.add(clean);
    }
  }
}

class _AddProductScreen extends StatefulWidget {
  const _AddProductScreen({
    super.key,
    this.editingProduct,
    required this.categories,
    required this.brands,
    required this.onSaveProduct,
    required this.onSaveCategories,
    required this.onCancel,
  });

  final ProductDraft? editingProduct;
  final List<CategoryDraft> categories;
  final List<String> brands;
  final ValueChanged<ProductDraft> onSaveProduct;
  final ValueChanged<List<CategoryDraft>> onSaveCategories;
  final VoidCallback onCancel;

  @override
  State<_AddProductScreen> createState() => _AddProductScreenState();
}

class _AddProductScreenState extends State<_AddProductScreen> {
  static const _useLegacyProductForm =
      bool.fromEnvironment('CRIMSON_LEGACY_PRODUCT_FORM');

  final _name = TextEditingController();
  final _sku = TextEditingController();
  final _brand = TextEditingController(text: 'Crimson');
  final _notes = TextEditingController();
  final _keywords = TextEditingController();
  final _fileDialogs = const WindowsFileDialogs();
  final _imageStorage = ProductImageStorage();
  final _categoryName = TextEditingController();
  final _subcategoryName = TextEditingController();
  final _finishEntry = TextEditingController();
  final _sizeEntry = TextEditingController();
  final _basePrice = TextEditingController();
  final _imagePathEntry = TextEditingController();
  final Map<String, TextEditingController> _priceControllers = {};
  late List<CategoryDraft> _categories;
  final List<String> _finishes = [];
  final List<String> _sizes = [];
  final List<String> _imagePaths = [];
  final Map<String, String> _imageFinishTags = {};
  String? _category;
  String? _subcategory;
  int _currentStep = 0;

  @override
  void initState() {
    super.initState();
    _categories = [...widget.categories];
    _prefillFromProduct(widget.editingProduct);
    _name.addListener(_refreshDraftPreview);
    _brand.addListener(_refreshDraftPreview);
    _basePrice.addListener(_refreshDraftPreview);
  }

  @override
  void dispose() {
    _name.removeListener(_refreshDraftPreview);
    _brand.removeListener(_refreshDraftPreview);
    _basePrice.removeListener(_refreshDraftPreview);
    _name.dispose();
    _sku.dispose();
    _brand.dispose();
    _notes.dispose();
    _keywords.dispose();
    _categoryName.dispose();
    _subcategoryName.dispose();
    _finishEntry.dispose();
    _sizeEntry.dispose();
    _basePrice.dispose();
    _imagePathEntry.dispose();
    for (final controller in _priceControllers.values) {
      controller.dispose();
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (_useLegacyProductForm) {
      return _buildLegacyProductForm(context);
    }
    return _buildProductBuilder(context);
  }

