  Widget _buildProductBuilder(BuildContext context) {
    final category = _selectedCategory();
    final subcategories = category?.subcategories ?? const <String>[];
    final matrixSizes = _matrixSizes;
    final isEditing = widget.editingProduct != null;
    final compact = MediaQuery.sizeOf(context).width < 720;

    return _Surface(
      child: Column(
        children: [
          _ProductBuilderSteps(
            currentStep: _currentStep,
            onStepSelected: (step) => setState(() => _currentStep = step),
          ),
          const Divider(height: 1, color: _CrimsonColors.border),
          Expanded(
            child: AnimatedSwitcher(
              duration: const Duration(milliseconds: 300),
              switchInCurve: Curves.easeOut,
              switchOutCurve: Curves.easeIn,
              child: SingleChildScrollView(
                key: ValueKey(_currentStep),
                padding: EdgeInsets.all(compact ? 14 : 24),
                child: _buildProductStep(
                  subcategories: subcategories,
                  matrixSizes: matrixSizes,
                  isEditing: isEditing,
                ),
              ),
            ),
          ),
          const Divider(height: 1, color: _CrimsonColors.border),
          _buildProductBuilderFooter(isEditing: isEditing),
        ],
      ),
    );
  }

  Widget _buildProductStep({
    required List<String> subcategories,
    required List<String> matrixSizes,
    required bool isEditing,
  }) {
    switch (_currentStep) {
      case 0:
        return _buildDetailsStep(subcategories);
      case 1:
        return _buildPhotosStep();
      case 2:
        return _buildVariationsStep(matrixSizes);
      case 3:
        return _buildReviewStep(matrixSizes, isEditing);
      default:
        return const SizedBox.shrink();
    }
  }

  Widget _buildDetailsStep(List<String> subcategories) {
    final details = _InputCard(
      title: 'Product information',
      children: [
        Text(
          'Enter the details customers will use to identify this product.',
          style: Theme.of(context).textTheme.bodySmall?.copyWith(
                color: _CrimsonColors.textSecondary,
              ),
        ),
        const SizedBox(height: 16),
        _AppTextField(controller: _name, label: 'Product name *'),
        _buildResponsivePair(
          _AppTextField(controller: _sku, label: 'SKU / Code'),
          _AppTextField(controller: _brand, label: 'Brand'),
        ),
        if (widget.brands.isNotEmpty) ...[
          const SizedBox(height: 2),
          Text(
            'Previously used brands',
            style: Theme.of(context).textTheme.labelMedium?.copyWith(
                  color: _CrimsonColors.textSecondary,
                  fontWeight: FontWeight.w700,
                ),
          ),
          const SizedBox(height: 8),
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              children: [
                for (final brand in widget.brands) ...[
                  ActionChip(
                    label: Text(brand),
                    onPressed: () => _brand.text = brand,
                    backgroundColor: Colors.white,
                    side: const BorderSide(color: _CrimsonColors.border),
                  ),
                  const SizedBox(width: 8),
                ],
              ],
            ),
          ),
          const SizedBox(height: 14),
        ],
        _buildResponsivePair(
          _buildCategoryField(),
          _buildSubcategoryField(subcategories),
        ),
        _AppTextField(
          controller: _notes,
          label: 'Notes / description',
          minLines: 3,
          maxLines: 4,
        ),
        _AppTextField(
          controller: _keywords,
          label: 'Keywords / search tags',
          minLines: 2,
          maxLines: 3,
        ),
        const SizedBox(height: 6),
        Text(
          'Separate alternate names with commas. Example: door bolt, chitkani, steel bolt.',
          style: Theme.of(context).textTheme.bodySmall?.copyWith(
                color: _CrimsonColors.textSecondary,
              ),
        ),
      ],
    );

    final side = Column(
      children: [
        _buildDraftPreviewCard(),
        const SizedBox(height: 16),
        _buildSetupSummaryCard(),
        const SizedBox(height: 16),
        Container(
          width: double.infinity,
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: const Color(0xFFFFFAF2),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: const Color(0xFFF2DFC0)),
          ),
          child: Text.rich(
            TextSpan(
              children: [
                TextSpan(
                  text: 'Categories stay controlled\n',
                  style: Theme.of(context).textTheme.titleSmall?.copyWith(
                        fontWeight: FontWeight.w800,
                      ),
                ),
                const TextSpan(
                  text:
                      'Use the + button beside Category or Subcategory to add a new option in a focused window.',
                ),
              ],
            ),
            style: Theme.of(context).textTheme.bodySmall?.copyWith(
                  color: _CrimsonColors.textSecondary,
                  height: 1.45,
                ),
          ),
        ),
      ],
    );

    return _buildResponsiveColumns(details, side, rightWidth: 420);
  }

  Widget _buildCategoryField() {
    final categories = _uniqueDropdownValues(
      _categories.map((category) => category.name).toList(),
    );
    final selectedCategory =
        _singleDropdownValue(categories, cleanText(_category));
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: _buildResponsiveActionRow(
        field: DropdownButtonFormField<String>(
          initialValue: selectedCategory,
          isExpanded: true,
          decoration: _inputDecoration('Category *'),
          items: [
            for (final item in categories)
              DropdownMenuItem(
                value: item,
                child: Text(item, overflow: TextOverflow.ellipsis),
              ),
          ],
          onChanged: (value) {
            setState(() {
              _category = value;
              final next = _selectedCategory();
              _subcategory = next?.subcategories.isNotEmpty == true
                  ? next!.subcategories.first
                  : null;
            });
          },
        ),
        action: _CompactAddButton(
          tooltip: 'Add category',
          label: 'Add category',
          onPressed: () => _openCategoryCreator(isSubcategory: false),
        ),
      ),
    );
  }

  Widget _buildSubcategoryField(List<String> subcategories) {
    final options = _uniqueDropdownValues(subcategories);
    final selectedSubcategory =
        _singleDropdownValue(options, cleanText(_subcategory));
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: _buildResponsiveActionRow(
        field: DropdownButtonFormField<String>(
          initialValue: selectedSubcategory,
          isExpanded: true,
          decoration: _inputDecoration('Subcategory *'),
          items: [
            for (final item in options)
              DropdownMenuItem(
                value: item,
                child: Text(item, overflow: TextOverflow.ellipsis),
              ),
          ],
          onChanged: (value) => setState(() => _subcategory = value),
        ),
        action: _CompactAddButton(
          tooltip: 'Add subcategory',
          label: 'Add subcategory',
          onPressed: () => _openCategoryCreator(isSubcategory: true),
        ),
      ),
    );
  }

  Widget _buildDraftPreviewCard() {
    final path = _imagePaths.isEmpty ? null : _imagePaths.first;
    return _InputCard(
      title: 'Product preview',
      children: [
        Container(
          height: 210,
          width: double.infinity,
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: _CrimsonColors.border),
          ),
          clipBehavior: Clip.antiAlias,
          child: path != null
              ? Image.file(
                  File(path),
                  fit: BoxFit.contain,
                  cacheWidth: 720,
                  errorBuilder: (_, __, ___) => const Center(
                    child: Icon(
                      Icons.inventory_2_outlined,
                      color: _CrimsonColors.crimson,
                      size: 54,
                    ),
                  ),
                )
              : const Center(
                  child: Icon(
                    Icons.inventory_2_outlined,
                    color: _CrimsonColors.crimson,
                    size: 54,
                  ),
                ),
        ),
        const SizedBox(height: 14),
        Text(
          cleanText(_name.text).isEmpty ? 'Your product name' : _name.text,
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: Theme.of(context).textTheme.titleMedium?.copyWith(
                fontWeight: FontWeight.w900,
              ),
        ),
        const SizedBox(height: 4),
        Text(
          [cleanText(_category), cleanText(_brand.text)]
              .where((value) => value.isNotEmpty)
              .join('  |  '),
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: Theme.of(context).textTheme.bodySmall?.copyWith(
                color: _CrimsonColors.textSecondary,
              ),
