  Widget _buildSetupSummaryCard() {
    final detailValues = [
      cleanText(_name.text),
      cleanText(_category),
      cleanText(_subcategory),
      cleanText(_brand.text),
    ];
    final detailCount = detailValues.where((value) => value.isNotEmpty).length;
    return _InputCard(
      title: 'Product setup',
      children: [
        _BuilderSummaryRow(
          label: 'Details',
          value: '$detailCount of 4 complete',
        ),
        _BuilderSummaryRow(
          label: 'Photos',
          value:
              _imagePaths.isEmpty ? 'Not added' : '${_imagePaths.length} added',
        ),
        _BuilderSummaryRow(
          label: 'Variations',
          value: _finishes.isEmpty
              ? (cleanText(_basePrice.text).isEmpty
                  ? 'Base price pending'
                  : 'Base price ready')
              : '${_finishes.length * _matrixSizes.length} prices',
        ),
        const _BuilderSummaryRow(label: 'Status', value: 'Draft'),
      ],
    );
  }

