String _fileNameFromPath(String path) => path.split(RegExp(r'[\\/]')).last;

CategoryDraft? _categoryDraftFor(
  List<CategoryDraft> categories,
  String name,
) {
  for (final category in categories) {
    if (_sameName(category.name, name)) return category;
  }
  return null;
}

String _namedMapValue(Map<String, String> values, String name) {
  for (final entry in values.entries) {
    if (_sameName(entry.key, name)) return cleanText(entry.value);
  }
  return '';
}

String _taxonomyCoverPath({
  required String savedPath,
  required List<ProductDraft> products,
}) {
  final saved = cleanText(savedPath);
  if (saved.isNotEmpty) return saved;
  for (final product in products) {
    final path = _primaryImagePath(product);
    if (path != null && path.isNotEmpty) return path;
  }
  return '';
}

class _TaxonomyImageFrame extends StatelessWidget {
  const _TaxonomyImageFrame({
    required this.path,
    required this.fallbackIcon,
  });

  final String path;
  final IconData fallbackIcon;

  @override
  Widget build(BuildContext context) {
    final cleanPath = cleanText(path);
    Widget fallback() => Container(
          color: Colors.white,
          alignment: Alignment.center,
          child: Icon(
            fallbackIcon,
            color: _CrimsonColors.crimson,
            size: 38,
          ),
        );
    if (cleanPath.isEmpty) return fallback();
    if (_isNetworkImagePath(cleanPath)) {
      return Container(
        color: Colors.white,
        child: CachedCatalogueImage(
          url: cleanPath,
          fit: BoxFit.contain,
          width: double.infinity,
          height: double.infinity,
          cacheWidth: 720,
          fallbackBuilder: (_) => fallback(),
        ),
      );
    }
    return Container(
      color: Colors.white,
      child: Image.file(
        File(cleanPath),
        fit: BoxFit.contain,
        width: double.infinity,
        height: double.infinity,
        cacheWidth: 720,
        errorBuilder: (_, __, ___) => fallback(),
      ),
    );
  }
}

class _ProductImageFrame extends StatelessWidget {
  const _ProductImageFrame({
    required this.product,
    this.fit = BoxFit.cover,
    this.fallbackIconSize = 48,
    this.padding = EdgeInsets.zero,
    this.cacheWidth = 480,
  });

  final ProductDraft product;
  final BoxFit fit;
  final double fallbackIconSize;
  final EdgeInsets padding;
  final int cacheWidth;

  @override
  Widget build(BuildContext context) {
    final path = _primaryImagePath(product);
    if (path == null) {
      return _ProductImageFallback(iconSize: fallbackIconSize);
    }

    if (_isNetworkImagePath(path)) {
      return Padding(
        padding: padding,
        child: CachedCatalogueImage(
          key: ValueKey(
            'product-image-${product.id}-${product.imageRevision}-$path',
          ),
          url: path,
          fit: fit,
          width: double.infinity,
          height: double.infinity,
          cacheWidth: cacheWidth,
          fallbackBuilder: (_) =>
              _ProductImageFallback(iconSize: fallbackIconSize),
        ),
      );
    }
    return Padding(
      padding: padding,
      child: Image.file(
        File(path),
        fit: fit,
        width: double.infinity,
        height: double.infinity,
        cacheWidth: cacheWidth,
        errorBuilder: (_, __, ___) =>
            _ProductImageFallback(iconSize: fallbackIconSize),
      ),
    );
  }
}

