String? _primaryImagePath(ProductDraft product) {
  final paths = [
    for (final path in [...product.imagePaths, product.imagePath])
      if (cleanText(path).isNotEmpty) cleanText(path),
  ];
  if (paths.isEmpty) return null;

  if (Platform.isAndroid) {
    for (final path in paths) {
      if (_isNetworkImagePath(path)) return path;
    }
    return paths.first;
  }

  for (final path in paths) {
    if (_isNetworkImagePath(path) || File(path).existsSync()) return path;
  }
  return paths.first;
}

bool _isNetworkImagePath(String path) {
  final value = path.trim().toLowerCase();
  return value.startsWith('https://') || value.startsWith('http://');
}

bool _sameImageReference(String left, String right) {
  final cleanLeft = cleanText(left);
  final cleanRight = cleanText(right);
  if (cleanLeft.isEmpty || cleanRight.isEmpty) return false;
  if (cleanLeft == cleanRight) return true;
  final leftName = _imageReferenceName(cleanLeft);
  final rightName = _imageReferenceName(cleanRight);
  return leftName.isNotEmpty && leftName == rightName;
}

String _imageReferenceName(String path) {
  final withoutQuery = path.split('?').first;
  final decoded = Uri.decodeComponent(withoutQuery);
  return decoded.split(RegExp(r'[\\/]')).last.trim().toLowerCase();
}

List<String> _allImagePaths(ProductDraft product) {
  final result = <String>[];
  for (final path in [...product.imagePaths, product.imagePath]) {
    final clean = cleanText(path);
    if (clean.isEmpty) continue;
    if (!result.contains(clean)) {
      result.add(clean);
    }
  }
  return result;
}

String _imageFinishTagFromMap(Map<String, String> tags, String path) {
  final direct = cleanText(tags[path]);
  if (direct.isNotEmpty) return direct;
  for (final entry in tags.entries) {
    if (_sameImageReference(entry.key, path)) {
      return cleanText(entry.value);
    }
  }
  return '';
}

String _matchingImageFinishTag(
  List<String> availableFinishes,
  String imageFinish,
) {
  final cleanFinish = cleanText(imageFinish);
  if (cleanFinish.isEmpty) return '';
  for (final finish in availableFinishes) {
    if (_sameName(finish, cleanFinish)) return finish;
  }
  return cleanFinish;
}

String _imageFinishForPath(ProductDraft product, String path) =>
    _imageFinishTagFromMap(product.imageFinishTags, path);

String _imagePathForFinish(ProductDraft product, String finish) {
  final paths = _allImagePaths(product);
  if (paths.isEmpty) return '';
  final cleanFinish = cleanText(finish);
  if (cleanFinish.isNotEmpty) {
    for (final path in paths) {
      if (_sameName(_imageFinishForPath(product, path), cleanFinish)) {
        return path;
      }
    }
  }
  return paths.first;
}

int _imageIndexForFinish(ProductDraft product, String finish) {
  final paths = _allImagePaths(product);
  final cleanFinish = cleanText(finish);
  if (cleanFinish.isEmpty) return 0;
  final index = paths.indexWhere(
    (path) => _sameName(_imageFinishForPath(product, path), cleanFinish),
  );
  return index < 0 ? 0 : index;
}

Map<String, String> _imageFinishTagsForPaths(
  List<String> paths,
  Iterable<ProductDraft> sources,
) {
  final result = <String, String>{};
  for (final path in paths) {
    for (final source in sources) {
      final finish = _imageFinishForPath(source, path);
      if (finish.isNotEmpty) {
        result[path] = finish;
        break;
      }
    }
  }
  return result;
}

String _matchingFinishSelection(
  List<_VariationAxis> axes,
  String imageFinish,
) {
  final cleanFinish = cleanText(imageFinish);
  if (cleanFinish.isEmpty) return '';
  for (final axis in axes) {
    if (axis.id != 'finish') continue;
    for (final value in axis.values) {
      if (_sameName(value, cleanFinish)) return value;
    }
  }
  return '';
}

