  }

  void _preview() {
    final parsed = parseBulkPasteProducts(_paste.text);
    final warnings =
        _repositoryDuplicateWarnings(widget.products, parsed.products);
    setState(() {
      _result = _withAdditionalImportMessages(parsed, warnings);
    });
  }

  void _clear() {
    setState(() {
      _paste.clear();
      _result = const BulkPasteImportResult(
        products: [],
        categories: [],
        errors: ['Paste rows copied from Excel to preview import.'],
      );
    });
  }

  void _loadSample() {
    _paste.text = _sampleBulkPasteRows;
    _preview();
  }

  void _commitImport() {
    if (_result.products.isEmpty) {
      _showMessage(context, 'Preview products first, then import.');
      return;
    }
    widget.onImport(_result);
    _showMessage(context, 'Importing ${_result.products.length} products...');
  }

  Future<void> _browseExcelImport() async {
    try {
      final path = await _fileDialogs.pickExcelFile();
      if (path == null) return;
      if (!mounted) return;
      setState(() => _excelImportPath.text = path);
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'Could not open file browser: $error');
    }
  }

  Future<void> _browseExcelExport() async {
    try {
      final path = await _fileDialogs.pickExcelSavePath();
      if (path == null) return;
      if (!mounted) return;
      setState(() => _excelExportPath.text = _ensureXlsxPath(path));
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'Could not open save browser: $error');
    }
  }

  Future<void> _browseLegacyImport() async {
    try {
      final path = await _fileDialogs.pickLegacyCatalogueFile();
      if (path == null) return;
      if (!mounted) return;
      setState(() => _legacyImportPath.text = path);
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'Could not open migration browser: $error');
    }
  }

  Future<void> _importExcel() async {
    final path = cleanText(_excelImportPath.text);
    if (path.isEmpty) {
      _showMessage(context, 'Enter the Excel file path first.');
      return;
    }
    try {
      final result = XlsxCatalogueIo().importProducts(path);
      final warnings =
          _repositoryDuplicateWarnings(widget.products, result.products);
      setState(() {
        _paste.text = 'Excel file preview loaded: $path';
        _result = _withAdditionalImportMessages(result, warnings);
      });
      if (result.products.isNotEmpty) {
        _showMessage(context,
            'Excel preview ready: ${result.products.length} products. Press Import Ready.');
      } else {
        _showMessage(
          context,
          result.errors.isEmpty
              ? 'No products found in this Excel file.'
              : result.errors.first,
        );
      }
    } on Object catch (error) {
      setState(() {
        _result = BulkPasteImportResult(
          products: const [],
          categories: const [],
          errors: ['Could not preview Excel file: $error'],
        );
      });
      _showMessage(context, 'Could not preview Excel file.');
    }
  }

  Future<void> _previewLegacyImport() async {
    final path = cleanText(_legacyImportPath.text);
    if (path.isEmpty) {
      _showMessage(context, 'Enter the old catalogue file path first.');
      return;
    }
    _showMessage(context, 'Reading old catalogue data...');
    final result = await const LegacyCatalogueImporter().importFromFile(path);
    if (!mounted) return;
    setState(() {
      _paste.text = 'Old catalogue preview loaded: $path';
      _result = result;
    });
    if (result.products.isNotEmpty) {
      _showMessage(
        context,
        'Migration preview ready: ${result.products.length} products. Press Import Ready.',
      );
    } else if (result.errors.isNotEmpty) {
      _showMessage(context, result.errors.first);
    }
  }

  void _exportExcel() {
    final path = _ensureXlsxPath(cleanText(_excelExportPath.text));
    if (path.isEmpty) {
      _showMessage(context, 'Enter the export Excel path first.');
      return;
    }
    try {
      XlsxCatalogueIo().exportProducts(path: path, products: widget.products);
      _excelExportPath.text = path;
      _showMessage(context, 'Excel exported: $path');
    } on Object catch (error) {
      _showMessage(context, 'Export failed: $error');
    }
  }

  String _ensureXlsxPath(String path) {
    if (path.isEmpty) return '';
    return path.toLowerCase().endsWith('.xlsx') ? path : '$path.xlsx';
  }
}

