class _EditablePriceMatrix extends StatelessWidget {
  const _EditablePriceMatrix({
    required this.finishes,
    required this.sizes,
    required this.controllerFor,
  });

  final List<String> finishes;
  final List<String> sizes;
  final TextEditingController Function(String finish, String size)
      controllerFor;

  @override
  Widget build(BuildContext context) {
    final rows =
        finishes.isEmpty && sizes.any((size) => cleanText(size).isNotEmpty)
            ? const ['']
            : finishes;
    if (rows.isEmpty) {
      return Container(
        height: 120,
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: _CrimsonColors.surfaceGrey,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: _CrimsonColors.border),
        ),
        child: const Text(
          'Use base price, or add sizes/finishes to create a matrix.',
        ),
      );
    }

    return Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: _CrimsonColors.border),
      ),
      clipBehavior: Clip.antiAlias,
      child: SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        child: DataTable(
          headingRowColor: WidgetStateProperty.all(_CrimsonColors.crimsonDark),
          headingTextStyle:
              const TextStyle(color: Colors.white, fontWeight: FontWeight.w900),
          dataRowMinHeight: 64,
          dataRowMaxHeight: 70,
          columns: [
            const DataColumn(label: Text('FINISH')),
            for (final size in sizes)
              DataColumn(
                  label: Text(size.isEmpty ? 'NO SIZE' : size.toUpperCase())),
          ],
          rows: [
            for (var index = 0; index < rows.length; index++)
              DataRow(
                color: WidgetStateProperty.all(
                  index.isEven ? Colors.white : _CrimsonColors.surfaceGrey,
                ),
                cells: [
                  DataCell(
                    Text(
                      rows[index].isEmpty ? 'PRICE' : rows[index],
                      style: const TextStyle(fontWeight: FontWeight.w900),
                    ),
                  ),
                  for (final size in sizes)
                    DataCell(
                      SizedBox(
                        width: 112,
                        child: TextField(
                          controller: controllerFor(rows[index], size),
                          decoration: const InputDecoration(
                            hintText: 'Blank/0 = N/A',
                            isDense: true,
                            border: OutlineInputBorder(),
                          ),
                          keyboardType: TextInputType.number,
                        ),
                      ),
                    ),
                ],
              ),
          ],
        ),
      ),
    );
  }
}

