  const _ExportPreviewScreen({required this.product});

  final ProductDraft? product;

  @override
  State<_ExportPreviewScreen> createState() => _ExportPreviewScreenState();
}

class _ExportPreviewScreenState extends State<_ExportPreviewScreen> {
  final _fileDialogs = const WindowsFileDialogs();
  final _exportService = const PremiumExportService();
  bool _isExporting = false;
  Future<List<Uint8List>>? _previewPages;
  int _previewPage = 0;

  @override
  void initState() {
    super.initState();
    final product = widget.product;
    if (product != null) {
      _previewPages = _exportService.renderProductSpotlightPages(product);
    }
  }

  @override
  void didUpdateWidget(covariant _ExportPreviewScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.product != widget.product) {
      _previewPage = 0;
      final product = widget.product;
      _previewPages = product == null
          ? null
          : _exportService.renderProductSpotlightPages(product);
    }
  }

  @override
  Widget build(BuildContext context) {
    final product = widget.product;
    if (product == null) return const _EmptyDetailPanel();
    return Row(
      children: [
        SizedBox(
          width: 210,
          child: _Surface(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Export Preview',
                  style: Theme.of(context).textTheme.titleMedium?.copyWith(
                        fontWeight: FontWeight.w900,
                      ),
                ),
                const SizedBox(height: 12),
                const _MiniChip(label: 'Product Spotlight', selected: true),
                const SizedBox(height: 8),
                const _MiniChip(label: 'Portrait A4'),
                const SizedBox(height: 18),
                FilledButton.icon(
                  onPressed: _isExporting ? null : () => _exportImage(product),
                  icon: const Icon(Icons.image_outlined),
                  label: const Text('Save Image'),
                ),
                const SizedBox(height: 10),
                OutlinedButton.icon(
                  onPressed: _isExporting ? null : () => _exportHtml(product),
                  icon: const Icon(Icons.picture_as_pdf_outlined),
                  label: const Text('PDF Page'),
                ),
                if (_isExporting) ...[
                  const SizedBox(height: 16),
                  const LinearProgressIndicator(),
                ],
              ],
            ),
          ),
        ),
        const SizedBox(width: 18),
        Expanded(
          child: FutureBuilder<List<Uint8List>>(
            future: _previewPages,
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                return Center(child: Text('Preview failed: ${snapshot.error}'));
              }
              if (!snapshot.hasData) {
                return const Center(child: CircularProgressIndicator());
              }
              final pages = snapshot.data!;
              if (pages.isEmpty) return const SizedBox.shrink();
              final index = _previewPage.clamp(0, pages.length - 1);
              return Column(
                children: [
                  Expanded(
                    child: Center(
                      child: AspectRatio(
                        aspectRatio: 1200 / 1697,
                        child: Image.memory(
                          pages[index],
                          fit: BoxFit.contain,
                          filterQuality: FilterQuality.high,
                          gaplessPlayback: true,
                        ),
                      ),
                    ),
                  ),
                  if (pages.length > 1)
                    Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        IconButton(
                          tooltip: 'Previous page',
                          onPressed: index == 0
                              ? null
                              : () => setState(() => _previewPage--),
                          icon: const Icon(Icons.chevron_left),
                        ),
                        Text('Page ${index + 1} of ${pages.length}'),
                        IconButton(
                          tooltip: 'Next page',
                          onPressed: index == pages.length - 1
                              ? null
                              : () => setState(() => _previewPage++),
                          icon: const Icon(Icons.chevron_right),
                        ),
                      ],
                    ),
                ],
              );
            },
          ),
        ),
      ],
    );
  }

  Future<void> _exportImage(ProductDraft product) async {
    final path = await _fileDialogs.pickPngSavePath(
      suggestedName: '${_exportSafeName(product.name)}_spotlight.png',
    );
    if (path == null) return;
    setState(() => _isExporting = true);
    try {
      await _exportService.exportProductSpotlightImage(
          product: product, path: path);
      if (!mounted) return;
      _showMessage(context, 'Product image exported: $path');
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'Image export failed: $error');
    } finally {
      if (mounted) setState(() => _isExporting = false);
    }
  }

  Future<void> _exportHtml(ProductDraft product) async {
    final path = await _fileDialogs.pickHtmlSavePath(
      suggestedName: '${_exportSafeName(product.name)}_pdf_ready.html',
    );
    if (path == null) return;
    setState(() => _isExporting = true);
    try {
      await _exportService.exportProductSpotlightHtml(
          product: product, path: path);
      if (!mounted) return;
      _showMessage(context, 'PDF-ready page exported: $path');
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'PDF-ready export failed: $error');
    } finally {
      if (mounted) setState(() => _isExporting = false);
    }
  }

  String _exportSafeName(String value) {
    final clean = cleanText(value)
        .replaceAll(RegExp(r'[^A-Za-z0-9._-]+'), '_')
        .replaceAll(RegExp(r'_+'), '_');
    return clean.isEmpty ? 'crimson_product' : clean;
  }
}

