  Widget _buildVisibilityTools(List<ProductDraft> activeProducts) {
    final query = _healthNormal(_visibilitySearch.text);
    final categories = [...widget.state.categories]
      ..sort((left, right) => _compareUiText(left.name, right.name));
    final categoryRows = categories
        .where((category) =>
            query.isEmpty ||
            _healthNormal(category.name).contains(query) ||
            category.subcategories
                .any((item) => _healthNormal(item).contains(query)))
        .toList(growable: false);
    final subcategoryRows = <({CategoryDraft category, String subcategory})>[];
    for (final category in categories) {
      final subcategories = [...category.subcategories]..sort(_compareUiText);
      for (final subcategory in subcategories) {
        if (query.isNotEmpty &&
            !_healthNormal(category.name).contains(query) &&
            !_healthNormal(subcategory).contains(query)) {
          continue;
        }
        subcategoryRows.add((category: category, subcategory: subcategory));
      }
    }
    final productRows = activeProducts
        .where((product) =>
            query.isEmpty ||
            _healthNormal(product.name).contains(query) ||
            _healthNormal(product.category).contains(query) ||
            _healthNormal(product.subcategory).contains(query) ||
            _healthNormal(product.brand).contains(query))
        .take(180)
        .toList(growable: false);
    final publishedProducts = activeProducts
        .where((product) => isProductVisibleToCustomers(widget.state, product))
        .length;

    return _Surface(
      padding: const EdgeInsets.all(20),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 48,
                height: 48,
                decoration: BoxDecoration(
                  color: _CrimsonColors.crimsonLight,
                  borderRadius: BorderRadius.circular(14),
                ),
                child: const Icon(
                  Icons.visibility_outlined,
                  color: _CrimsonColors.crimson,
                ),
              ),
              const SizedBox(width: 14),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Publishing Control',
                      style: Theme.of(context)
                          .textTheme
                          .titleLarge
                          ?.copyWith(fontWeight: FontWeight.w900),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      'Manage what customers can see without opening every product.',
