  int _categoryProductCount(List<ProductDraft> products, String category) {
    return products
        .where((product) => _sameName(product.category, category))
        .length;
  }

  int _subcategoryProductCount(
    List<ProductDraft> products,
    String category,
    String subcategory,
  ) {
    return products
        .where((product) =>
            _sameName(product.category, category) &&
            _sameName(product.subcategory, subcategory))
        .length;
  }

  Future<void> _setCategoryPublished(
    CategoryDraft category,
    bool published,
  ) async {
    final categories = widget.state.categories
        .map((item) => _sameName(item.name, category.name)
            ? item.copyWith(isPublished: published)
            : item)
        .toList(growable: false);
    await _saveVisibility(
      widget.state.copyWith(categories: categories),
      published ? 'Category published.' : 'Category hidden from customers.',
    );
  }

  Future<void> _setSubcategoryPublished(
    CategoryDraft category,
    String subcategory,
    bool published,
  ) async {
    final categories = widget.state.categories.map((item) {
      if (!_sameName(item.name, category.name)) return item;
      final next = Map<String, bool>.from(item.subcategoryPublished);
      next[subcategory] = published;
      return item.copyWith(subcategoryPublished: next);
    }).toList(growable: false);
    await _saveVisibility(
      widget.state.copyWith(categories: categories),
      published
          ? 'Subcategory products published.'
          : 'Subcategory products hidden from customers.',
    );
  }

  Future<void> _setProductPublished(
    ProductDraft product,
    bool published,
  ) async {
    final categoryName = cleanText(product.category);
    final subcategoryName = cleanText(product.subcategory);
    var categoryExists = false;
    final categories = widget.state.categories.map((category) {
      if (!_sameName(category.name, categoryName)) return category;
      categoryExists = true;
      if (!published) return category;
      final subcategories = [...category.subcategories];
      if (subcategoryName.isNotEmpty &&
          !subcategories.any((item) => _sameName(item, subcategoryName))) {
        subcategories.add(subcategoryName);
      }
      final subcategoryPublished =
          Map<String, bool>.from(category.subcategoryPublished);
      if (subcategoryName.isNotEmpty) {
        subcategoryPublished[subcategoryName] = true;
      }
      return category.copyWith(
        isPublished: true,
        subcategories: subcategories,
        subcategoryPublished: subcategoryPublished,
      );
    }).toList();
    if (published && !categoryExists && categoryName.isNotEmpty) {
      categories.add(
        CategoryDraft(
          name: categoryName,
          subcategories: subcategoryName.isEmpty ? const [] : [subcategoryName],
          isPublished: true,
          subcategoryPublished:
              subcategoryName.isEmpty ? const {} : {subcategoryName: true},
        ),
      );
    }
    final products = widget.state.products
        .map((item) => item.id == product.id
            ? item.copyWith(isPublished: published)
            : item)
        .toList(growable: false);
    await _saveVisibility(
      widget.state.copyWith(products: products, categories: categories),
      published ? 'Product published.' : 'Product hidden from customers.',
    );
  }

  Future<void> _saveVisibility(CatalogueState state, String message) async {
    setState(() => _busy = true);
    try {
      await widget.onSaveState(
        state.copyWith(updatedAt: DateTime.now().toIso8601String()),
      );
      if (mounted) _showMessage(context, message);
    } on Object catch (error) {
      if (mounted) _showMessage(context, 'Visibility update failed: $error');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  List<List<ProductDraft>> _duplicateProductGroups(
    List<ProductDraft> products,
  ) {
    final grouped = <String, List<ProductDraft>>{};
    for (final product in products) {
      final key = _healthNormal(product.name);
      if (key.isEmpty) continue;
      grouped.putIfAbsent(key, () => []).add(product);
    }
    final groups = grouped.values
        .where((items) => items.length > 1)
        .map((items) => [...items]..sort(_compareProductsForCatalogue))
        .toList()
      ..sort((left, right) => cleanText(left.first.name)
          .toLowerCase()
          .compareTo(cleanText(right.first.name).toLowerCase()));
    return groups;
  }

