  Future<void> _exportHealthProductReport({
    required String title,
    required List<ProductDraft> products,
  }) async {
    if (products.isEmpty) {
      _showMessage(context, 'No products to export.');
      return;
    }
    final now = DateTime.now();
    final date =
        '${now.year}-${now.month.toString().padLeft(2, '0')}-${now.day.toString().padLeft(2, '0')}';
    final safeTitle = title
        .toLowerCase()
        .replaceAll(RegExp(r'[^a-z0-9]+'), '_')
        .replaceAll(RegExp(r'_+'), '_')
        .replaceAll(RegExp(r'^_|_$'), '');
    final suggestedName =
        'Crimson-${safeTitle.isEmpty ? 'health_report' : safeTitle}-$date.xlsx';
    final path = await _fileDialogs.pickExcelSavePath(
      suggestedName: suggestedName,
    );
    if (path == null) return;

    setState(() => _busy = true);
    try {
      XlsxCatalogueIo().exportMissingImageReport(
        path: _ensureXlsxPath(path),
        products: [...products]..sort(_compareProductsForCatalogue),
      );
      if (!mounted) return;
      _showMessage(context, 'Excel report exported: ${_ensureXlsxPath(path)}');
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'Excel report failed: $error');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  String _ensureXlsxPath(String path) =>
      path.toLowerCase().endsWith('.xlsx') ? path : '$path.xlsx';

