  Future<bool> _confirmDuplicateMerge(
    BuildContext dialogContext, {
    required ProductDraft target,
    required List<ProductDraft> duplicates,
  }) async {
    return await showDialog<bool>(
          context: dialogContext,
          builder: (context) => AlertDialog(
            title: const Text('Merge duplicate products?'),
            content: Text(
              'Keep "${cleanText(target.name)}" and merge ${duplicates.length} duplicate record${duplicates.length == 1 ? '' : 's'} into it. Unique images and variation rows will be retained.',
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context, false),
                child: const Text('Cancel'),
              ),
              FilledButton.icon(
                onPressed: () => Navigator.pop(context, true),
