        ) ??
        false;
  }

  Future<void> _mergeDuplicateProducts({
    required ProductDraft target,
    required List<ProductDraft> duplicates,
  }) async {
    if (duplicates.isEmpty) return;
    final duplicateIds = duplicates.map((product) => product.id).toSet();
    final merged = _mergedHealthProduct(target, duplicates);
    final products = <ProductDraft>[
      for (final product in widget.state.products)
        if (product.id == target.id)
          merged
        else if (!duplicateIds.contains(product.id))
          product,
    ];
    await widget.onSaveState(widget.state.copyWith(products: products));
    if (!mounted) return;
    _showMessage(
      context,
      'Merged ${duplicates.length} duplicate product${duplicates.length == 1 ? '' : 's'} into ${cleanText(target.name)}.',
    );
  }

  ProductDraft _mergedHealthProduct(
    ProductDraft target,
    List<ProductDraft> duplicates,
  ) {
    final allProducts = [target, ...duplicates];
    final imagePaths = <String>[];
    final variations = <VariationDraft>[];
    var imageRevision = target.imageRevision;

    void addImage(String value) {
      final clean = value.trim();
      if (clean.isEmpty) return;
      if (!imagePaths
          .any((path) => _healthNormal(path) == _healthNormal(clean))) {
        imagePaths.add(clean);
      }
    }

    void addVariation(VariationDraft value) {
      if (!variations.any((item) => _sameHealthVariation(item, value))) {
        variations.add(value);
      }
    }

    for (final product in allProducts) {
      addImage(product.imagePath);
      for (final imagePath in product.imagePaths) {
        addImage(imagePath);
      }
      for (final variation in product.variations) {
        addVariation(variation);
      }
      if (product.imageRevision > imageRevision) {
        imageRevision = product.imageRevision;
      }
    }

    String fill(String primary, String fallback) =>
        primary.trim().isNotEmpty ? primary : fallback;

    return target.copyWith(
      sku: fill(target.sku, duplicates.first.sku),
      category: fill(target.category, duplicates.first.category),
      subcategory: fill(target.subcategory, duplicates.first.subcategory),
      brand: fill(target.brand, duplicates.first.brand),
      sizeSpec: fill(target.sizeSpec, duplicates.first.sizeSpec),
      finishColor: fill(target.finishColor, duplicates.first.finishColor),
      sellingPrice: fill(target.sellingPrice, duplicates.first.sellingPrice),
      imagePath: imagePaths.isEmpty ? target.imagePath : imagePaths.first,
      imagePaths: imagePaths,
      imageFinishTags: _imageFinishTagsForPaths(imagePaths, allProducts),
      imageRevision: imageRevision,
      variations: variations,
      notes: _mergedHealthNotes(target, duplicates),
    );
  }

  String _mergedHealthNotes(
      ProductDraft target, List<ProductDraft> duplicates) {
    final notes = <String>[];
    void addNote(String value) {
      final clean = value.trim();
      if (clean.isEmpty) return;
      if (!notes.any((note) => _healthNormal(note) == _healthNormal(clean))) {
        notes.add(clean);
      }
    }

    addNote(target.notes);
    for (final product in duplicates) {
      addNote(product.notes);
    }
    return notes.join('\n');
  }

  bool _sameHealthVariation(VariationDraft left, VariationDraft right) {
    return _healthNormal(left.size) == _healthNormal(right.size) &&
        _healthNormal(left.finish) == _healthNormal(right.finish) &&
        _healthNormal(left.sku) == _healthNormal(right.sku) &&
        _healthNormal(left.notes) == _healthNormal(right.notes);
  }

  bool _hasCatalogueContent() {
    return widget.state.products.isNotEmpty ||
        widget.state.categories.isNotEmpty ||
        widget.state.brands.isNotEmpty ||
        widget.state.brandImages.isNotEmpty;
  }

  String _resetBackupPath() {
    final root = File(widget.storePath).parent;
    final now = DateTime.now();
    final stamp = [
      now.year.toString().padLeft(4, '0'),
      now.month.toString().padLeft(2, '0'),
      now.day.toString().padLeft(2, '0'),
      '-',
      now.hour.toString().padLeft(2, '0'),
      now.minute.toString().padLeft(2, '0'),
      now.second.toString().padLeft(2, '0'),
    ].join();
    return '${root.path}${Platform.pathSeparator}backups${Platform.pathSeparator}Crimson-Catalogue-Before-Reset-$stamp.json';
  }

  Future<_ResetCredentials?> _collectResetCredentials() async {
    final email = TextEditingController();
    final password = TextEditingController();
    final phrase = TextEditingController();
    var obscure = true;
    var error = '';
    const requiredPhrase = 'RESET CRIMSON CATALOGUE';

    try {
      return await showDialog<_ResetCredentials>(
        context: context,
        barrierDismissible: false,
        builder: (context) => StatefulBuilder(
          builder: (context, setDialogState) => AlertDialog(
            title: const Text('Fresh catalogue reset'),
            content: SizedBox(
              width: 520,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'This will remove only catalogue data: products, variations, categories, subcategories, brands and their image links. Login, roles, banners, rules and app settings stay safe.',
                    ),
                    const SizedBox(height: 12),
                    const Text(
                      'A backup will be created automatically before anything is removed.',
                      style: TextStyle(fontWeight: FontWeight.w800),
                    ),
                    const SizedBox(height: 18),
                    TextField(
                      controller: email,
                      keyboardType: TextInputType.emailAddress,
                      decoration: _inputDecoration('Admin email'),
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      controller: password,
                      obscureText: obscure,
                      decoration: _inputDecoration('Admin password').copyWith(
                        suffixIcon: IconButton(
                          onPressed: () =>
                              setDialogState(() => obscure = !obscure),
                          icon: Icon(obscure
                              ? Icons.visibility_outlined
                              : Icons.visibility_off_outlined),
                        ),
                      ),
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      controller: phrase,
                      decoration: _inputDecoration(
                        'Type $requiredPhrase to confirm',
                      ),
                    ),
                    if (error.isNotEmpty) ...[
                      const SizedBox(height: 10),
                      Text(
                        error,
                        style: const TextStyle(
                          color: Color(0xFFB91C1C),
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context),
                child: const Text('Cancel'),
              ),
              FilledButton.icon(
                style: FilledButton.styleFrom(
                  backgroundColor: const Color(0xFFB91C1C),
                ),
                onPressed: () {
                  if (email.text.trim().isEmpty ||
                      password.text.trim().isEmpty) {
                    setDialogState(
                        () => error = 'Enter the admin email and password.');
                    return;
                  }
                  if (phrase.text.trim().toUpperCase() != requiredPhrase) {
                    setDialogState(
                        () => error = 'Type the confirmation phrase exactly.');
                    return;
                  }
                  Navigator.pop(
                    context,
                    _ResetCredentials(
                      email: email.text.trim(),
                      password: password.text,
                    ),
                  );
                },
                icon: const Icon(Icons.lock_reset_rounded),
                label: const Text('Create backup and reset'),
              ),
            ],
          ),
        ),
      );
    } finally {
      email.dispose();
      password.dispose();
      phrase.dispose();
    }
  }

  Future<void> _startFreshCatalogueReset() async {
    if (!_hasCatalogueContent()) {
      _showMessage(context, 'Catalogue is already empty.');
      return;
    }
    final credentials = await _collectResetCredentials();
    if (credentials == null) return;

    setState(() => _busy = true);
    try {
      await widget.onVerifyAdminReset(
        email: credentials.email,
        password: credentials.password,
      );
      final backupPath = _resetBackupPath();
      await _backupService.exportBackup(state: widget.state, path: backupPath);
      final resetTime = DateTime.now().toUtc();
      final cleanState = CatalogueState(
        bannerImagePaths: widget.state.bannerImagePaths,
        resetGeneration: 'reset-${resetTime.microsecondsSinceEpoch}',
        updatedAt: resetTime.toIso8601String(),
      );
      await widget.onResetCatalogueData(cleanState);
      if (!mounted) return;
      _showMessage(
        context,
        'Fresh catalogue started. Backup saved: $backupPath',
      );
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'Fresh reset stopped: $error');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _createBackup() async {
    final now = DateTime.now();
    final date =
        '${now.year}-${now.month.toString().padLeft(2, '0')}-${now.day.toString().padLeft(2, '0')}';
    final path = await _fileDialogs.pickCatalogueBackupSavePath(
      suggestedName: 'Crimson-Catalogue-Backup-$date.json',
    );
    if (path == null) return;

    setState(() => _busy = true);
    try {
      await _backupService.exportBackup(state: widget.state, path: path);
      if (!mounted) return;
      _showMessage(context, 'Catalogue backup created: $path');
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'Backup failed: $error');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _restoreBackup() async {
    final path = await _fileDialogs.pickCatalogueBackupFile();
    if (path == null) return;

    setState(() => _busy = true);
    try {
      final restored = await _backupService.readBackup(path);
      if (!mounted) return;
      final variationCount = restored.products.fold<int>(
        0,
        (sum, product) => sum + product.variations.length,
      );
      final confirmed = await showDialog<bool>(
            context: context,
            builder: (context) => AlertDialog(
              title: const Text('Restore this catalogue backup?'),
              content: Text(
                'The backup contains ${restored.products.length} products, '
                '$variationCount variations and '
                '${restored.categories.length} categories.\n\n'
                'Your current local catalogue will be replaced. Create a '
                'fresh backup first if you may need to return to it.',
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(context, false),
                  child: const Text('Cancel'),
                ),
                FilledButton(
                  onPressed: () => Navigator.pop(context, true),
                  child: const Text('Restore'),
                ),
              ],
            ),
          ) ??
          false;
      if (!confirmed) return;
      await widget.onRestoreBackup(restored);
      if (!mounted) return;
      _showMessage(context, 'Catalogue restored successfully.');
    } on Object catch (error) {
      if (!mounted) return;
      _showMessage(context, 'Restore failed: $error');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }
}

