String _healthProductSubtitle(ProductDraft product) {
  final parts = [
    cleanText(product.category),
    cleanText(product.subcategory),
    cleanText(product.brand),
  ].where((item) => item.isNotEmpty).toList();
  return parts.isEmpty ? 'No classification added' : parts.join(' / ');
}

String _healthNormal(String value) =>
    cleanText(value).trim().toLowerCase().replaceAll(RegExp(r'\s+'), ' ');

