class _DialogProductImage extends StatelessWidget {
  const _DialogProductImage({required this.path});

  final String? path;

  @override
  Widget build(BuildContext context) {
    final cleanPath = cleanText(path);
    if (cleanPath.isEmpty) {
      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          const Icon(
            Icons.add_photo_alternate_outlined,
            size: 70,
            color: _CrimsonColors.crimsonDark,
          ),
          const SizedBox(height: 12),
          Text(
            'Product photo not added',
            style: Theme.of(context)
                .textTheme
                .titleMedium
                ?.copyWith(fontWeight: FontWeight.w900),
          ),
        ],
      );
    }
    if (_isNetworkImagePath(cleanPath)) {
      return CachedCatalogueImage(
        url: cleanPath,
        fit: BoxFit.contain,
        width: double.infinity,
        height: double.infinity,
        cacheWidth: 1200,
        fallbackBuilder: (_) => const _ProductImageFallback(iconSize: 70),
      );
    }
    return Image.file(
      File(cleanPath),
      fit: BoxFit.contain,
      width: double.infinity,
      height: double.infinity,
      cacheWidth: 1200,
      errorBuilder: (_, __, ___) => const _ProductImageFallback(iconSize: 70),
    );
  }
}

