class _VariantChoiceChip extends StatelessWidget {
  const _VariantChoiceChip({
    required this.label,
    required this.selected,
    required this.onSelected,
    this.stockStatus,
  });

  final String label;
  final bool selected;
  final VoidCallback onSelected;
  final StockAvailability? stockStatus;

  @override
  Widget build(BuildContext context) {
    return ChoiceChip(
      label: stockStatus == null
          ? Text(label == '-' ? 'Not specified' : label)
          : Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(label == '-' ? 'Not specified' : label),
                const SizedBox(height: 2),
                Text(
                  _stockStatusLabel(stockStatus!),
                  style: TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w700,
                    color: selected ? Colors.white : _stockStatusColor(stockStatus!),
                  ),
                ),
              ],
            ),
      selected: selected,
      onSelected: (_) => onSelected(),
      selectedColor: _CrimsonColors.crimson,
      labelStyle: TextStyle(
        color: selected ? Colors.white : _CrimsonColors.textPrimary,
        fontWeight: FontWeight.w800,
      ),
      side: BorderSide(
        color: selected ? _CrimsonColors.crimson : _CrimsonColors.border,
      ),
    );
  }
}

String _stockStatusLabel(StockAvailability status) => switch (status) {
      StockAvailability.inStock => 'In stock',
      StockAvailability.lowStock => 'Low stock',
      StockAvailability.outOfStock => 'Out of stock',
      StockAvailability.notRecorded => 'Stock not recorded',
    };

Color _stockStatusColor(StockAvailability status) => switch (status) {
      StockAvailability.inStock => const Color(0xFF17764A),
      StockAvailability.lowStock => const Color(0xFFB96800),
      StockAvailability.outOfStock => const Color(0xFFC62D3B),
      StockAvailability.notRecorded => _CrimsonColors.textSecondary,
    };

