class _ProductPublishChip extends StatelessWidget {
  const _ProductPublishChip({
    required this.published,
    required this.onPressed,
    this.comingSoon = false,
    this.compact = false,
  });

  final bool published;
  final bool comingSoon;
  final VoidCallback onPressed;
  final bool compact;

  @override
  Widget build(BuildContext context) {
    final color = published ? _CrimsonColors.success : _CrimsonColors.warning;
    final background =
        published ? const Color(0xFFEAFBF0) : const Color(0xFFFFF7ED);
    return Tooltip(
      message: published
          ? 'Hide product from customers'
          : comingSoon
              ? 'Make live when details and prices are ready'
              : 'Publish product',
      child: Material(
        color: background,
        borderRadius: BorderRadius.circular(999),
        child: InkWell(
          borderRadius: BorderRadius.circular(999),
          onTap: onPressed,
          child: Container(
            padding: EdgeInsets.symmetric(
              horizontal: compact ? 8 : 9,
              vertical: compact ? 5 : 6,
            ),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(999),
              border: Border.all(color: color.withValues(alpha: 0.28)),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(
                  published
                      ? Icons.visibility_rounded
                      : Icons.visibility_off_rounded,
                  size: compact ? 13 : 14,
                  color: color,
                ),
                const SizedBox(width: 4),
                Text(
                  published
                      ? 'Live'
                      : comingSoon
                          ? 'Coming Soon'
                          : 'Hidden',
                  style: TextStyle(
                    color: color,
                    fontSize: compact ? 10 : 11,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _SelectionTickBox extends StatelessWidget {
  const _SelectionTickBox({
    required this.selected,
    required this.onPressed,
  });

  final bool selected;
  final VoidCallback onPressed;

  @override
  Widget build(BuildContext context) {
    return Tooltip(
      message: selected
          ? 'Remove from catalogue export'
          : 'Select for catalogue export',
      child: Material(
        color: Colors.white.withValues(alpha: 0.96),
        elevation: 2,
        shadowColor: Colors.black26,
        borderRadius: BorderRadius.circular(7),
        child: SizedBox(
          width: 30,
          height: 30,
          child: Transform.scale(
            scale: 0.86,
            child: Checkbox(
              value: selected,
              onChanged: (_) => onPressed(),
              activeColor: _CrimsonColors.crimson,
              checkColor: Colors.white,
              side: const BorderSide(
                color: _CrimsonColors.textSecondary,
                width: 1.5,
              ),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(4),
              ),
              materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
              visualDensity: VisualDensity.compact,
            ),
          ),
        ),
      ),
    );
  }
}

class _ProductGridCard extends StatelessWidget {
  const _ProductGridCard({
    required this.product,
    required this.selected,
    required this.onTap,
    this.showSubcategory = true,
    this.onSelectionToggle,
    this.onTogglePublished,
    this.stockQuantity,
  });

  final ProductDraft product;
  final bool selected;
  final bool showSubcategory;
  final VoidCallback onTap;
  final VoidCallback? onSelectionToggle;
  final VoidCallback? onTogglePublished;
  final double? stockQuantity;

  @override
  Widget build(BuildContext context) {
    return Material(
      color: Colors.white,
      borderRadius: BorderRadius.circular(14),
      child: InkWell(
        borderRadius: BorderRadius.circular(14),
        onTap: onTap,
        onLongPress: onSelectionToggle,
        child: Container(
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(14),
            border: Border.all(
              color: selected ? _CrimsonColors.crimson : _CrimsonColors.border,
            ),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: ClipRRect(
                  borderRadius:
                      const BorderRadius.vertical(top: Radius.circular(14)),
                  child: Stack(
                    children: [
                      Positioned.fill(
                        child: Container(
                          color: Colors.white,
                          child: _ProductImageFrame(
                            product: product,
                            fit: BoxFit.contain,
                            fallbackIconSize: 42,
                            padding: const EdgeInsets.all(8),
                          ),
                        ),
                      ),
                      if (onSelectionToggle != null)
                        Positioned(
                          top: 7,
                          left: 7,
                          child: _SelectionTickBox(
                            selected: selected,
                            onPressed: onSelectionToggle!,
                          ),
                        ),
                      if (onTogglePublished != null)
                        Positioned(
                          top: 7,
                          right: 7,
                          child: _ProductPublishChip(
                            published: product.isPublished,
                            comingSoon: product.isComingSoon,
                            onPressed: onTogglePublished!,
                          ),
                        ),
                    ],
                  ),
                ),
              ),
              Container(
                width: double.infinity,
                color: Colors.white,
                padding: const EdgeInsets.fromLTRB(10, 8, 10, 10),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      product.name,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: Theme.of(context).textTheme.titleSmall?.copyWith(
                            fontWeight: FontWeight.w900,
                          ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      [
                        product.category,
                        if (showSubcategory) product.subcategory,
                      ]
                          .where((value) => cleanText(value).isNotEmpty)
                          .join(' / '),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: Theme.of(context).textTheme.bodySmall?.copyWith(
                            color: _CrimsonColors.textSecondary,
                          ),
                    ),
                    const SizedBox(height: 6),
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            _priceRange(product),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: Theme.of(context)
                                .textTheme
                                .bodyMedium
                                ?.copyWith(
                                  color: _CrimsonColors.crimson,
                                  fontWeight: FontWeight.w900,
                                ),
                          ),
                        ),
                        const SizedBox(width: 8),
                        Text(
                          '${product.variations.length} variants',
                          style:
                              Theme.of(context).textTheme.bodySmall?.copyWith(
                                    color: _CrimsonColors.textSecondary,
                                    fontWeight: FontWeight.w700,
                                  ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

