class _ManagedChipList extends StatelessWidget {
  const _ManagedChipList({
    required this.values,
    required this.emptyText,
  });

  final List<String> values;
  final String emptyText;

  @override
  Widget build(BuildContext context) {
    if (values.isEmpty) {
      return Container(
        width: double.infinity,
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: _CrimsonColors.surfaceGrey,
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: _CrimsonColors.border),
        ),
        child: Text(
          emptyText,
          style: const TextStyle(color: _CrimsonColors.textSecondary),
        ),
      );
    }
    return Wrap(
      spacing: 8,
      runSpacing: 8,
      children: [
        for (final value in values)
          Chip(
            label: Text(value),
            backgroundColor: Colors.white,
            side: const BorderSide(color: _CrimsonColors.border),
            labelStyle: const TextStyle(
              color: _CrimsonColors.textPrimary,
              fontWeight: FontWeight.w700,
            ),
          ),
      ],
    );
  }
}

class _SpecGrid extends StatelessWidget {
  const _SpecGrid({required this.product, this.showSubcategory = true});

  final ProductDraft product;
  final bool showSubcategory;

  @override
  Widget build(BuildContext context) {
    final specs = [
      ('Category', product.category, Icons.folder_outlined),
      if (showSubcategory)
        ('Subcategory', product.subcategory, Icons.folder_copy_outlined),
      ('Brand', product.brand, Icons.sell_outlined),
      (
        'Variants',
        product.variations.length.toString(),
        Icons.view_module_outlined
      ),
    ];
    return GridView.count(
      shrinkWrap: true,
      physics: const NeverScrollableScrollPhysics(),
      crossAxisCount: 2,
      crossAxisSpacing: 10,
      mainAxisSpacing: 10,
      childAspectRatio: 2.7,
      children: [
        for (final spec in specs)
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: _CrimsonColors.border),
            ),
            child: Row(
              children: [
                Icon(spec.$3, color: _CrimsonColors.crimson),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Text(
                        spec.$1,
                        style: Theme.of(context).textTheme.bodySmall?.copyWith(
                              color: _CrimsonColors.textSecondary,
                            ),
                      ),
                      Text(
                        spec.$2.isEmpty ? '-' : spec.$2,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                              fontWeight: FontWeight.w800,
                            ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
      ],
    );
  }
}

class _PriceMatrixTable extends StatelessWidget {
  const _PriceMatrixTable({required this.matrix});

  final VariationMatrix matrix;

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: _CrimsonColors.border),
      ),
      clipBehavior: Clip.antiAlias,
      child: SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        child: DataTable(
          headingRowColor: WidgetStateProperty.all(_CrimsonColors.crimsonDark),
          headingTextStyle:
              const TextStyle(color: Colors.white, fontWeight: FontWeight.w900),
          dataRowMinHeight: 46,
          dataRowMaxHeight: 52,
          columns: [
            const DataColumn(label: Text('FINISH')),
            for (final size in matrix.sizes) DataColumn(label: Text(size)),
          ],
          rows: [
            for (var index = 0; index < matrix.finishes.length; index++)
              DataRow(
                color: WidgetStateProperty.all(
                  index.isEven ? Colors.white : _CrimsonColors.surfaceGrey,
                ),
                cells: [
                  DataCell(Text(matrix.finishes[index],
                      style: const TextStyle(fontWeight: FontWeight.w800))),
                  for (final size in matrix.sizes)
                    DataCell(Text(_displayPrice(matrix
                        .prices[matrix.key(matrix.finishes[index], size)]))),
                ],
              ),
          ],
        ),
      ),
    );
  }
}

