class _CloudStatusChip extends StatelessWidget {
  const _CloudStatusChip({
    required this.status,
    this.compact = false,
  });

  final CloudSyncStatus status;
  final bool compact;

  @override
  Widget build(BuildContext context) {
    final color = status.isWarning
        ? const Color(0xFFF59E0B)
        : status.isWorking
            ? _CrimsonColors.crimson
            : const Color(0xFF16A34A);
    final background = status.isWarning
        ? const Color(0xFFFFF7ED)
        : status.isWorking
            ? _CrimsonColors.crimsonLight
            : const Color(0xFFEFFBF3);
    return Tooltip(
      message: status.label,
      child: Container(
        padding: EdgeInsets.symmetric(
          horizontal: compact ? 9 : 12,
          vertical: compact ? 7 : 9,
        ),
        decoration: BoxDecoration(
          color: background,
          borderRadius: BorderRadius.circular(999),
          border: Border.all(color: color.withValues(alpha: 0.22)),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (status.isWorking)
              SizedBox(
                width: compact ? 12 : 14,
                height: compact ? 12 : 14,
                child: CircularProgressIndicator(
                  strokeWidth: 2,
                  valueColor: AlwaysStoppedAnimation<Color>(color),
                ),
              )
            else
              Icon(
                status.isWarning
                    ? Icons.cloud_off_outlined
                    : Icons.check_circle_outline_rounded,
                size: compact ? 14 : 16,
                color: color,
              ),
            if (!compact) ...[
              const SizedBox(width: 7),
              Text(
                status.label,
                style: TextStyle(
                  color: color,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }
}

