class _SmartSearchChipRow extends StatelessWidget {
  const _SmartSearchChipRow({required this.query});

  final String query;

  @override
  Widget build(BuildContext context) {
    final chips = smartSearchChips(query);
    if (chips.isEmpty) return const SizedBox.shrink();
    return Padding(
      padding: const EdgeInsets.only(top: 8),
      child: Wrap(
        spacing: 6,
        runSpacing: 6,
        children: [
          for (final chip in chips.take(8))
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
              decoration: BoxDecoration(
                color: _CrimsonColors.crimsonLight,
                borderRadius: BorderRadius.circular(999),
                border: Border.all(color: const Color(0xFFF4C7D0)),
              ),
              child: Text(
                chip,
                style: const TextStyle(
                  color: _CrimsonColors.crimsonDark,
                  fontWeight: FontWeight.w800,
                  fontSize: 11,
                ),
              ),
            ),
        ],
      ),
    );
  }
}

