Future<CatalogueImageLayout?> _chooseCatalogueImageLayout(
  BuildContext context,
) async {
  var selected = CatalogueImageLayout.classic;
  return showDialog<CatalogueImageLayout>(
    context: context,
    builder: (dialogContext) => StatefulBuilder(
      builder: (context, setDialogState) => AlertDialog(
        title: const Text('Catalogue image layout'),
        content: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 520),
          child: RadioGroup<CatalogueImageLayout>(
            groupValue: selected,
            onChanged: (value) {
              if (value != null) {
                setDialogState(() => selected = value);
              }
            },
            child: const Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                RadioListTile<CatalogueImageLayout>(
                  value: CatalogueImageLayout.classic,
                  title: Text('Classic catalogue (current)'),
                  subtitle: Text(
                    'One large image per product. Keeps the existing template unchanged.',
                  ),
                ),
                RadioListTile<CatalogueImageLayout>(
                  value: CatalogueImageLayout.multiImage,
                  title: Text('Multi-image catalogue'),
                  subtitle: Text(
                    'One main image with up to three colour-tagged thumbnails. Still three products per page.',
                  ),
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(),
            child: const Text('Cancel'),
          ),
          FilledButton.icon(
            onPressed: () => Navigator.of(dialogContext).pop(selected),
            icon: const Icon(Icons.file_download_outlined),
            label: const Text('Continue'),
          ),
        ],
      ),
    ),
  );
}

void _showMessage(BuildContext context, String message) {
  final messenger = ScaffoldMessenger.of(context);
  messenger.hideCurrentSnackBar();
  messenger.showSnackBar(
    SnackBar(
      duration: const Duration(seconds: 3),
      content: Text(message),
    ),
  );
}

Future<bool> _confirmArchive(BuildContext context, ProductDraft product) async {
  final result = await showDialog<bool>(
    context: context,
    builder: (context) {
      return AlertDialog(
        title: const Text('Archive product?'),
        content: Text(
          '${product.name} will be hidden from the active catalogue. You can restore it from the Archived view.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(false),
            child: const Text('Cancel'),
          ),
          FilledButton.icon(
            onPressed: () => Navigator.of(context).pop(true),
            icon: const Icon(Icons.archive_outlined),
            label: const Text('Archive'),
          ),
        ],
      );
    },
  );
  return result == true;
}

String _displayPrice(String? value) {
  if (value == null || value.trim().isEmpty) return '-';
  if (value == '0') return '0';
  return 'Rs. $value';
}

String _discountedPriceDisplay(
  String original,
  double basePrice,
  double discountPercent,
) {
  if (basePrice <= 0 || discountPercent <= 0) return original;
  final percent = discountPercent.clamp(0, 100);
  return _displayPrice(
    formatCompactPrice(basePrice * (1 - percent / 100)),
  );
}

String _priceRange(ProductDraft product) {
  if (product.isComingSoon) return 'Coming Soon';
  final prices = product.variations
      .map((variation) => double.tryParse(cleanText(variation.price)) ?? 0)
      .where((price) => price > 0)
      .toList()
    ..sort();
  if (prices.isEmpty) return 'Price pending';
  final low = formatCompactPrice(prices.first);
  final high = formatCompactPrice(prices.last);
  return low == high ? 'Rs. $low' : 'Rs. $low - $high';
}

bool _comingSoonProductIsReady(ProductDraft product) {
  final name = product.name.trim();
  if (name.isEmpty || RegExp(r'^Coming Soon [A-Z0-9-]{1,8}$').hasMatch(name)) {
    return false;
  }
  if (product.category.trim().isEmpty ||
      product.subcategory.trim().isEmpty ||
      _allImagePaths(product).isEmpty) {
    return false;
  }
  return product.variations
      .any((variation) => (double.tryParse(variation.price.trim()) ?? 0) > 0);
}

bool _shouldShowVariantControls(ProductDraft product, VariationMatrix matrix) {
  return _variationSelectorAxes(product).isNotEmpty;
}

bool _shouldShowPriceMatrix(ProductDraft product, VariationMatrix matrix) {
  return product.variations.length > 1 &&
      matrix.finishes.isNotEmpty &&
      matrix.sizes.isNotEmpty;
}

String _simpleProductPrice(ProductDraft product) {
  if (product.isComingSoon) return 'Coming Soon';
  if (product.variations.isNotEmpty) {
    return _displayPrice(formatCompactPrice(product.variations.first.price));
  }
  final price = cleanText(product.sellingPrice);
  if (price.isEmpty || double.tryParse(price) == 0) return 'Price pending';
  return _displayPrice(formatCompactPrice(price));
}

String _simpleProductVariationLabel(ProductDraft product) {
  if (product.variations.isEmpty) return 'Base price';
  return _variationLabelForDraft(product.variations.first);
}

class _VariationAxis {
  const _VariationAxis({
    required this.id,
    required this.label,
    required this.values,
    required this.valueOf,
  });

  final String id;
  final String label;
  final List<String> values;
  final String Function(VariationDraft variation) valueOf;
}

List<_VariationAxis> _variationSelectorAxes(ProductDraft product) {
  if (product.variations.length <= 1) return const [];
  final hasBreadthLengthHeight = product.variations.any((variation) =>
      cleanText(variation.breadth).isNotEmpty ||
      cleanText(variation.length).isNotEmpty ||
      cleanText(variation.height).isNotEmpty);
  final candidates = <_VariationAxis>[
    if (hasBreadthLengthHeight) ...[
      _buildVariationAxis('breadth', 'Breadth', product.variations,
          (variation) => variation.breadth),
      _buildVariationAxis('length', 'Length', product.variations,
          (variation) => variation.length),
      _buildVariationAxis('height', 'Height', product.variations,
          (variation) => variation.height),
    ],
    _buildVariationAxis('thickness', 'Thickness', product.variations,
        (variation) => variation.thickness),
    _buildVariationAxis('finish', 'Finish', product.variations,
        (variation) => variation.finish),
    if (!hasBreadthLengthHeight)
      _buildVariationAxis(
          'size', 'Size', product.variations, (variation) => variation.size),
  ];
  return candidates.where((axis) {
    if (hasBreadthLengthHeight &&
        (axis.id == 'breadth' || axis.id == 'length' || axis.id == 'height')) {
      return axis.values.isNotEmpty;
    }
    return axis.values.length > 1;
  }).toList(growable: false);
}

_VariationAxis _buildVariationAxis(
  String id,
  String label,
  List<VariationDraft> variations,
  String Function(VariationDraft variation) valueOf,
) {
  final values = <String>[];
  for (final variation in variations) {
    final value = cleanText(valueOf(variation));
    if (value.isEmpty || value == '-') continue;
    if (!values
        .any((item) => cleanText(item).toLowerCase() == value.toLowerCase())) {
      values.add(value);
    }
  }
  return _VariationAxis(
    id: id,
    label: label,
    values: values,
    valueOf: valueOf,
  );
}

List<Widget> _variationSelectorWidgets({
  required ProductDraft product,
  required List<_VariationAxis> axes,
  required Map<String, String> selectedValues,
  required void Function(_VariationAxis axis, String value) onSelected,
  StockAvailability Function(VariationDraft? variation)? stockStatusForVariation,
}) {
  final widgets = <Widget>[];
  final effectiveSelections = <String, String>{...selectedValues};
  for (var index = 0; index < axes.length; index++) {
    final axis = axes[index];
    final availableValues = _availableVariationValues(
      product,
      axes,
      index,
      effectiveSelections,
    );
    if (availableValues.isEmpty) continue;

    var selected = cleanText(effectiveSelections[axis.id]);
    if (!availableValues.any((value) => _sameName(value, selected))) {
      selected = availableValues.first;
    }
    effectiveSelections[axis.id] = selected;

    widgets.add(_SelectorLabel(axis.label));
    widgets.add(const SizedBox(height: 8));
    widgets.add(
      Wrap(
        spacing: 8,
        runSpacing: 8,
        children: [
          for (final value in availableValues)
            _VariantChoiceChip(
              label: value,
              selected: _sameName(value, selected),
              onSelected: () => onSelected(axis, value),
              stockStatus: axis.id == 'size' && stockStatusForVariation != null
                  ? stockStatusForVariation(_selectedVariationDraft(
                      product,
                      axes,
                      {...effectiveSelections, axis.id: value},
                    ))
                  : null,
            ),
        ],
      ),
    );
    widgets.add(const SizedBox(height: 16));
  }
  return widgets;
}

List<String> _availableVariationValues(
  ProductDraft product,
  List<_VariationAxis> axes,
  int axisIndex,
  Map<String, String> selectedValues,
) {
  final axis = axes[axisIndex];
  final values = <String>[];
  for (final variation in product.variations) {
    var matchesPrevious = true;
    for (var index = 0; index < axisIndex; index++) {
      final previousAxis = axes[index];
      final selected = cleanText(selectedValues[previousAxis.id]);
      if (selected.isEmpty) continue;
      if (!_sameName(previousAxis.valueOf(variation), selected)) {
        matchesPrevious = false;
        break;
      }
    }
    if (!matchesPrevious) continue;

    final value = cleanText(axis.valueOf(variation));
    if (value.isEmpty || value == '-') continue;
    if (axis.values.any((known) => _sameName(known, value)) &&
        !values.any((known) => _sameName(known, value))) {
      values.add(value);
    }
  }
  return values;
}

Map<String, String> _effectiveVariationSelections(
  ProductDraft product,
  List<_VariationAxis> axes,
  Map<String, String> selectedValues,
) {
  final effective = <String, String>{...selectedValues};
  for (var index = 0; index < axes.length; index++) {
    final axis = axes[index];
    final availableValues = _availableVariationValues(
      product,
      axes,
      index,
      effective,
    );
    if (availableValues.isEmpty) {
      effective.remove(axis.id);
      continue;
    }

    final selected = cleanText(effective[axis.id]);
    if (!availableValues.any((value) => _sameName(value, selected))) {
      effective[axis.id] = availableValues.first;
    }
  }
  return effective;
}

VariationDraft? _selectedVariationDraft(
  ProductDraft product,
  List<_VariationAxis> axes,
  Map<String, String> selectedValues,
) {
  if (product.variations.isEmpty) return null;
  if (axes.isEmpty) return product.variations.first;
  final effectiveSelections = _effectiveVariationSelections(
    product,
    axes,
    selectedValues,
  );
  for (final variation in product.variations) {
    var matches = true;
    for (final axis in axes) {
      final selected = cleanText(effectiveSelections[axis.id]);
      if (selected.isEmpty) continue;
      if (!_sameName(axis.valueOf(variation), selected)) {
        matches = false;
        break;
      }
    }
    if (matches) return variation;
  }
  return null;
}

VariationDraft? _variationForCartItem(
  ProductDraft product,
  CustomerOrderItemDraft item,
) {
  final itemSize = cleanText(item.size);
  final itemFinish = cleanText(item.finish);
  final itemPrice = item.unitPrice;
  for (final variation in product.variations) {
    final variationSize = cleanText(variation.size);
    final structuredSize = cleanText(_structuredVariationSizeLabel(variation));
    final variationFinish = cleanText(variation.finish);
    final sizeMatches = itemSize.isEmpty ||
        _sameName(itemSize, variationSize) ||
        _sameName(itemSize, structuredSize);
    final finishMatches =
        itemFinish.isEmpty || _sameName(itemFinish, variationFinish);
    final priceMatches =
        itemPrice <= 0 || _priceNumber(variation.price) == itemPrice;
    if (sizeMatches && finishMatches && priceMatches) return variation;
  }
  for (final variation in product.variations) {
    final variationSize = cleanText(variation.size);
    final structuredSize = cleanText(_structuredVariationSizeLabel(variation));
    final variationFinish = cleanText(variation.finish);
    final sizeMatches = itemSize.isEmpty ||
        _sameName(itemSize, variationSize) ||
        _sameName(itemSize, structuredSize);
    final finishMatches =
        itemFinish.isEmpty || _sameName(itemFinish, variationFinish);
    if (sizeMatches && finishMatches) return variation;
  }
  return null;
}

String _variationLabelForDraft(VariationDraft? variation) {
  if (variation == null) return 'Select variant';
  final structuredSize = _structuredVariationSizeLabel(variation);
  final values = [
    variation.finish,
    structuredSize.isEmpty ? variation.size : structuredSize,
    if (structuredSize.isEmpty) variation.thickness,
  ].map(cleanText).where((value) => value.isNotEmpty && value != '-').toList();
  return values.isEmpty ? 'Base price' : values.join(' / ');
}

String _structuredVariationSizeLabel(VariationDraft variation) {
  final breadth = cleanText(variation.breadth);
  final length = cleanText(variation.length);
  final height = cleanText(variation.height);
  final thickness = cleanText(variation.thickness);
  if ([breadth, length, height].any((value) => value.isNotEmpty)) {
    final parts = <String>[];
    if (breadth.isNotEmpty) parts.add('B $breadth');
    if (length.isNotEmpty) parts.add('L $length');
    if (height.isNotEmpty) parts.add('H $height');
    if (thickness.isNotEmpty) parts.add('T $thickness');
    return parts.join(' x ');
  }
  return '';
}

bool _sameName(String left, String right) {
  return cleanText(left).toLowerCase() == cleanText(right).toLowerCase();
}

