String _bulkPasteFormatLabel(BulkPasteImportFormat format) {
  return switch (format) {
    BulkPasteImportFormat.longRows => 'Long rows detected',
    BulkPasteImportFormat.widePriceMatrix => 'Wide matrix detected',
    BulkPasteImportFormat.unknown => 'Format pending',
  };
}

BulkPasteImportResult _withAdditionalImportMessages(
  BulkPasteImportResult result,
  List<String> messages,
) {
  if (messages.isEmpty) return result;
  return BulkPasteImportResult(
    products: result.products,
    categories: result.categories,
    errors: [...result.errors, ...messages],
    format: result.format,
  );
}

List<String> _repositoryDuplicateWarnings(
  List<ProductDraft> existingProducts,
  List<ProductDraft> incomingProducts,
) {
  final warnings = <String>[];
  for (final product in incomingProducts) {
    if (normalizeInternalProductCode(product.internalProductCode).isNotEmpty) {
      continue;
    }
    final incomingName = cleanText(product.name).toLowerCase();
    if (incomingName.isEmpty) continue;
    final matches = existingProducts
        .where((existing) =>
            cleanText(existing.name).toLowerCase() == incomingName)
        .toList();
    if (matches.isEmpty) continue;
    final codes = matches
        .map((existing) =>
            normalizeInternalProductCode(existing.internalProductCode))
        .where((code) => code.isNotEmpty)
        .join(', ');
    warnings.add(codes.isEmpty
        ? 'Possible duplicate: ${product.name} already exists. Export Excel first if you want to update it.'
        : 'Possible duplicate: ${product.name} already exists as $codes. Export Excel first if you want to update it.');
  }
  return warnings;
}

